--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Action = {}
Action.__index = Action
Action.__type = "Action"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local log = require(utility.log)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

function Action.new(window, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        window = assert(window, "Missing argument #1 (Window expected)"),
        name = properties.name or properties.Name or "Action",
        icon = assert(properties.icon or properties.Icon, "Missing argument (Icon expected)"),
        callback = assert(properties.callback or properties.Callback, "Missing argument (Function expected)"),
        linkedTab = properties.linkedTab or properties.LinkedTab,
    }, Action)

    self.action = self.window:Create("Frame", {
        Name = self.name,
        BorderSizePixel = 0,

        LayoutOrder = -(properties.order or 0),
        -- 30px buttons with a 19px glyph and 6px between them, the header rhythm of
        -- SyncOfficialSpec's Rayfield Gen 3 Concept: the old 24px row read cramped next to the title
        Size = UDim2.fromOffset(30, 30),
        BackgroundTransparency = 1,

        Parent = self.window.actionContainer,
    })

    self.iconLabel = self.window:Create("ImageLabel", {
        -- Configurables
        Image = self.icon,

        Size = UDim2.fromOffset(19, 19),
        BorderSizePixel = 0,
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        BackgroundTransparency = 1,

        -- Animation
        ImageTransparency = 1, -- In = 0.6

        Parent = self.action,
    }, { ImageColor3 = "ActionColor" })

    -- the whole 30px square is the target: already finger-sized, and the 6px gap between
    -- neighbours keeps two buttons from sharing a tap
    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        TextTransparency = 1,

        Parent = self.action,
    })

    -- drop the icon back to its resting brightness, unless this action opens a tab that's
    -- currently selected (the settings cog stays lit while its page is open), or it reports
    -- itself lit some other way (the search action while the field is open)
    local function settleIcon()
        if not self.window:_settled() then
            return -- mid reveal/hide: those repaint the icons themselves, dont fight them
        end
        if self.linkedTab and self.window.selectedTab == self.linkedTab then
            return
        end
        if self.isLit and self:isLit() then
            return
        end
        variables.tweenService
            :Create(
                self.iconLabel,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { ImageTransparency = 0.6 }
            )
            :Play()
    end

    self.window:Connect(self.interact.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        task.spawn(function()
            local success, result = pcall(self.callback)
            if not success then
                log.warn(
                    `Rayfield encountered an error, with the callback for a {self.__type} component named '{self.name}':`
                )
                log.print(result)
            end
            -- undo the hover brighten now (the callback has run, so selectedTab is up to date),
            -- otherwise the icon stays lit until the mouse happens to move off it
            settleIcon()
        end)
    end)

    self.window:Connect(self.interact.MouseEnter, function()
        if not self.window:_interactive() then
            return -- window still revealing/hiding: dont light up mid-animation
        end
        variables.tweenService
            :Create(
                self.iconLabel,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { ImageTransparency = 0.2 }
            )
            :Play()
    end)

    self.window:Connect(self.interact.MouseLeave, settleIcon)

    return self
end

return Action
]=====]

sources["components/button"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Button = {}
Button.__index = Button
Button.__type = "Button"

-- Utility
local utility = script.Parent.Parent.utility
local constants = require(utility.constants)
-- the height of a one-line card (see constants.elementHeight)
local elementHeight = constants.elementHeight

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local locale = require(utility.locale)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

function Button.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Button",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        compact = tab.compact or false, -- true when the host is a Row
        locked = properties.locked or properties.Locked or false,

        callback = properties.callback or properties.Callback or function() end,

        -- Cheap destructive-action confirm: the first click just arms it (title flips to a
        -- "Are you sure?" prompt for a moment) and the callback only actually fires on a second
        -- click within confirmWindow seconds. No modal/extra frame needed for a "click twice to
        -- delete" style button.
        doubleClick = properties.doubleClick or properties.DoubleClick or false,
        confirmText = properties.confirmText or properties.ConfirmText or "Click again to confirm",
        _armed = false,
    }, Button)

    if self.compact then
        self:_buildCompact()
    else
        self:_buildFull()
    end

    self.lockIcon = self.window:_buildLockIcon(self.main)
    -- compact mode has no separate self.container - icon/title parent straight to self.interact
    self.prohibitedIcon = self.window:_buildProhibitedIcon(self.container or self.interact)
    self:_applyLocked(false)
    self.window:_wireTooltip(self)

    -- Descriptions don't belong on a compact row element.
    if self.description and not self.compact then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- how long an armed double-click button waits for its confirming second click before
-- reverting to its normal title
local confirmWindow = 3

-- callback + red error-flash, shared by both layouts. A plain button just runs the callback; a
-- doubleClick button's first click only arms it (see _arm) and returns without calling out -
-- the second click within confirmWindow disarms it and runs the callback like normal.
function Button:_runCallback()
    if self.doubleClick and not self._armed then
        self:_arm()
        return
    end
    if self.doubleClick then
        self:_disarm()
    end
    self.window:_runGuarded(self, self.callback)
end

-- Swaps the title to confirmText and starts the revert timer. Generation-stamped so an earlier
-- arm's delayed revert can't fire late and stomp a disarm/re-arm that happened after it.
function Button:_arm()
    self._armed = true
    self._originalTitle = self.title.Text
    self.title.Text = locale.resolve(self.confirmText)
    self._armGeneration = (self._armGeneration or 0) + 1
    local generation = self._armGeneration
    task.delay(confirmWindow, function()
        if self._armed and self._armGeneration == generation then
            self:_disarm()
        end
    end)
end

function Button:_disarm()
    if not self._armed then
        return
    end
    self._armed = false
    if self._originalTitle then
        self.title.Text = self._originalTitle
        self._originalTitle = nil
    end
end

-- full-width: title/icon left, width-bounce on press
function Button:_buildFull()
    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, elementHeight),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        -- Animation
        BackgroundTransparency = 1, -- In = 0

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.main)

    self.container = self.window:Create("Frame", {
        BorderSizePixel = 0,

        Parent = self.main,
        Size = UDim2.new(0, 170, 0, 16),
        Position = UDim2.new(0, constants.elementInset, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
    })

    self.containerLayout = self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, constants.elementIconGap),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(constants.elementIconSize, constants.elementIconSize),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            -- Animations
            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),

        Size = UDim2.fromOffset(250, 16),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        AutomaticSize = Enum.AutomaticSize.X,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        -- Animation
        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        TextTransparency = 1,

        Parent = self.main,
    })

    self.window:_fitRowTitle(self, constants.elementInset) -- nothing on the right but the row's own padding
    self.window:_wireElementHover(self)

    -- press: ghost the stroke + squeeze the width around the callback
    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        if self.locked then
            return
        end
        hapticEngine.click()
        soundEngine.click()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()
        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -26, 0, elementHeight) }
            )
            :Play()

        self:_runCallback()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -20, 0, elementHeight) }
            )
            :Play()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- compact (row): content-sized, centred icon+title, no width-bounce
function Button:_buildCompact()
    local window = self.window

    self.main, self.stroke, self.interact = window:_buildCompactRow(self.tab, self.name)
    self.hoverOverlay = self.interact

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 16),
        PaddingRight = UDim.new(0, 16),

        Parent = self.interact,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        Padding = UDim.new(0, 6),

        Parent = self.interact,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(constants.elementIconSize, constants.elementIconSize),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            LayoutOrder = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.interact,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.interact,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- grows to its text, shrinks + ellipsizes when the row's tight
    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    self.window:_wireElementHover(self)

    -- press: ghost the stroke around the callback
    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        if self.locked then
            return
        end
        hapticEngine.click()
        soundEngine.click()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()

        self:_runCallback()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

function Button:_applyLocked(animate)
    self.window:_applyLockedVisual(self, animate)
end

function Button:SetLocked(locked)
    locked = locked and true or false
    if locked == self.locked then
        return
    end
    self.locked = locked
    self:_applyLocked(true)
end

-- Lock/Unlock/IsLocked: the shared naming lockable.luau gives every other locking-capable
-- element - aliased into this component's own pre-existing SetLocked/padlock-icon dimming
-- rather than the mixin's scrim (see lockable.luau's own header comment). `reason` isn't
-- supported here.
function Button:Lock()
    self:SetLocked(true)
end
function Button:Unlock()
    self:SetLocked(false)
end
function Button:IsLocked(): boolean
    return self.locked == true
end

function Button:_setShown(shown, animate)
    if shown then
        -- _revealCommon is locked-aware (see window.luau) - it already dims title/icon
        -- correctly by itself, no second tween needed to fix it up afterward
        self.window:_revealCommon(self, animate)
    else
        self.window:_hideCommon(self, animate)
    end
end

-- Room the compact button needs before its label would clip: side padding + icon
-- (and its gap) if shown + the title text. A horizontal group uses this to wrap.
function Button:_minWidth()
    local w = 32 -- interact padding, 16 each side
    if self.icon then
        w += constants.elementIconSize + 6 -- the icon, and the 6px gap to the title
    end
    w += functions.textWidth(self.window.theme.Font, 16, self.name)
    return w
end

-- Live status line - see Toggle:SetStatus's own comment, same reasoning and same reused
-- descriptor slot, just for a button (e.g. "Import" reporting "Imported 12/12" after it runs).
function Button:SetStatus(text)
    if self.compact then
        return -- no room for a status line in a row layout
    end
    if not self.descriptor then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = text })
        self.descriptor.main.LayoutOrder = self.main.LayoutOrder + 1
        if not self.window.hidden then
            self.window:_reveal(self.descriptor.titleLabel, { TextTransparency = 0.7 }, false)
        end
    else
        self.descriptor.description = text
        self.descriptor.titleLabel.Text = text
    end
end

moveable(Button)

return Button
]=====]

sources["components/changelog"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 6: an inline "Update Log" card - a title + version/date header, a divider, then a list
-- of entries each tagged ADDED/FIXED/CHANGED/REMOVED (or any custom tag) in a semantic colour.
-- Static once built (no add/remove API) - it's meant to be authored once per release, the same
-- way the devlog text itself is.

local Changelog = {}
Changelog.__index = Changelog
Changelog.__type = "Changelog"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local moveable = require(utility.moveable)
local locale = require(utility.locale)

-- Semantic tag colours, git-status-log convention: green add, blue fix, amber change, red remove.
-- Kept soft/pastel on purpose - the original fully-saturated set read as neon against the card.
-- A custom tag not in this table falls back to the theme's own accent colour.
local tagColors = {
    ADDED = Color3.fromRGB(125, 209, 155),
    FIXED = Color3.fromRGB(130, 179, 235),
    CHANGED = Color3.fromRGB(230, 178, 110),
    REMOVED = Color3.fromRGB(224, 130, 128),
}

local rowGap = 10
local entryGap = 14
local prefixWidth = 80
local dotSize = 6

function Changelog.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Update Log",
        version = properties.version or properties.Version,
        date = properties.date or properties.Date,
        entries = properties.entries or properties.Entries or {},
    }, Changelog)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)

    self.window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 20),
        PaddingRight = UDim.new(0, 20),
        PaddingTop = UDim.new(0, 16),
        PaddingBottom = UDim.new(0, 16),

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, rowGap),

        Parent = self.main,
    })

    self:_buildHeader()
    self:_buildDivider()
    self._rows = {}
    for index, entry in self.entries do
        self:_buildEntry(entry, index)
    end

    return self
end

function Changelog:_buildHeader()
    local header = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 22),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 1,

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.SpaceBetween,

        Parent = header,
    })

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 22),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 18,
        TextXAlignment = Enum.TextXAlignment.Left,

        TextTransparency = 1, -- In = 0

        Parent = header,
    }, { TextColor3 = "ContentColor", FontFace = "TitleFont" })

    if (self.version and self.version ~= "") or (self.date and self.date ~= "") then
        local parts = {}
        if self.version and self.version ~= "" then
            table.insert(parts, self.version)
        end
        if self.date and self.date ~= "" then
            table.insert(parts, self.date)
        end
        self.meta = self.window:Create("TextLabel", {
            Text = locale.t(table.concat(parts, "  \u{00B7}  ")),
            Size = UDim2.fromOffset(0, 16),
            AutomaticSize = Enum.AutomaticSize.X,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 13,
            TextXAlignment = Enum.TextXAlignment.Right,

            TextTransparency = 1, -- In = 0.5

            Parent = header,
        }, { TextColor3 = "PlaceholderColor", FontFace = "Font" })
    end
end

function Changelog:_buildDivider()
    self.divider = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 1),
        BorderSizePixel = 0,
        LayoutOrder = 2,

        BackgroundTransparency = 1, -- In = 0.9

        Parent = self.main,
    }, { BackgroundColor3 = "SurfaceStroke" })
end

-- One row: a fixed-width colour tag left, the description filling the rest. Wraps onto its own
-- height if the description needs more than one line.
function Changelog:_buildEntry(entry, order)
    entry = if typeof(entry) == "table" then entry else { text = tostring(entry) }
    local tag = string.upper(tostring(entry.tag or entry.Tag or ""))
    local color = tagColors[tag] or self.window.theme.AccentColor
    local text = entry.text or entry.Text or entry.description or entry.Description or ""

    local row = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 20),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 2 + order,

        Parent = self.main,
    })

    -- fixed-width prefix so every row's description starts at the same x regardless of how
    -- long its own tag word is - dot + tag flow left inside it via their own mini row
    local prefix = self.window:Create("Frame", {
        Size = UDim2.fromOffset(prefixWidth, 20),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = row,
    })

    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Padding = UDim.new(0, 6),

        Parent = prefix,
    })

    local dot = self.window:Create("Frame", {
        Size = UDim2.fromOffset(dotSize, dotSize),
        BackgroundColor3 = color,
        BorderSizePixel = 0,

        BackgroundTransparency = 1, -- In = 0

        Parent = prefix,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = dot })

    local tagLabel = self.window:Create("TextLabel", {
        Text = locale.t(tag),
        Size = UDim2.fromOffset(0, 20),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 12,
        Font = Enum.Font.GothamBold,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextColor3 = color,

        TextTransparency = 1, -- In = 0

        Parent = prefix,
    })

    local desc = self.window:Create("TextLabel", {
        Text = locale.t(text),
        Position = UDim2.fromOffset(prefixWidth + entryGap, 0),
        Size = UDim2.new(1, -(prefixWidth + entryGap), 0, 20),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 14,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,

        TextTransparency = 1, -- In = 0

        Parent = row,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    table.insert(self._rows, { row = row, dot = dot, tagLabel = tagLabel, desc = desc })
end

function Changelog:_setShown(shown, animate)
    local w = self.window
    w:_reveal(self.stroke, { Transparency = if shown then w.theme.ElementStrokeTransparency else 1 }, animate)
    w:_reveal(self.main, { BackgroundTransparency = if shown then (w.theme.ElementTransparency or 0) else 1 }, animate)
    w:_reveal(self.title, { TextTransparency = if shown then 0 else 1 }, animate)
    if self.meta then
        w:_reveal(self.meta, { TextTransparency = if shown then 0.5 else 1 }, animate)
    end
    w:_reveal(self.divider, { BackgroundTransparency = if shown then 0.9 else 1 }, animate)
    for _, entry in self._rows do
        w:_reveal(entry.dot, { BackgroundTransparency = if shown then 0 else 1 }, animate)
        w:_reveal(entry.tagLabel, { TextTransparency = if shown then 0 else 1 }, animate)
        w:_reveal(entry.desc, { TextTransparency = if shown then 0 else 1 }, animate)
    end
end

moveable(Changelog)

return Changelog
]=====]

sources["components/chart"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A small chart: gold per hour, DPS, mobs killed a minute - the numbers a hub already tracks,
-- drawn instead of printed. Two shapes, both fed the same way:
--
--   local chart = tab:CreateChart({ name = "Gold / hour", mode = "line", maxPoints = 60 })
--   chart:Push(currentRate)   -- every tick; the oldest point falls off the left
--
-- The line is drawn as one thin rotated frame per segment, the bars as one frame per point. No
-- external library, no images: Roblox has no line primitive, and a rotated frame between two
-- points IS a line segment. Costs one instance per point either way, which is why maxPoints is
-- capped rather than unbounded - a hub pushing once a second all session would otherwise grow
-- the instance count forever.
--
-- The scale follows the data (with `min`/`max` to pin it), so a flat series doesn't draw as a
-- flat line at the bottom of an empty box - a series that never moves is drawn through the
-- middle, which is what "nothing is changing" should look like. Bars stand on zero.
--
-- The look is the Gen 3 Concept's (SyncOfficialSpec's Rayfield Gen 3 Concept, MIT): a bright 3px
-- line with a white dot on every point over a deep gradient field, two faint rules, a bold header
-- whose value reads with thousands separators; rounded gradient bars with optional labels under
-- them. The motion - the line drawing itself in, the series sliding along, the rolling value, the
-- breathing newest point, the reading under the pointer - stays this library's own.

local Chart = {}
Chart.__index = Chart
Chart.__type = "Chart"

local utility = script.Parent.Parent.utility
local constants = require(utility.constants)
local variables = require(utility.variables)
local functions = require(utility.functions)
local locale = require(utility.locale)
local image = require(utility.image)
local odometer = require(utility.odometer)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)

local sidePadding = 17
local headerTop = 13
local headerHeight = 18
local plotGap = 13
local bottomPadding = 14
local defaultHeight = 94
local minHeight = 40
local defaultMaxPoints = 48
local lineThickness = 3
-- a bar is most of its slot, never a sliver and never a slab
local barShare, minBarWidth, maxBarWidth = 0.72, 6, 46
local barCorner = 6
-- room under the bars for their labels, when they have any
local labelRoom = 16
-- the plot keeps a little air above its highest point and below its lowest, so a dot on either
-- end sits whole inside it instead of being cut by the clip
local plotPadTop, plotPadBottom = 10, 12
-- white dots on every point, while the points are far enough apart to take them
local pointDotSize = 10
local pointDotMinStep = 12
-- the first point's dot needs room on the left the way the newest one does on the right
local leftRoom = 5
local gridTransparency = 0.93
-- The drawing's layers, bottom to top. The field and the line used to share one: whichever was made
-- last drew on top, and the field's columns - made after the line - laid their dark stepped tops
-- over it, so the line looked pixelated along its underside.
local layers = { field = 1, line = 2, halo = 2, point = 3, dot = 4 }

-- The deep field under a line, drawn as thin columns sampled along it (see _redrawFill), each one
-- fading from under the line down to the floor.
local fillTransparency = 0.12
local fillColumnWidth = 3
local maxFillColumns = 128
-- The live dot at the newest point, and the halo that breathes around it.
local dotSize = pointDotSize
local haloRest, haloPeak = 16, 24
-- The room the newest point's dot and halo need on the right. Without it the dot sat centred on the
-- plot's own edge, so the clip cut it in half - reported as the dot "ending up outside".
local dotRoom = 11

local drawInfo = TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
-- a new point slides the whole series left by one step instead of teleporting it
local slideInfo = TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local haloInfo = TweenInfo.new(1.1, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true)
-- Its entrance, each time its page comes on screen - the Gen 3 Concept's: the line wiped in from
-- the left, the dots popping up as it reaches them, the field rising off the floor behind it; bars
-- growing up one after another.
local entranceTime = 0.75
local entranceWipe = TweenInfo.new(entranceTime, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
local dotPopInfo = TweenInfo.new(0.42, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
local fillRiseInfo = TweenInfo.new(0.55, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local barGrowInfo = TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local barStagger = 0.05

-- 12400 -> "12,400"
local function commafy(text: string): string
    local sign = ""
    if string.sub(text, 1, 1) == "-" then
        sign, text = "-", string.sub(text, 2)
    end
    local whole, rest = string.match(text, "^(%d+)(.*)$")
    if not whole then
        return sign .. text
    end
    whole = string.reverse((string.gsub(string.reverse(whole), "(%d%d%d)", "%1,")))
    if string.sub(whole, 1, 1) == "," then
        whole = string.sub(whole, 2)
    end
    return sign .. whole .. rest
end

-- The accent's two companions: a brighter one for the line, a deeper one for the field under it -
-- the Concept's AccentSoft and AccentDark, derived from whatever accent the chart is drawn in.
local function softOf(color: Color3): Color3
    local h, sat, v = color:ToHSV()
    return Color3.fromHSV(h, sat * 0.86, math.min(v * 1.25, 1))
end

local function deepOf(color: Color3): Color3
    local h, sat, v = color:ToHSV()
    return Color3.fromHSV(h, sat * 0.83, v * 0.62)
end

-- A point on the Catmull-Rom curve through p1 and p2 (p0 and p3 bend it), t from 0 to 1.
local function catmull(p0: number, p1: number, p2: number, p3: number, t: number): number
    local t2, t3 = t * t, t * t * t
    return 0.5 * (2 * p1 + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 + (-p0 + 3 * p1 - 3 * p2 + p3) * t3)
end

-- a smooth line's pieces between two points: short enough to read as a curve, few enough that a
-- long series stays a few hundred frames at most
local smoothPieceWidth, minSmoothPieces, maxSmoothPieces = 3, 6, 36
-- How far each piece of a line runs past its own ends, under its neighbours. One pixel closed the
-- hairline at a straight line's joins; a curve's pieces are only a few pixels long, and there the
-- soft edge of every rounded end showed through as a bead - the line looked grainy.
local straightOverlap, smoothOverlap = 1, 3

local function clampNumber(value, fallback: number): number
    local number = tonumber(value)
    return if number and number == number and number ~= math.huge and number ~= -math.huge then number else fallback
end

function Chart.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local mode = string.lower(tostring(properties.mode or properties.Mode or "line"))
    if mode ~= "bar" then
        mode = "line"
    end

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Chart",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = true, -- a live series is not state to restore into a new session

        mode = mode,
        height = math.max(clampNumber(properties.height or properties.Height, defaultHeight), minHeight),
        -- How many points are kept. The oldest falls off the left as new ones arrive.
        maxPoints = math.clamp(
            math.floor(clampNumber(properties.maxPoints or properties.MaxPoints, defaultMaxPoints)),
            2,
            240
        ),
        -- Pin either end of the scale, or leave both to follow the data.
        min = tonumber(properties.min or properties.Min),
        max = tonumber(properties.max or properties.Max),
        -- What the header's current value reads as: a formatter, or nil for the number with its
        -- prefix, suffix and decimals around it (and thousands separators)
        format = properties.format or properties.Format,
        prefix = tostring(properties.prefix or properties.Prefix or ""),
        suffix = tostring(properties.suffix or properties.Suffix or ""),
        decimals = math.clamp(math.floor(clampNumber(properties.decimals or properties.Decimals, 0)), 0, 6),
        color = properties.color or properties.Color,
        -- The baseline under the plot; off for a chart that is all line and no frame.
        showBaseline = functions.readBool(properties, "baseline", true),
        -- The number on the right of the header, tracking the newest point.
        showValue = functions.readBool(properties, "showValue", true),
        -- What the top and the bottom of the plot are worth, written on its left edge. Off by
        -- default: the header already says what the newest point is worth, and the reading under
        -- the pointer says the rest.
        showScale = functions.readBool(properties, "scale", false),
        -- A curve through the points instead of straight lines between them.
        smooth = functions.readBool(properties, "smooth", false),
        -- A white dot on every point of a line - on by default for a straight line, off for a
        -- smooth one, whose points are not corners to mark.
        showDots = functions.readBool(properties, "dots", not functions.readBool(properties, "smooth", false)),

        points = {},
        labels = {}, -- a bar's name under it, by index
        dots = {}, -- the white dots on a line's points
        _segments = {}, -- each drawn segment's two ends, for _clipToView
        marks = {}, -- the drawn pieces: segments for a line, bars for a bar chart
        joints = {}, -- the welds where two segments meet
        fills = {}, -- the shading under a line
    }, Chart)

    self:_readSeries(properties.values or properties.Values or properties.points or properties.Points or {})
    local labels = properties.labels or properties.Labels
    if type(labels) == "table" then
        for index, label in labels do
            self.labels[index] = tostring(label)
        end
    end

    self:_build()
    self:_redraw(false)

    self.window:_onPageShown(function(tab)
        if not self._shown or not tab.tabPage then
            return
        end
        -- on that page, however deep (a group, a collapsible)
        local node = self.main.Parent
        while node and node ~= tab.tabPage do
            node = node.Parent
        end
        if node then
            self:_entrance()
        end
    end)

    self.window:_wireTooltip(self)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- Numbers, or { value = n, label = "Mon" } for a bar with a name under it.
function Chart:_readSeries(values)
    local points, labels = {}, {}
    for _, item in (if type(values) == "table" then values else {}) do
        local number, label
        if type(item) == "table" then
            number = tonumber(item.value or item.Value)
            label = item.label or item.Label
        else
            number = tonumber(item)
        end
        if number then
            table.insert(points, number)
            if label ~= nil then
                labels[#points] = tostring(label)
            end
        end
    end
    while #points > self.maxPoints do
        table.remove(points, 1)
        local shifted = {}
        for index, label in labels do
            if index > 1 then
                shifted[index - 1] = label
            end
        end
        labels = shifted
    end
    self.points = points
    if next(labels) ~= nil then
        self.labels = labels
    end
end

-- Whether the bars have names to write under them.
function Chart:_hasLabels(): boolean
    return self.mode == "bar" and next(self.labels) ~= nil
end

function Chart:_cardHeight(): number
    return headerTop
        + headerHeight
        + plotGap
        + self.height
        + bottomPadding
        + (if self:_hasLabels() then labelRoom else 0)
end

function Chart:_build()
    local window = self.window

    self.main = window:Create("Frame", {
        Name = self.name,
        Size = UDim2.new(1, -20, 0, self:_cardHeight()),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = window:StyleElementBody(self.main)

    local titleLeft = sidePadding
    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Size = UDim2.fromOffset(constants.elementIconSize, constants.elementIconSize),
            Position = UDim2.new(0, sidePadding, 0, headerTop + 1),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.main,
        }, { ImageColor3 = "ContentColor" })
        image.assign(self.iconLabel, "Image", self.icon)
        titleLeft += constants.elementIconSize + constants.elementIconGap
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.new(1, -(titleLeft + sidePadding + 90), 0, headerHeight),
        Position = UDim2.new(0, titleLeft, 0, headerTop),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,

        TextTransparency = 1, -- In = 0

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "TitleFont" })

    -- the newest point, in words, for the times a shape is not precise enough
    self.valueLabel = window:Create("TextLabel", {
        Text = "",
        Size = UDim2.fromOffset(90, 20),
        Position = UDim2.new(1, -sidePadding, 0, headerTop - 2),
        AnchorPoint = Vector2.new(1, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 20,
        TextXAlignment = Enum.TextXAlignment.Right,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Visible = self.showValue,

        TextTransparency = 1, -- In = 0.1

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "TitleFont" })

    -- The number itself rolls: the plain label stays as the value of record (and as what a spec
    -- reads), while the odometer is what the player sees change.
    if self.showValue then
        self.valueLabel.TextTransparency = 1
        self.valueHost = window:Create("Frame", {
            Name = "Value",
            Size = UDim2.fromOffset(0, 20),
            Position = UDim2.new(1, -sidePadding, 0, headerTop - 2),
            AnchorPoint = Vector2.new(1, 0),
            AutomaticSize = Enum.AutomaticSize.X,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,

            Parent = self.main,
        })
        self.valueOdo = odometer.new(window, self.valueHost, {
            textSize = 20,
            alignment = Enum.HorizontalAlignment.Right,
            transparency = 1, -- revealed on show, like every other piece here
            duration = 0.32,
            font = "TitleFont",
        })
    end

    -- the names under the bars, when they have any: outside the plot, since the plot clips
    self.labelRow = window:Create("Frame", {
        Name = "Labels",
        Size = UDim2.new(1, -(sidePadding * 2), 0, 12),
        Position = UDim2.new(0, sidePadding, 0, headerTop + headerHeight + plotGap + self.height + 3),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.main,
    })
    self.labelLabels = {}

    -- everything drawn lives in here, so a redraw only ever touches this subtree
    self.plot = window:Create("Frame", {
        Name = "Plot",
        Size = UDim2.new(1, -(sidePadding * 2), 0, self.height),
        Position = UDim2.new(0, sidePadding, 0, headerTop + headerHeight + plotGap),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ClipsDescendants = true,

        Parent = self.main,
    })

    -- A faint rule across the middle of the plot, and the baseline under it. Without them a line
    -- has nothing to be high or low against; with them the same drawing reads as a measurement.
    self.gridLines = {}
    for _ = 1, 1 do
        local line = window:Create("Frame", {
            Name = "Grid",
            Size = UDim2.new(1, 0, 0, 1),
            Position = UDim2.fromScale(0, 0.5),
            BorderSizePixel = 0,
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),

            BackgroundTransparency = 1, -- In = gridTransparency

            Parent = self.plot,
        }, { BackgroundColor3 = "ContentColor" })
        table.insert(self.gridLines, line)
    end

    self.baseline = window:Create("Frame", {
        Name = "Baseline",
        Size = UDim2.new(1, 0, 0, 1),
        Position = UDim2.new(0, 0, 1, -1),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        Visible = self.showBaseline,

        BackgroundTransparency = 1, -- In = 0.9

        Parent = self.plot,
    }, { BackgroundColor3 = "ContentColor" })

    -- what the top and the bottom of the plot are worth, so the shape has numbers attached
    local function scaleLabel(anchorY)
        return window:Create("TextLabel", {
            Text = "",
            Size = UDim2.new(0, 60, 0, 12),
            Position = UDim2.new(0, 0, anchorY, if anchorY == 0 then 1 else -2),
            AnchorPoint = Vector2.new(0, anchorY),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,

            TextTransparency = 1, -- In = 0.72
            Visible = self.showScale,

            Parent = self.plot,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })
    end
    self.maxLabel = scaleLabel(0)
    self.minLabel = scaleLabel(1)

    -- Everything that moves with the series lives in here: a new point slides this left by one
    -- step, so the line travels rather than jumping (the plot clips, so it slides in from the edge).
    self.canvas = window:Create("Frame", {
        Name = "Series",
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.plot,
    })

    self.halo = window:Create("Frame", {
        Name = "Halo",
        Size = UDim2.fromOffset(haloRest, haloRest),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        Visible = false,
        ZIndex = layers.halo,

        BackgroundTransparency = 1, -- In = 0.82

        Parent = self.canvas,
    })
    window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = self.halo })

    self.dot = window:Create("Frame", {
        Name = "Dot",
        Size = UDim2.fromOffset(dotSize, dotSize),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        Visible = false,
        ZIndex = layers.dot,

        BackgroundTransparency = 1, -- In = 0

        Parent = self.canvas,
    })
    window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = self.dot })

    -- A reading under the pointer: the line the pointer is on, and what that point is worth. A
    -- chart without one can only be looked at; with one it can be asked a question.
    self.guide = window:Create("Frame", {
        Name = "Guide",
        Size = UDim2.new(0, 1, 1, 0),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        Visible = false,

        BackgroundTransparency = 1, -- In = 0.8 while hovered

        Parent = self.canvas,
    }, { BackgroundColor3 = "ContentColor" })

    self.readout = window:Create("TextLabel", {
        Name = "Readout",
        -- above the line, its dots and the pointer sheet
        ZIndex = 6,
        Text = "",
        Size = UDim2.fromOffset(52, 18),
        AnchorPoint = Vector2.new(0.5, 0),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        TextSize = 12,
        Visible = false,

        BackgroundTransparency = 1, -- In = 0.12 while hovered
        TextTransparency = 1,

        Parent = self.plot,
        -- StatBackground, not ElementGradient: the readout needs one flat colour behind it, and that
        -- is the key every theme defines for exactly that
    }, { BackgroundColor3 = "StatBackground", TextColor3 = "ContentColor", FontFace = "Font" })
    window:Create("UICorner", { CornerRadius = UDim.new(0, 6), Parent = self.readout })
    self.readoutStroke = window:Create("UIStroke", {
        Thickness = 1,
        Transparency = 1,

        Parent = self.readout,
    }, { Color = "ElementStroke" })

    -- A sheet over the whole plot, to read the pointer from. The plot itself cannot: every piece
    -- drawn into it sits on top, and the topmost object under the pointer is the one that gets the
    -- move, so the segments and bars swallowed it.
    self.hoverCatcher = window:Create("TextButton", {
        Name = "Hover",
        Text = "",
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        AutoButtonColor = false,
        ZIndex = 5,

        Parent = self.plot,
    })

    window:ConnectFor(self, self.hoverCatcher.MouseMoved, function(x)
        self:_hoverAt(x)
    end)
    window:ConnectFor(self, self.hoverCatcher.MouseLeave, function()
        self:_clearHover()
    end)

    self.emptyLabel = window:Create("TextLabel", {
        Text = locale.t("No data yet."),
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 13,
        TextXAlignment = Enum.TextXAlignment.Center,

        TextTransparency = 1, -- In = 0.6 while there is nothing to draw

        Parent = self.plot,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- the plot's real width decides how many pixels a point is worth
    window:ConnectFor(self, self.plot:GetPropertyChangedSignal("AbsoluteSize"), function()
        self:_redraw(false)
    end)
    -- and where it sits on screen decides how much of the line the page shows
    window:ConnectFor(self, self.plot:GetPropertyChangedSignal("AbsolutePosition"), function()
        if self.mode == "line" and next(self._segments) ~= nil then
            self:_clipToView()
        end
    end)
end

function Chart:_accent(): Color3
    return self.color or self.window.theme.AccentColor
end

-- The scale the points are drawn against: the data's own range, either end pinned by min/max, and
-- never zero-height (a series that never moves draws through the middle). Bars stand on zero: a
-- bar's height IS its value, so a scale starting anywhere else would lie about it.
function Chart:_range(): (number, number)
    local low, high
    for _, value in self.points do
        low = if low == nil or value < low then value else low
        high = if high == nil or value > high then value else high
    end
    if self.mode == "bar" and low ~= nil then
        low = math.min(low, 0)
        high = math.max(high, 0)
    end
    low = self.min or low or 0
    high = self.max or high or 1
    if high <= low then
        local pad = math.max(math.abs(high) * 0.1, 1)
        low, high = low - pad, high + pad
    end
    return low, high
end

-- Reuse the pieces already drawn: a chart pushed to once a second would otherwise create and
-- destroy its whole subtree every second.
function Chart:_mark(index: number)
    local mark = self.marks[index]
    if mark then
        return mark
    end
    mark = self.window:Create("Frame", {
        Name = "Mark",
        BorderSizePixel = 0,
        BackgroundColor3 = self:_accent(),
        ZIndex = layers.line,
        AnchorPoint = if self.mode == "bar" then Vector2.new(0.5, 1) else Vector2.new(0.5, 0.5),

        BackgroundTransparency = 1, -- In = 0

        Parent = self.canvas,
    })
    if self.mode == "bar" then
        -- rounded, and a shade deeper towards its foot, the Concept's bar
        self.window:Create("UICorner", { CornerRadius = UDim.new(0, barCorner), Parent = mark })
        self.window:Create("UIGradient", {
            Rotation = 90,
            Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(178, 178, 178)),
            Parent = mark,
        })
    else
        -- a rounded cap on each segment closes the notch two sloped rectangles leave at their joint
        self.window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = mark })
    end
    self.marks[index] = mark
    return mark
end

-- The field under a line, as thin columns sampled ALONG the line rather than one per point: a
-- column per point would step in visible stairs at this width, and the sampled ones read as a
-- smooth field. Each fades from under the line down to the floor. Capped, so a 240-point chart
-- does not become 240 instances of shading.
function Chart:_fill(index: number)
    local fill = self.fills[index]
    if fill then
        return fill
    end
    fill = self.window:Create("Frame", {
        Name = "Fill",
        AnchorPoint = Vector2.new(0, 1),
        BorderSizePixel = 0,
        ZIndex = layers.field,
        BackgroundColor3 = deepOf(self:_accent()),

        BackgroundTransparency = 1, -- In = fillTransparency

        Parent = self.canvas,
    })
    self.window:Create("UIGradient", {
        Rotation = 90,
        Transparency = NumberSequence.new(0, 0.78),
        Parent = fill,
    })
    self.fills[index] = fill
    return fill
end

-- Columns on whole pixels, each starting exactly where the last one ended. They used to be a
-- pixel wider than their step so no hairline showed between them, but at this transparency the
-- overlap painted twice - the field read as vertical stripes.
function Chart:_redrawFill(left: number, right: number, height: number, yAt)
    local used = 0
    local width = right - left
    if self.mode == "line" and #self.points > 1 and width > 0 then
        local columns = math.clamp(math.floor(width / fillColumnWidth), 1, maxFillColumns)
        local columnWidth = width / columns
        for index = 1, columns do
            local fill = self:_fill(index)
            local x0 = math.floor(left + (index - 1) * columnWidth + 0.5)
            local x1 = math.floor(left + index * columnWidth + 0.5)
            local y = yAt((x0 + x1) / 2)
            local target = UDim2.fromOffset(math.max(x1 - x0, 1), math.max(height - y, 0))
            fill.Position = UDim2.fromOffset(x0, height)
            if self._animatingFill and fill.Visible then
                variables.tweenService:Create(fill, drawInfo, { Size = target }):Play()
            else
                fill.Size = target
            end
            fill.Visible = true
        end
        used = columns
    end
    for index = used + 1, #self.fills do
        self.fills[index].Visible = false
    end
end

-- The newest point, marked: a dot with a halo breathing around it, so a live chart looks live.
function Chart:_redrawDot(x: number, y: number, visible: boolean)
    self.dot.Visible = visible
    self.halo.Visible = visible
    if not visible then
        return
    end
    self.dot.Position = UDim2.fromOffset(math.floor(x + 0.5), math.floor(y + 0.5))
    self.halo.Position = self.dot.Position
    if not self._haloPlaying and self._shown then
        self._haloPlaying = true
        variables.tweenService:Create(self.halo, haloInfo, { Size = UDim2.fromOffset(haloPeak, haloPeak) }):Play()
    end
end

-- Where a line's points sit across the plot: from leftRoom in to dotRoom short of the right edge,
-- so the dots on both ends sit whole inside the clip.
function Chart:_lineStep(width: number, count: number): number
    local usable = math.max(width - dotRoom - leftRoom, 1)
    return if count > 1 then usable / (count - 1) else usable
end

-- Which point the pointer is over, and the guide/readout that says so.
function Chart:_hoverAt(absoluteX: number)
    local width = self.plot.AbsoluteSize.X
    local count = #self.points
    if count == 0 or width <= 0 or not self._shown then
        return
    end

    local localX = math.clamp(absoluteX - self.plot.AbsolutePosition.X, 0, width)
    local index, centre
    if self.mode == "bar" then
        local slot = width / count
        index = math.clamp(math.floor(localX / slot) + 1, 1, count)
        centre = (index - 0.5) * slot
    else
        local step = self:_lineStep(width, count)
        index = math.clamp(math.floor((localX - leftRoom) / step + 0.5) + 1, 1, count)
        centre = leftRoom + (index - 1) * step
    end

    if self._hoverIndex ~= index then
        self._hoverIndex = index
        self:_paintMarks(true) -- the hovered bar or point stands out from the rest
    end

    local guidePosition = UDim2.fromOffset(math.floor(centre), 0)
    if self.guide.Visible then
        variables.tweenService:Create(self.guide, drawInfo, { Position = guidePosition }):Play()
    else
        self.guide.Position = guidePosition
    end
    self.guide.Visible = true
    self.readout.Visible = true
    self.readout.Text = self:_readable(self.points[index])
    self.readout.Size =
        UDim2.fromOffset(math.max(functions.textWidth(self.window.theme.Font, 12, self.readout.Text) + 14, 40), 18)
    local half = self.readout.Size.X.Offset / 2
    -- Beside the point it reads rather than pinned to the plot's top edge: pinned, a point at the
    -- top of the scale sat right on it and its dot covered the number. Above the point, clear of
    -- a hovered dot; below it when the point is too close to the top for that.
    local pointY = self._pointY and self._pointY[index] or 0
    local readoutHeight = self.readout.Size.Y.Offset
    local clearance = pointDotSize / 2 + 6
    local y = pointY - clearance - readoutHeight
    if y < 0 then
        y = pointY + clearance
    end
    y = math.clamp(y, 0, math.max(self.plot.AbsoluteSize.Y - readoutHeight, 0))
    self.readout.Position =
        UDim2.new(0, math.clamp(math.floor(centre), half, math.max(width - half, half)), 0, math.floor(y))

    variables.tweenService:Create(self.guide, drawInfo, { BackgroundTransparency = 0.8 }):Play()
    variables.tweenService
        :Create(self.readout, drawInfo, { BackgroundTransparency = 0.12, TextTransparency = 0.05 })
        :Play()
    variables.tweenService:Create(self.readoutStroke, drawInfo, { Transparency = 0.4 }):Play()
end

function Chart:_clearHover()
    if self._hoverIndex == nil and not self.guide.Visible then
        return
    end
    self._hoverIndex = nil
    variables.tweenService:Create(self.guide, drawInfo, { BackgroundTransparency = 1 }):Play()
    variables.tweenService:Create(self.readout, drawInfo, { BackgroundTransparency = 1, TextTransparency = 1 }):Play()
    variables.tweenService:Create(self.readoutStroke, drawInfo, { Transparency = 1 }):Play()
    self:_paintMarks(true)
end

-- A dot of the line's own thickness sitting on every point.
--
-- Two segments meeting at a steep angle still part by a pixel or so: a thin line standing nearly
-- upright covers well under a pixel of width, and the renderer has to land each of the two
-- somewhere whole. Reported live as the line "breaking" on the way up. Welding the corner with a
-- dot the same size as the line closes it for good, whatever the angle.
function Chart:_joint(index: number)
    local joint = self.joints[index]
    if joint then
        return joint
    end
    joint = self.window:Create("Frame", {
        Name = "Joint",
        Size = UDim2.fromOffset(lineThickness, lineThickness),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        ZIndex = layers.line,
        BackgroundColor3 = softOf(self:_accent()),

        BackgroundTransparency = 1, -- In = 0

        Parent = self.canvas,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = joint })
    self.joints[index] = joint
    return joint
end

-- The white dot on a line's point (the newest point has its own, with the halo).
function Chart:_pointDot(index: number)
    local dot = self.dots[index]
    if dot then
        return dot
    end
    dot = self.window:Create("Frame", {
        Name = "Point",
        Size = UDim2.fromOffset(pointDotSize, pointDotSize),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        ZIndex = layers.point,

        BackgroundTransparency = 1, -- In = 0

        Parent = self.canvas,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = dot })
    self.dots[index] = dot
    return dot
end

function Chart:_hideJointsFrom(index: number)
    for i = index, #self.joints do
        self.joints[i].Visible = false
    end
end

function Chart:_hideMarksFrom(index: number)
    for i = index, #self.marks do
        self.marks[i].Visible = false
    end
end

function Chart:_hideDotsFrom(index: number)
    for i = index, #self.dots do
        self.dots[i].Visible = false
    end
end

-- The names under the bars, one per slot, centred on its bar.
function Chart:_redrawLabels(width: number)
    local count = #self.points
    local shown = self:_hasLabels() and width > 0
    self.labelRow.Visible = shown
    local used = 0
    if shown then
        local slot = width / math.max(count, 1)
        for index = 1, count do
            local label = self.labelLabels[index]
            if not label then
                label = self.window:Create("TextLabel", {
                    Name = "Label",
                    AnchorPoint = Vector2.new(0.5, 0),
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    TextSize = 11,
                    TextTruncate = Enum.TextTruncate.AtEnd,

                    TextTransparency = if self._shown then 0.45 else 1,

                    Parent = self.labelRow,
                }, { TextColor3 = "ContentColor", FontFace = "Font" })
                self.labelLabels[index] = label
            end
            label.Visible = true
            label.Text = self.labels[index] or ""
            label.Size = UDim2.fromOffset(math.floor(slot), 12)
            label.Position = UDim2.fromOffset(math.floor(slot * (index - 0.5) + 0.5), 0)
        end
        used = count
    end
    for index = used + 1, #self.labelLabels do
        self.labelLabels[index].Visible = false
    end
end

function Chart:_redraw(animate: boolean?)
    -- a redraw takes over from an entrance still playing: its pieces are where they belong now
    self._drawCount = (self._drawCount or 0) + 1
    self._revealX = nil
    local width, height = self.plot.AbsoluteSize.X, self.plot.AbsoluteSize.Y
    local count = #self.points

    self.emptyLabel.Visible = count == 0
    if count == 0 or width <= 0 or height <= 0 then
        self:_hideMarksFrom(1)
        self:_hideDotsFrom(1)
        self:_hideJointsFrom(1)
        self:_redrawFill(0, 0, 0, function()
            return 0
        end)
        self:_redrawDot(0, 0, false)
        self:_redrawLabels(0)
        self.maxLabel.Text = ""
        self.minLabel.Text = ""
        self:_syncValueLabel()
        return
    end

    local low, high = self:_range()
    local span = high - low
    local top = plotPadTop
    local bottom = if self.mode == "bar" then 1 else plotPadBottom
    local room = math.max(height - top - bottom, 1)
    -- where a value sits inside the plot, in pixels from the top
    local function yOf(value: number): number
        return top + (1 - (value - low) / span) * room
    end

    self.maxLabel.Text = self:_readable(high)
    self.minLabel.Text = self:_readable(low)

    if self.mode == "bar" then
        local slot = width / count
        local barWidth = math.clamp(math.floor(slot * barShare), minBarWidth, maxBarWidth)
        local floor = yOf(math.max(low, 0))
        local barTops = {}
        self._pointY = barTops
        for index, value in self.points do
            local mark = self:_mark(index)
            local barHeight = math.max(floor - yOf(value), 3)
            local isNew = index == count and not mark.Visible
            mark.Visible = true
            mark.Position = UDim2.fromOffset(math.floor(slot * (index - 0.5) + 0.5), math.floor(floor + 0.5))
            local target = UDim2.fromOffset(barWidth, math.floor(barHeight + 0.5))
            barTops[index] = floor - barHeight
            if isNew then
                mark.Size = UDim2.fromOffset(barWidth, 1) -- a new bar grows up out of the floor
            end
            if animate and self._drawn then
                variables.tweenService:Create(mark, drawInfo, { Size = target }):Play()
            else
                mark.Size = target
            end
            mark.Rotation = 0
        end
        self:_hideMarksFrom(count + 1)
        self:_hideJointsFrom(1)
        self:_hideDotsFrom(1)
        self:_redrawFill(0, 0, height, function()
            return height
        end)
        self:_redrawDot(0, 0, false)
        self:_redrawLabels(width)
    else
        local step = self:_lineStep(width, count)
        local function xOf(index: number): number
            return leftRoom + (index - 1) * step
        end

        -- The line's vertices: the points themselves, or, for a smooth line, the curve through
        -- them sampled finely enough to read as one.
        local xs, ys = {}, {}
        for index = 1, count do
            xs[index], ys[index] = xOf(index), yOf(self.points[index])
        end
        local vx, vy = xs, ys
        if self.smooth and count >= 3 then
            vx, vy = {}, {}
            for index = 1, count - 1 do
                local x0, y0 = xs[math.max(index - 1, 1)], ys[math.max(index - 1, 1)]
                local x1, y1 = xs[index], ys[index]
                local x2, y2 = xs[index + 1], ys[index + 1]
                local x3, y3 = xs[math.min(index + 2, count)], ys[math.min(index + 2, count)]
                local pieces = math.clamp(math.ceil((x2 - x1) / smoothPieceWidth), minSmoothPieces, maxSmoothPieces)
                for piece = 0, pieces - 1 do
                    local t = piece / pieces
                    table.insert(vx, catmull(x0, x1, x2, x3, t))
                    -- the curve can overshoot between two points; never past the plot's own edges
                    table.insert(vy, math.clamp(catmull(y0, y1, y2, y3, t), 2, height - 2))
                end
            end
            table.insert(vx, xs[count])
            table.insert(vy, ys[count])
        end
        local vertices = #vx
        local overlap = if vx == xs then straightOverlap else smoothOverlap
        self._overlap = overlap

        -- one rotated frame per gap between vertices
        for index = 1, math.max(vertices - 1, 0) do
            local mark = self:_mark(index)
            local x1, y1 = vx[index], vy[index]
            local x2, y2 = vx[index + 1], vy[index + 1]
            local dx, dy = x2 - x1, y2 - y1
            mark.Visible = true
            -- Centred and rotated about its own middle. Rotation turns a frame around its anchor, so
            -- the previous version - anchored at its left edge but placed at the segment's MIDDLE
            -- height - swung each segment half a step off its own end. That is what left the line
            -- looking like loose dashes with gaps at the joins. Reported live, visible on any steep
            -- series.
            --
            -- The overlap, with the rounded caps each segment wears, closes the hairline at the joins.
            mark.AnchorPoint = Vector2.new(0.5, 0.5)
            self:_placeSegment(mark, x1, y1, x2, y2, overlap)
            mark.Rotation = math.deg(math.atan2(dy, dx))
            self._segments[index] = { x1, y1, x2, y2 }
        end
        for index = math.max(vertices, 1), #self._segments do
            self._segments[index] = nil
        end
        -- a curve's pieces turn so little from one to the next that they need no welding
        local welded = if vx == xs then count else 0
        for index = 1, welded do
            local joint = self:_joint(index)
            joint.Visible = true
            joint.Position = UDim2.fromOffset(xs[index], ys[index])
        end
        self:_hideJointsFrom(welded + 1)
        self:_hideMarksFrom(math.max(vertices, 1))

        -- a white dot on every point but the newest (that one has its own), while they fit
        local dotted = self.showDots and step >= pointDotMinStep
        local dotCount = if dotted then count - 1 else 0
        for index = 1, dotCount do
            local dot = self:_pointDot(index)
            local fresh = not dot.Visible
            dot.Visible = true
            dot.Position = UDim2.fromOffset(math.floor(xOf(index) + 0.5), math.floor(yOf(self.points[index]) + 0.5))
            if fresh and self._shown then
                dot.BackgroundTransparency = 0
            end
        end
        self:_hideDotsFrom(dotCount + 1)

        -- a single point has no segment to draw, so it draws itself as a dot
        if count == 1 then
            local mark = self:_mark(1)
            mark.Visible = true
            mark.Rotation = 0
            mark.AnchorPoint = Vector2.new(0.5, 0.5)
            mark.Size = UDim2.fromOffset(lineThickness * 2, lineThickness * 2)
            mark.Position = UDim2.fromOffset(xOf(1), yOf(self.points[1]))
        end

        -- the height of the line at any x, for the field under it: read off the drawn vertices, so
        -- the field follows a curve as closely as it follows a straight line
        self._animatingFill = animate == true
        local cursor = 1
        self:_redrawFill(xOf(1), xOf(count), height, function(x: number): number
            if vertices == 1 then
                return vy[1]
            end
            -- the columns are asked for left to right, so the search only ever moves forward
            if x < vx[cursor] then
                cursor = 1
            end
            while cursor < vertices - 1 and vx[cursor + 1] < x do
                cursor += 1
            end
            local x1, x2 = vx[cursor], vx[cursor + 1]
            local blend = math.clamp((x - x1) / math.max(x2 - x1, 0.001), 0, 1)
            return vy[cursor] + (vy[cursor + 1] - vy[cursor]) * blend
        end)
        -- the newest point wears its dot and halo unless the chart asked for no dots at all (a
        -- smooth line, by default): then the curve simply ends, as the Concept's does
        self:_redrawDot(xOf(count), yOf(self.points[count]), self.showDots)
        -- where each point sits, for the reading under the pointer to keep clear of
        self._pointY = ys
        self:_redrawLabels(0)
        self._step = step
    end

    self._drawn = true
    if self.mode == "line" then
        self:_clipToView()
    else
        table.clear(self._segments)
    end
    self:_syncValueLabel()
    if self._shown then
        self:_paintMarks(false)
    end

    -- the series travels left by exactly one point, from off the clipped edge
    if animate and self._slide and width > 0 then
        local step = if self.mode == "bar" then width / math.max(count, 1) else self:_lineStep(width, count)
        self.canvas.Position = UDim2.fromOffset(math.floor(step), 0)
        variables.tweenService:Create(self.canvas, slideInfo, { Position = UDim2.fromOffset(0, 0) }):Play()
    end
    self._slide = false
end

-- Put one piece of the line between two points, centred on its middle.
--
-- Placed by scale, not offset: a UDim2 offset is a whole number of pixels, so every piece's centre
-- used to snap to the pixel grid - on a curve, whose pieces are a few pixels long, that turned the
-- line into a staircase and its edge looked pixelated. A scale of the plot's size keeps the
-- centre where the curve actually is, between pixels, which is how the Gen 3 Concept places its
-- own. The length rounds up, so neighbouring pieces never fall short of each other.
function Chart:_placeSegment(mark, x1: number, y1: number, x2: number, y2: number, overlap: number)
    local width, height = self.plot.AbsoluteSize.X, self.plot.AbsoluteSize.Y
    local length = math.sqrt((x2 - x1) ^ 2 + (y2 - y1) ^ 2)
    mark.Size = UDim2.fromOffset(math.max(math.ceil(length + overlap), 1), lineThickness)
    mark.Position = UDim2.fromScale(((x1 + x2) / 2) / math.max(width, 1), ((y1 + y2) / 2) / math.max(height, 1))
end

-- Trim the line to the part of the page on screen.
--
-- The line is rotated frames, and Roblox does not clip a rotated frame at its clipping ancestors'
-- edges the way it clips an upright one: a chart scrolled half under the tab track had its last
-- segment poking up into the window above the page. So each segment is cut here, against the band
-- of the plot the page actually shows, and one wholly outside it is hidden. Run after every
-- redraw and whenever the plot moves (a scroll, a tab switch, the window dragged).
function Chart:_clipToView()
    -- the band every clipping ancestor lets through - the page, the frame around the pages, a
    -- collapsible - in the plot's own pixels
    local plotPosition = self.plot.AbsolutePosition
    local height = self.plot.AbsoluteSize.Y
    local low, high = 0, height
    if plotPosition then
        local node = self.plot.Parent
        while node and not node:IsA("LayerCollector") and not node:IsA("ScreenGui") do
            -- (one not laid out yet has no size to clip to, and says nothing about the view)
            local isGui = node:IsA("GuiObject") or node:IsA("Frame") or node:IsA("ScrollingFrame")
            local size = isGui and node.ClipsDescendants and node.AbsoluteSize
            if size and size.Y > 0 and node.AbsolutePosition then
                local top = node.AbsolutePosition.Y - plotPosition.Y
                low = math.max(low, top)
                high = math.min(high, top + node.AbsoluteSize.Y)
            end
            node = node.Parent
        end
    end

    -- A piece reaches past its own ends by its rounded cap and its overlap with the next one, so a
    -- piece cut exactly at an edge still poked a few bright pixels over it - specks in the gap under
    -- the tab track, above the top fade. Cut that much inside the edges instead.
    local reach = lineThickness / 2 + (self._overlap or straightOverlap) / 2 + 0.5
    if low > 0 then
        low += reach
    end
    if high < height then
        high -= reach
    end

    for index, ends in self._segments do
        local mark = self.marks[index]
        if mark then
            local x1, y1, x2, y2 = ends[1], ends[2], ends[3], ends[4]
            -- while the entrance wipes the line in, nothing right of the wipe is drawn yet
            local right = self._revealX
            local outside = (y1 < low and y2 < low) or (y1 > high and y2 > high) or high <= low
            if right and not outside then
                if x1 >= right then
                    outside = true
                elseif x2 > right then
                    y2 = y1 + (y2 - y1) * (right - x1) / (x2 - x1)
                    x2 = right
                    outside = (y1 < low and y2 < low) or (y1 > high and y2 > high)
                end
            end
            mark.Visible = not outside
            if not outside then
                local dx, dy = x2 - x1, y2 - y1
                -- slide whichever end is past an edge back along the segment to that edge
                local function cut(_y: number, edge: number)
                    local t = (edge - y1) / dy
                    return x1 + dx * t, edge
                end
                if dy ~= 0 then
                    if y1 < low then
                        x1, y1 = cut(y1, low)
                    elseif y1 > high then
                        x1, y1 = cut(y1, high)
                    end
                    if y2 < low then
                        x2, y2 = cut(y2, low)
                    elseif y2 > high then
                        x2, y2 = cut(y2, high)
                    end
                end
                self:_placeSegment(mark, x1, y1, x2, y2, self._overlap or straightOverlap)
            end
        end
    end
end

-- A value the way this chart writes it: the dev's formatter when there is one, otherwise the
-- number with its prefix, suffix and decimals, and thousands separators.
function Chart:_readable(value: number): string
    if type(self.format) == "function" then
        local ok, text = pcall(self.format, value)
        if ok then
            return tostring(text)
        end
    end
    local text
    if self.decimals > 0 then
        text = string.format("%." .. self.decimals .. "f", value)
    elseif math.abs(value) >= 100 or value % 1 == 0 then
        text = tostring(math.floor(value + 0.5))
    else
        text = string.format("%.1f", value)
    end
    return self.prefix .. commafy(text) .. self.suffix
end

function Chart:_syncValueLabel()
    if not self.showValue then
        return
    end
    local newest = self.points[#self.points]
    local text = if newest ~= nil then self:_readable(newest) else ""

    -- kept in sync for anything reading the label directly (a spec, a dev); what is SEEN is the
    -- odometer, whose digits roll up or down to the new number instead of blinking to it
    self.valueLabel.Text = text
    if self.valueOdo then
        local previous = self._lastValue
        self._lastValue = newest
        if previous == nil or newest == nil then
            self.valueOdo:snap(text)
        else
            self.valueOdo:to(text, newest >= previous)
        end
    end
end

-- Colour and settle every drawn piece. (How the chart first comes in is _entrance.)
function Chart:_paintMarks(animate: boolean?)
    local accent = self:_accent()
    local soft = softOf(accent)
    local deep = deepOf(accent)
    local lineColor = if self.mode == "bar" then accent else soft

    local function settle(part, goal)
        if animate then
            variables.tweenService:Create(part, drawInfo, goal):Play()
        else
            for property, value in goal do
                part[property] = value
            end
        end
    end

    -- Every piece, shown or not: whether a piece of the line is on screen is _clipToView's call, and
    -- it changes as the page scrolls. Painting only the visible ones left a chart that opened below
    -- the fold with its pieces transparent for good - scrolled to, it showed its field and no line.
    for index, mark in self.marks do
        -- the hovered bar lights up in the brighter shade
        local color = if self.mode == "bar" and self._hoverIndex == index then soft else lineColor
        settle(mark, { BackgroundColor3 = color, BackgroundTransparency = 0 })
    end

    for _, joint in self.joints do
        if joint.Visible then
            settle(joint, { BackgroundColor3 = soft, BackgroundTransparency = 0 })
        end
    end

    for _, fill in self.fills do
        if fill.Visible then
            settle(fill, { BackgroundColor3 = deep, BackgroundTransparency = fillTransparency })
        end
    end

    -- the white dots; the hovered one grows and takes the line's colour
    for index, dot in self.dots do
        if dot.Visible then
            local hovered = self._hoverIndex == index
            local size = if hovered then pointDotSize + 4 else pointDotSize
            local goal = {
                BackgroundColor3 = if hovered then soft else Color3.fromRGB(255, 255, 255),
                BackgroundTransparency = 0,
                Size = UDim2.fromOffset(size, size),
            }
            settle(dot, goal)
        end
    end

    local newestHovered = self._hoverIndex == #self.points and self.mode == "line"
    if self.dot.Visible then
        local size = if newestHovered then dotSize + 4 else dotSize
        settle(self.dot, {
            BackgroundColor3 = if newestHovered then soft else Color3.fromRGB(255, 255, 255),
            BackgroundTransparency = 0,
            Size = UDim2.fromOffset(size, size),
        })
    end
    if self.halo.Visible then
        settle(self.halo, { BackgroundColor3 = soft, BackgroundTransparency = 0.8 })
    end
end

moveable(Chart)
lockable(Chart)

-- Every point currently drawn, oldest first.
function Chart:Get(): { number }
    return table.clone(self.points)
end

-- Add one point, with a bar's name under it if you like. The oldest falls off the left once the
-- chart is full.
function Chart:Push(value, label)
    local number = tonumber(value)
    if not number or number ~= number then
        return false
    end
    local wasFull = #self.points >= self.maxPoints
    table.insert(self.points, number)
    if label ~= nil then
        self.labels[#self.points] = tostring(label)
    end
    while #self.points > self.maxPoints do
        table.remove(self.points, 1)
        local shifted = {}
        for index, text in self.labels do
            if index > 1 then
                shifted[index - 1] = text
            end
        end
        self.labels = shifted
    end
    -- only a full chart actually travels; before that the line is still growing into the plot
    self._slide = wasFull
    self:_redraw(true)
    return true
end

-- Replace the whole series: numbers, or { value = n, label = "Mon" } for named bars.
function Chart:Set(values)
    self.labels = {}
    self:_readSeries(values)
    self:_resize()
    self:_redraw(false)
end

-- The card follows the plot's height, and the room named bars need under it.
function Chart:_resize()
    self.plot.Size = UDim2.new(1, -(sidePadding * 2), 0, self.height)
    self.labelRow.Position = UDim2.new(0, sidePadding, 0, headerTop + headerHeight + plotGap + self.height + 3)
    self.main.Size = UDim2.new(1, -20, 0, self:_cardHeight())
end

function Chart:Clear()
    self.points = {}
    self.labels = {}
    self:_resize()
    self:_redraw(false)
end

-- Pin the scale, or hand either end back to the data with nil.
function Chart:SetRange(min, max)
    self.min = tonumber(min)
    self.max = tonumber(max)
    self:_redraw(true)
end

function Chart:SetHeight(height)
    self.height = math.max(clampNumber(height, defaultHeight), minHeight)
    self:_resize()
    self:_redraw(false)
end

-- Line or bar, swapped live: the marks are rebuilt in the other shape.
function Chart:SetMode(mode)
    mode = string.lower(tostring(mode))
    if mode ~= "bar" and mode ~= "line" then
        return false
    end
    if mode == self.mode then
        return true
    end
    self.mode = mode
    for _, mark in self.marks do
        self.window:DestroySubtree(mark)
    end
    table.clear(self.marks)
    for _, fill in self.fills do
        self.window:DestroySubtree(fill)
    end
    table.clear(self.fills)
    for _, joint in self.joints do
        self.window:DestroySubtree(joint)
    end
    table.clear(self.joints)
    for _, dot in self.dots do
        self.window:DestroySubtree(dot)
    end
    table.clear(self.dots)
    self._drawn = false
    self:_resize()
    self:_redraw(false)
    if self._shown then
        self:_paintMarks(false)
    end
    return true
end

-- Draw the chart in: see entranceTime. Replayed each time its page comes on screen.
function Chart:_entrance()
    self:_paintMarks(false)
    if not self._shown or #self.points == 0 then
        return
    end
    self._entranceToken = (self._entranceToken or 0) + 1
    local token, drawn = self._entranceToken, self._drawCount
    -- a later entrance, a redraw or the chart hiding all end this one where it stands
    local function current(): boolean
        return self._entranceToken == token and self._drawCount == drawn and self._shown == true
    end
    local ts = variables.tweenService

    if self.mode == "bar" then
        local order = 0
        for _, mark in self.marks do
            if mark.Visible then
                local target = mark.Size
                mark.Size = UDim2.fromOffset(target.X.Offset, 0)
                task.delay(0.04 + order * barStagger, function()
                    if current() then
                        ts:Create(mark, barGrowInfo, { Size = target }):Play()
                    else
                        mark.Size = target
                    end
                end)
                order += 1
            end
        end
        return
    end

    local width = self.plot.AbsoluteSize.X
    if width <= 0 then
        return
    end
    -- how far along the wipe is by the time it reaches x: the dots and the field follow it
    local function lagAt(x: number): number
        return math.clamp(x / width, 0, 1) * entranceTime * 0.62
    end

    for _, dot in self.dots do
        if dot.Visible then
            local size = dot.Size
            dot.Size = UDim2.fromOffset(0, 0)
            task.delay(lagAt(dot.Position.X.Offset), function()
                if current() then
                    ts:Create(dot, dotPopInfo, { Size = size }):Play()
                else
                    dot.Size = size
                end
            end)
        end
    end
    if self.dot.Visible then
        local size = self.dot.Size
        self.dot.Size = UDim2.fromOffset(0, 0)
        self.halo.BackgroundTransparency = 1
        task.delay(lagAt(self.dot.Position.X.Offset), function()
            if current() then
                ts:Create(self.dot, dotPopInfo, { Size = size }):Play()
                ts:Create(self.halo, dotPopInfo, { BackgroundTransparency = 0.8 }):Play()
            else
                self.dot.Size = size
                self.halo.BackgroundTransparency = 0.8
            end
        end)
    end
    for _, fill in self.fills do
        if fill.Visible then
            local target = fill.Size
            fill.Size = UDim2.fromOffset(target.X.Offset, 0)
            task.delay(lagAt(fill.Position.X.Offset) + 0.05, function()
                if current() then
                    ts:Create(fill, fillRiseInfo, { Size = target }):Play()
                else
                    fill.Size = target
                end
            end)
        end
    end

    -- the line itself, wiped in: a rotated frame is not clipped by a frame growing over it, so
    -- the wipe is the same cut _clipToView makes at the page's edges, moved along each frame
    local progress = Instance.new("NumberValue")
    progress.Value = 0
    self._revealX = 0
    self:_clipToView()
    local function step()
        if not current() then
            return
        end
        self._revealX = progress.Value * width
        self:_clipToView()
    end
    local changed = progress.Changed:Connect(step)
    local wipe = ts:Create(progress, entranceWipe, { Value = 1 })
    wipe.Completed:Connect(function()
        changed:Disconnect()
        progress:Destroy()
        if self._entranceToken == token and self._drawCount == drawn then
            self._revealX = nil
            self:_clipToView()
        end
    end)
    wipe:Play()
    -- a tween that is cancelled never completes; this makes sure the line is whole regardless
    task.delay(entranceTime + 0.1, function()
        if self._entranceToken == token and self._drawCount == drawn and self._revealX ~= nil then
            self._revealX = nil
            self:_clipToView()
        end
    end)
end

function Chart:_setShown(shown, animate)
    local w = self.window
    self._shown = shown
    if shown then
        w:_revealCommon(self, animate)
        if self.valueOdo then
            self.valueOdo:reveal(0.1, animate)
        end
        w:_reveal(self.baseline, { BackgroundTransparency = gridTransparency }, animate)
        w:_reveal(self.emptyLabel, { TextTransparency = if #self.points == 0 then 0.6 else 1 }, animate)
        for _, line in self.gridLines do
            w:_reveal(line, { BackgroundTransparency = gridTransparency }, animate)
        end
        for _, label in self.labelLabels do
            w:_reveal(label, { TextTransparency = 0.45 }, animate)
        end
        w:_reveal(self.maxLabel, { TextTransparency = 0.72 }, animate)
        w:_reveal(self.minLabel, { TextTransparency = 0.72 }, animate)

        if animate then
            self:_entrance()
        else
            self:_paintMarks(false)
        end
        if self.dot.Visible and not self._haloPlaying then
            self._haloPlaying = true
            self._haloTween =
                variables.tweenService:Create(self.halo, haloInfo, { Size = UDim2.fromOffset(haloPeak, haloPeak) })
            self._haloTween:Play()
        end
    else
        w:_hideCommon(self, animate)
        if self.valueOdo then
            self.valueOdo:reveal(1, animate)
        end
        w:_reveal(self.baseline, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.emptyLabel, { TextTransparency = 1 }, animate)
        for _, line in self.gridLines do
            w:_reveal(line, { BackgroundTransparency = 1 }, animate)
        end
        w:_reveal(self.maxLabel, { TextTransparency = 1 }, animate)
        w:_reveal(self.minLabel, { TextTransparency = 1 }, animate)
        for _, mark in self.marks do
            w:_reveal(mark, { BackgroundTransparency = 1 }, animate)
        end
        for _, fill in self.fills do
            w:_reveal(fill, { BackgroundTransparency = 1 }, animate)
        end
        for _, joint in self.joints do
            w:_reveal(joint, { BackgroundTransparency = 1 }, animate)
        end
        for _, dot in self.dots do
            w:_reveal(dot, { BackgroundTransparency = 1 }, animate)
        end
        for _, label in self.labelLabels do
            w:_reveal(label, { TextTransparency = 1 }, animate)
        end
        w:_reveal(self.dot, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.halo, { BackgroundTransparency = 1 }, animate)
        self:_clearHover()
        -- an endless halo tween on an element nobody is looking at is work for nothing
        if self._haloTween then
            self._haloTween:Cancel()
            self._haloTween = nil
        end
        self._haloPlaying = false
    end
end

function Chart:_refreshTheme()
    if self._shown then
        self:_paintMarks(true)
    end
end

function Chart:_minWidth(): number
    return 200
end

function Chart:Remove()
    if self.descriptor then
        self.descriptor:Remove()
    end
    self.main:Destroy()
end

return Chart
]=====]

sources["components/checkbox"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A compact alternative to Toggle: same flag/config/description contract and the same
-- full/compact scaffolding, just a small check box instead of a pill + knob.

local Checkbox = {}
Checkbox.__index = Checkbox
Checkbox.__type = "Checkbox"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local constants = require(utility.constants)
-- the height of a one-line card (see constants.elementHeight)
local elementHeight = constants.elementHeight
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

local checkIcon = constants.icons.tick
local boxSize = 26 -- the Concept's box
local boxLeft = 16

function Checkbox.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local declared = functions.readValue(properties, { "value", "Value" })

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Checkbox",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState,
        compact = tab.compact or false,

        flag = properties.flag
            or properties.Flag
            or (
                not (properties.forgetState or properties.ForgetState or tab.forgetState)
                    and functions.deriveFlagFromName(properties.name or properties.Name or "Checkbox")
                or nil
            ),

        callback = properties.callback or properties.Callback or function() end,

        value = if declared ~= nil then declared else false,
    }, Checkbox)

    self.window:_registerControl(self)

    if self.compact then
        self:_buildCompact()
    else
        self:_buildFull()
    end

    self.window:_wireTooltip(self)

    if self.description and not self.compact then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- The box + checkmark, the Gen 3 Concept's: a dark rounded square with a faint outline when
-- unchecked, a white one with a dark tick when checked - the tick popping in on a slight overshoot.
-- The same in both layouts; the caller places it (left of the title, or pinned right in a row).
local checkedFill = Color3.fromRGB(255, 255, 255)
local tickColour = Color3.fromRGB(26, 26, 26)

-- fill, fill transparency, outline transparency for the current state
function Checkbox:_boxLook(): (Color3, number)
    if self.value then
        return checkedFill, 1
    end
    return self.window.theme.ToggleTrack, 0.84
end

function Checkbox:_buildBox(parent)
    local window = self.window
    local fill = self:_boxLook()

    self.box = window:Create("Frame", {
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(boxSize, boxSize),
        BackgroundColor3 = fill,

        BackgroundTransparency = 1, -- In = 0

        Parent = parent,
    })

    window:Create("UICorner", {
        CornerRadius = UDim.new(0, 8),
        Parent = self.box,
    })

    -- a soft top-to-bottom sheen, so the checked box reads as a raised key rather than a flat tile
    window:Create("UIGradient", {
        Rotation = 90,
        Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(196, 196, 196)),
        Parent = self.box,
    })

    self.boxStroke = window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),
        Transparency = 1, -- In = 0.84 unchecked / 1 checked
        Parent = self.box,
    })

    self.checkIcon = window:Create("ImageLabel", {
        Image = checkIcon,
        Size = UDim2.fromOffset(18, 18),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        ImageColor3 = tickColour,

        -- Animation: scale-pops in with a check, fades out when unchecked
        ImageTransparency = self.value and 0 or 1,
        Parent = self.box,
    })

    self.checkIconScale = window:Create("UIScale", {
        Scale = self.value and 1 or 0.4,
        Parent = self.checkIcon,
    })

    return self.box
end

-- flip, animate, run callback (error-flash on fail), autosave. press anim is per-layout
function Checkbox:_performCheck()
    hapticEngine.click()
    soundEngine.click()
    self.value = not self.value
    self:_animateBox()

    self.window:_runGuarded(self, self.callback, self.value)
    self.window:_persist(self)
end

-- full-width: title/icon left, box pinned right, width-bounce
function Checkbox:_buildFull()
    local window = self.window

    self.main = window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, elementHeight),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = window:StyleElementBody(self.main)
    self.hoverOverlay = window:CreateHoverOverlay(self.main)

    self.container = window:Create("Frame", {
        BorderSizePixel = 0,

        Parent = self.main,
        Size = UDim2.new(0, 170, 0, 16),
        -- after the box, which leads the row the way the Concept's does
        Position = UDim2.new(0, boxLeft + boxSize + 12, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
    })

    self.containerLayout = window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, constants.elementIconGap),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(constants.elementIconSize, constants.elementIconSize),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(250, 16),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        AutomaticSize = Enum.AutomaticSize.X,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.interact = window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 1, 0),
        BorderSizePixel = 0,
        Position = UDim2.fromScale(1, 0.5),
        AnchorPoint = Vector2.new(1, 0.5),
        TextTransparency = 1,
        ZIndex = 10,

        Parent = self.main,
    })

    -- the box leads the row, 16px in; the title runs from after it to the right edge
    self:_buildBox(self.main)
    self.box.Position = UDim2.new(0, boxLeft, 0, elementHeight / 2)
    self.box.AnchorPoint = Vector2.new(0, 0.5)
    -- nothing on the right but the row's own padding
    self.window:_fitRowTitle(self, constants.elementInset)

    self.window:_wireElementHover(self)

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()
        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -26, 0, elementHeight) }
            )
            :Play()

        self:_performCheck()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -20, 0, elementHeight) }
            )
            :Play()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- compact (row): title left, box right (SpaceBetween)
function Checkbox:_buildCompact()
    local window = self.window

    self.main, self.stroke, self.interact = window:_buildCompactRow(self.tab, self.name, 10)
    self.hoverOverlay = self.interact

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 15),
        PaddingRight = UDim.new(0, 15),

        Parent = self.interact,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.SpaceBetween,
        Padding = UDim.new(0, 10),

        Parent = self.interact,
    })

    self.container = window:Create("Frame", {
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, 16),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 0,

        Parent = self.interact,
    })

    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.container,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, constants.elementIconGap),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(constants.elementIconSize, constants.elementIconSize),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            LayoutOrder = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    self:_buildBox(self.interact)
    self.box.LayoutOrder = 1

    self.window:_wireElementHover(self)

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()

        self:_performCheck()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- checked pops with a slight overshoot; unchecked settles back flat
local checkPopIn = TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
local checkFadeOut = TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local boxColorInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

function Checkbox:_animateBox()
    local ts = variables.tweenService
    local fill, outline = self:_boxLook()
    ts:Create(self.box, boxColorInfo, { BackgroundColor3 = fill, BackgroundTransparency = 0 }):Play()
    ts:Create(self.boxStroke, boxColorInfo, { Transparency = outline }):Play()
    if self.value then
        ts:Create(self.checkIcon, checkPopIn, { ImageTransparency = 0 }):Play()
        ts:Create(self.checkIconScale, checkPopIn, { Scale = 1 }):Play()
    else
        ts:Create(self.checkIcon, checkFadeOut, { ImageTransparency = 1 }):Play()
        ts:Create(self.checkIconScale, checkFadeOut, { Scale = 0.4 }):Play()
    end
end

local checkboxReveal = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
-- Live-caught: same ordering fix as toggle.luau's own toggleStateReveal - the box's checked-state
-- colour/checkmark faded in on the same beat as the row it sits on, so it could read as "there"
-- before the row itself looked like a real card yet. Delayed after the row (checkboxReveal via
-- _revealCommon, no delay) but before the glow (checkboxGlowReveal, 0.35s).
local checkboxStateReveal = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out, 0, false, 0.12)

function Checkbox:_setShown(shown, animate)
    local w = self.window
    if shown then
        local fill, outline = self:_boxLook()
        w:_revealCommon(self, animate)
        w:_reveal(self.box, { BackgroundColor3 = fill, BackgroundTransparency = 0 }, animate, checkboxStateReveal)
        w:_reveal(self.boxStroke, { Transparency = outline }, animate, checkboxStateReveal)
        w:_reveal(self.checkIcon, { ImageTransparency = self.value and 0 or 1 }, animate, checkboxStateReveal)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.box, { BackgroundTransparency = 1 }, animate, checkboxReveal)
        w:_reveal(self.boxStroke, { Transparency = 1 }, animate, checkboxReveal)
        w:_reveal(self.checkIcon, { ImageTransparency = 1 }, animate, checkboxReveal)
    end
end

-- Re-apply the visuals that aren't plain themeProperties, so a runtime ChangeTheme reaches
-- the box. Called on the visible tab only.
function Checkbox:_refreshTheme()
    local fill = self:_boxLook()
    variables.tweenService
        :Create(
            self.box,
            TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { BackgroundColor3 = fill }
        )
        :Play()
end

-- Room the compact checkbox needs: side padding + icon (and gap) if shown + title text
-- + the gap to the box + the box itself. Lets a horizontal group wrap sensibly.
function Checkbox:_minWidth()
    local w = 30 + 10 + boxSize -- 15+15 padding, 10 gap to box, box itself
    if self.icon then
        w += 21 -- 16 icon + 5 gap
    end
    w += functions.textWidth(self.window.theme.Font, 16, self.name)
    return w
end

moveable(Checkbox)
lockable(Checkbox)

function Checkbox:Set(value, skipCallback)
    local changed = self.value ~= value
    self.value = value

    if changed then
        self:_animateBox()
    end

    -- fire even when unchanged: config load calls Set and relies on the callback to apply
    if not skipCallback then
        self.window:_runGuarded(self, self.callback, self.value)
        self.window:_persist(self)
    end
end

return Checkbox
]=====]

sources["components/chrome"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Window furniture: the collapsed "Show" face main wears while hidden (window.collapsed*
-- fields), plus the first-open new-user check. The welcome greeting itself is just a toast now.

local utility = script.Parent.Parent.utility
local variables = require(utility.variables)
local filesystem = require(utility.filesystem)
local constants = require(utility.constants)
local locale = require(utility.locale)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

local chrome = {}

local collapsedDragThreshold = 6

-- Same half-extent clamp _clampedPosition (windowMethods.luau) uses for a real drag, just
-- against the pill's own current AbsoluteSize instead of the full window's self.size - main is
-- tiny while collapsed, so clamping against the expanded window's own half-extents would either
-- refuse to let the pill reach the real screen edges or let it hang off them, depending on which
-- is bigger.
local function clampCollapsedPosition(window, position: UDim2): UDim2
    if not (window.settings and window.settings.keepOnScreen) then
        return position
    end
    if position.X.Scale ~= 0 or position.Y.Scale ~= 0 then
        return position -- on-scale positions recentre on their own; nothing to clamp
    end
    local size = window.main.AbsoluteSize
    local screen = window.screenGui.AbsoluteSize
    local margin = 8
    local halfX, halfY = size.X / 2, size.Y / 2
    local x = math.clamp(position.X.Offset, halfX + margin, math.max(halfX + margin, screen.X - halfX - margin))
    local y = math.clamp(position.Y.Offset, halfY + margin, math.max(halfY + margin, screen.Y - halfY - margin))
    return UDim2.fromOffset(x, y)
end

-- Drag the collapsed pill around the screen (e.g. out from under something else on screen it
-- happens to land on) - a plain tap still restores the window; a real drag doesn't also fire
-- that. MouseButton1Click alone can't tell those apart (Roblox fires it on any mouse-up over the
-- button regardless of movement in between), so this tracks the raw input itself and only calls
-- ToggleHide() when the pointer never moved past a small threshold - the same click-vs-drag
-- shape a real drag handle would use, just with the "was this actually a drag" check added on
-- top.
local function wireCollapsedDrag(window)
    local uis = variables.userInputService
    local dragging, dragged = false, false
    local startMouse, startMainPos = Vector2.zero, UDim2.new()

    window:Connect(window.collapsedInteract.InputBegan, function(input, processed)
        if processed then
            return
        end
        local t = input.UserInputType
        if t ~= Enum.UserInputType.MouseButton1 and t ~= Enum.UserInputType.Touch then
            return
        end
        dragging = true
        dragged = false
        startMouse = uis:GetMouseLocation()
        startMainPos = window.main.Position
    end)

    window:Connect(variables.runService.RenderStepped, function()
        if not dragging then
            return
        end
        local delta = uis:GetMouseLocation() - startMouse
        if not dragged and delta.Magnitude > collapsedDragThreshold then
            dragged = true
        end
        if dragged then
            local target = UDim2.new(
                startMainPos.X.Scale,
                startMainPos.X.Offset + delta.X,
                startMainPos.Y.Scale,
                startMainPos.Y.Offset + delta.Y
            )
            window.main.Position = clampCollapsedPosition(window, target)
        end
    end)

    local function release(input)
        local t = input.UserInputType
        if t ~= Enum.UserInputType.MouseButton1 and t ~= Enum.UserInputType.Touch then
            return
        end
        if not dragging then
            return
        end
        dragging = false
        if dragged then
            -- Remember where the PILL was put, not where the window should reopen. Those are two
            -- different memories and this used to write both into _restorePosition, so dragging
            -- the pill moved the window's reopen spot with it, and reopening + dragging the
            -- window then wiped the pill's spot back to the default corner. Show() still grows
            -- the window out from wherever the pill happens to be - that leg is just a tween, so
            -- it reads as the window travelling back to its own place rather than teleporting.
            window._collapsedPosition = window.main.Position
            window:_rememberCollapsedPosition(window.main.Position)
            window:_syncDragBar()
        else
            hapticEngine.click()
            soundEngine.click()
            window:ToggleHide()
        end
    end
    window:Connect(uis.InputEnded, release)
    window:Connect(uis.WindowFocusReleased, function()
        dragging = false
    end)
end

-- The face main wears once collapsed: an icon + "name"/"Tap to show", drawn straight onto
-- the window frame itself. main already carries the pill's background (its own WindowColor
-- gradient reads the same as the old standalone pill), so shrinking main IS becoming the
-- pill - nothing to hand off to, nothing to swap.
function chrome.buildCollapsedFace(window)
    -- The Gen 3 Concept's pill face: a 30px icon centred 31px in, the name in bold over a quiet
    -- "Tap to show", both starting 65px in.
    window.collapsedIcon = window:Create("ImageLabel", {
        Name = "CollapsedIcon",
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0, 31, 0.5, 0),
        Size = UDim2.fromOffset(30, 30),
        BackgroundTransparency = 1,
        -- raw value: Create routes Image through image.resolve (concat would double the prefix)
        Image = window.showIcon,
        ZIndex = constants.zIndex.restoreContent,

        ImageTransparency = 1, -- shown = 0, set by chrome.setCollapsedShown

        Parent = window.main,
    }, { ImageColor3 = "TitlingColor" })

    window:Create("UICorner", {
        Parent = window.collapsedIcon,
    }, { CornerRadius = "PillCornerRadius" })

    local textContainer = window:Create("Frame", {
        Name = "CollapsedText",
        AnchorPoint = Vector2.new(0, 0.5),
        Position = UDim2.new(0, 65, 0.5, 0),
        Size = UDim2.new(1, -91, 0, 34),
        BackgroundTransparency = 1,
        ZIndex = constants.zIndex.restoreContent,

        Parent = window.main,
    })

    window:Create("UIListLayout", {
        Padding = UDim.new(0, 2),
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = textContainer,
    })

    window.collapsedTitle = window:Create("TextLabel", {
        Name = "Title",
        Text = window.showName,
        Size = UDim2.new(1, 0, 0, 17),
        BackgroundTransparency = 1,
        FontFace = variables.brandFont(Enum.FontWeight.Bold),
        RichText = true,
        TextSize = 16,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 1,
        ZIndex = constants.zIndex.restoreContent,

        TextTransparency = 1, -- shown = 0, set by chrome.setCollapsedShown

        Parent = textContainer,
    }, { TextColor3 = "TitlingColor" })

    window.collapsedSubtitle = window:Create("TextLabel", {
        Name = "Subtitle",
        Text = locale.t("Tap to show"),
        Size = UDim2.new(1, 0, 0, 14),
        BackgroundTransparency = 1,
        FontFace = variables.brandFont(Enum.FontWeight.Medium),
        TextSize = 13,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 2,
        ZIndex = constants.zIndex.restoreContent,

        TextTransparency = 1, -- shown = 0.5, set by chrome.setCollapsedShown

        Parent = textContainer,
    }, { TextColor3 = "TitlingColor" })

    -- covers the whole window but only takes clicks while collapsed - Window:Hide/Show flip
    -- Visible as the morph starts/settles so it can never eat a click mid-animation or while
    -- the window is fully open. Active alone doesn't stop a GuiButton from still receiving
    -- clicks here, so Visible is what actually keeps it out of hit-testing.
    window.collapsedInteract = window:Create("TextButton", {
        Name = "CollapsedInteract",
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        Text = "",
        TextTransparency = 1,
        Visible = false,
        ZIndex = constants.zIndex.restoreInteract,

        Parent = window.main,
    })

    -- Drag the collapsed pill around the screen (e.g. out from under something else on screen
    -- it happens to land on) - a plain tap still restores the window; a real drag doesn't also
    -- fire that. MouseButton1Click alone can't tell those apart (Roblox fires it on any
    -- mouse-up over the button regardless of movement in between), so this tracks the raw
    -- input itself and only calls ToggleHide() when the pointer never moved past a small
    -- threshold - the same click-vs-drag shape a real drag handle would use, just with the
    -- "was this actually a drag" check added on top.
    wireCollapsedDrag(window)
end

function chrome.isNewUser()
    local localPlayer = variables.localPlayer
    if not localPlayer then
        return false
    end

    -- No filesystem available - just show the banner every launch.
    if not filesystem.usable() or typeof(filesystem.writefile) ~= "function" then
        return true
    end

    local path = variables.fileSystemManager:getPath("lastuser.txt")
    local currentId = tostring(localPlayer.UserId)
    local isNew = true

    pcall(function()
        if filesystem.isfile(path) then
            isNew = filesystem.readfile(path) ~= currentId
        end
    end)

    pcall(function()
        filesystem.writefile(path, currentId)
    end)

    return isNew
end

-- Fade the collapsed face (icon + labels) in or out as main morphs into/out of the pill.
-- When tweenInfo is nil the values snap instantly.
function chrome.setCollapsedShown(window, shown, tweenInfo)
    local targets = {
        [window.collapsedIcon] = { ImageTransparency = if shown then 0 else 1 },
        [window.collapsedTitle] = { TextTransparency = if shown then 0 else 1 },
        [window.collapsedSubtitle] = { TextTransparency = if shown then 0.5 else 1 },
    }

    for instance, props in targets do
        if tweenInfo then
            variables.tweenService:Create(instance, tweenInfo, props):Play()
        else
            for property, value in props do
                instance[property] = value
            end
        end
    end
end

return chrome
]=====]

sources["components/collapsible"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 6: a clickable header (title + a chevron that rotates) that expands to reveal its own
-- children, collapsing their height smoothly instead of a hard cut. Doesn't reimplement element
-- building itself - it hosts an internal column Group (group.luau) and forwards every CreateX
-- call to it, exposing the same Tab-like surface (window/tabPage/elements/compact/direction)
-- Group itself expects from its own host. tabPage points at this collapsible's own inner frame,
-- so the group's normal full-width column just becomes this section's expandable content.

local Collapsible = {}
Collapsible.__index = Collapsible
Collapsible.__type = "Collapsible"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local moveable = require(utility.moveable)
local functions = require(utility.functions)
local locale = require(utility.locale)
local constants = require(utility.constants)
-- the height of a one-line card (see constants.elementHeight)
local elementHeight = constants.elementHeight
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

local heightInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
local chevronInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)

local headerHeight = elementHeight

-- breathing room around the nested group: without it, the first child sits glued to the header
-- and the last one gets squeezed against the clip's bottom edge the instant the section opens
local contentPadTop = 8
local contentPadBottom = 8

-- The card behind the content when it is open (background = true, the default): a gap below the
-- header so the two read as separate surfaces, and one pixel of room on each side and the bottom,
-- because a UIStroke draws OUTSIDE its frame and contentWrapper clips - a card flush with the
-- wrapper's edges would lose its outline on exactly those sides.
local cardGap = 6
local strokeRoom = 1

-- Half the element fill, so the element cards inside still read as raised - see
-- functions.containerTransparency, shared with Panel.
local cardTransparency = functions.containerTransparency

function Collapsible.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Section",
        icon = properties.icon or properties.Icon,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState,
        compact = false,
        direction = nil,
        elements = {}, -- the inner group's own elements list (Group fills this in)
        background = functions.readBool(properties, "background", true),

        expanded = if properties.expanded ~= nil
            then properties.expanded
            elseif properties.Expanded ~= nil then properties.Expanded
            else false,

        -- Open or closed persists like any other control's value: a player who opened "Advanced"
        -- finds it open next session instead of closed again. `forgetState = true` (or a tab-wide
        -- one) opts out, same as everywhere else.
        flag = properties.flag
            or properties.Flag
            or (
                not (properties.forgetState or properties.ForgetState or tab.forgetState)
                    and functions.deriveFlagFromName(properties.name or properties.Name or "Section")
                or nil
            ),
    }, Collapsible)
    self.value = self.expanded

    -- the -20 inset happens once here (matches every other tabPage-level card, e.g.
    -- colorpicker.luau's own outer main) - header/contentWrapper below are full width of this.
    -- No AutomaticSize here on purpose: confirmed live that main's AutomaticSize.Y doesn't
    -- reliably follow a *tweened* child Size change on this executor (same class of bug as
    -- UIListLayout never writing back a tweened child's Position) - main sat stuck at whatever
    -- height it last was, collapsed or not, leaving dead space below the header forever. main's
    -- own height is driven explicitly instead, in lockstep with contentWrapper's, by _setHeight
    -- below - every call site that used to resize just contentWrapper resizes both together now.
    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, headerHeight),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Name = self.name,

        Parent = self.tab.tabPage,
    })

    self.window:_registerControl(self)
    self:_buildHeader()

    -- content: clips so the collapse never shows a half-cut child, height tweens between 0 and
    -- the inner group's own real AbsoluteSize.Y
    self.contentWrapper = self.window:Create("Frame", {
        Position = UDim2.fromOffset(0, headerHeight),
        Size = UDim2.new(1, 0, 0, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ClipsDescendants = true,

        Parent = self.main,
    })

    -- What the children are built into: a card of its own when background is on, otherwise the
    -- wrapper directly, as it always was. Either way the wrapper stays the thing that clips and
    -- animates, so the collapse itself is unchanged.
    local contentParent = self.contentWrapper
    if self.background then
        self.contentCard = self.window:Create("Frame", {
            Name = "Content",
            Position = UDim2.fromOffset(strokeRoom, cardGap),
            Size = UDim2.new(1, -strokeRoom * 2, 0, 0),
            BorderSizePixel = 0,
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),

            BackgroundTransparency = 1, -- In = cardTransparency(ElementTransparency)

            Parent = self.contentWrapper,
        }, { BackgroundTransparency = { "ElementTransparency", cardTransparency } })
        self.contentStroke = self.window:StyleElementBody(self.contentCard)
        contentParent = self.contentCard
    end

    self.window:Create("UIPadding", {
        PaddingTop = UDim.new(0, contentPadTop),
        PaddingBottom = UDim.new(0, contentPadBottom),

        Parent = contentParent,
    })

    self.tabPage = contentParent

    -- children build through here - see file header. Requiring by relative path (not a name
    -- string) since this isn't Group's own _add dispatch table.
    self._group = require(script.Parent.group).new(self, { direction = "column" })

    self.window:ConnectFor(self, self._group.main:GetPropertyChangedSignal("AbsoluteSize"), function()
        -- the card follows its content even while closed, so opening never shows a stale height
        self:_syncCard()
        if self.expanded then
            self:_setHeight(self:_contentHeight(), true)
        end
    end)

    self:_syncCard()

    -- start at the right height instantly - no animating in from 0 on first build
    if self.expanded then
        self:_setHeight(self:_contentHeight(), false)
        self.chevron.Rotation = 0
    end

    -- Tracked per-window (same shape as window.tabs) so the guided tour can find whichever
    -- collapsible actually owns a step's target and force it open - see tour.luau's own
    -- expandAncestors. No corresponding removal on teardown: nothing in this file destroys a
    -- Collapsible outright today, matching that this list is only ever appended to for the same
    -- reason window.tabs itself doesn't need pruning until Tab:Remove exists on this too.
    self.window.collapsibles = self.window.collapsibles or {}
    table.insert(self.window.collapsibles, self)

    return self
end

-- the group's own real height plus the breathing room above/below it (UIPadding doesn't count
-- toward a sibling's AbsoluteSize, so it has to be added back in by hand here)
function Collapsible:_cardHeight()
    return self._group.main.AbsoluteSize.Y + contentPadTop + contentPadBottom
end

-- how tall the clipping wrapper has to be to show everything: with a card that is the gap above
-- it and the stroke room below it on top of the card itself
function Collapsible:_contentHeight()
    if self.contentCard then
        return cardGap + self:_cardHeight() + strokeRoom
    end
    return self:_cardHeight()
end

-- The card's height is set outright rather than tweened: the wrapper clips it, and it is the
-- wrapper that animates, so the card only ever needs to be the right size underneath.
function Collapsible:_syncCard()
    if self.contentCard then
        self.contentCard.Size = UDim2.new(1, -strokeRoom * 2, 0, self:_cardHeight())
    end
end

-- Drives contentWrapper's height AND main's own height together (see the comment on self.main's
-- own Create() call above for why main can't just auto-follow this itself). targetContentHeight
-- is contentWrapper's own target - main's is headerHeight taller, header + content stacked.
function Collapsible:_setHeight(targetContentHeight, animate)
    local contentSize = UDim2.new(1, 0, 0, targetContentHeight)
    local mainSize = UDim2.new(1, -20, 0, headerHeight + targetContentHeight)
    if animate then
        variables.tweenService:Create(self.contentWrapper, heightInfo, { Size = contentSize }):Play()
        variables.tweenService:Create(self.main, heightInfo, { Size = mainSize }):Play()
    else
        self.contentWrapper.Size = contentSize
        self.main.Size = mainSize
    end
end

function Collapsible:_buildHeader()
    self.header = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 43),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.main,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.header)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.header)

    self.container = self.window:Create("Frame", {
        BorderSizePixel = 0,

        Parent = self.header,
        Size = UDim2.new(1, -70, 0, 16),
        Position = UDim2.new(0, constants.elementInset, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
    })

    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, constants.elementIconGap),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(constants.elementIconSize, constants.elementIconSize),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- chevron: 180deg = closed (matches dropdown.luau's own convention), tweens to 0 on open
    self.chevron = self.window:Create("ImageLabel", {
        Image = constants.icons.chevron,
        Size = UDim2.fromOffset(12, 12),
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -20, 0.5, 0),
        Rotation = 180,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,

        ImageTransparency = 1, -- In = 0.4

        Parent = self.header,
    }, { ImageColor3 = "ContentColor" })

    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Text = "",
        AutoButtonColor = false,
        ZIndex = 10,

        Parent = self.header,
    })

    self.window:_wireElementHover({
        main = self.header,
        stroke = self.stroke,
        title = self.title,
        hoverOverlay = self.hoverOverlay,
    })

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        self:Toggle()
    end)
end

function Collapsible:Toggle()
    self:SetExpanded(not self.expanded)
end

-- Whether it is open.
function Collapsible:Get(): boolean
    return self.expanded
end

-- The shape every persisted control has, so a config restore can apply a saved open/closed state.
-- A restore snaps rather than animating: the section is being put back the way the player left it,
-- not opened in front of them.
function Collapsible:Set(expanded, skipAnimation: boolean?)
    local snap = if skipAnimation ~= nil then skipAnimation else self.window:IsRestoringConfig()
    self:SetExpanded(expanded, snap)
end

-- skipAnimation: snap straight to the target height/chevron angle instead of tweening - the
-- guided tour uses this (see tour.luau's own expandAncestors) to force a closed section open
-- without its own 0.3s motion competing with the tour's ring/bubble reveal for attention.
function Collapsible:SetExpanded(expanded, skipAnimation: boolean?)
    expanded = expanded and true or false
    if expanded == self.expanded then
        return
    end
    self.expanded = expanded
    self.value = expanded
    self.window:_persist(self)

    self:_setHeight(if expanded then self:_contentHeight() else 0, not skipAnimation)
    if skipAnimation then
        self.chevron.Rotation = if expanded then 0 else 180
    else
        variables.tweenService:Create(self.chevron, chevronInfo, { Rotation = if expanded then 0 else 180 }):Play()
    end
end

-- Forward every CreateX to the inner column group, so a Collapsible reads exactly like a Tab
-- or Group to a dev using it. Kept in sync with Group's own CreateX list (see group.luau) -
-- anything Group can host, a Collapsible's own content column can too, since it's just another
-- Group underneath.
for _, name in
    {
        "CreateButton",
        "CreateFlipButton",
        "CreateCopyButton",
        "CreateRippleButton",
        "CreateToggle",
        "CreateSwitch",
        "CreateCheckbox",
        "CreateStat",
        "CreateStatusCard",
        "CreateSlider",
        "CreateDropdown",
        "CreatePlayerDropdown",
        "CreateReorderList",
        "CreateItemGrid",
        "CreateListPicker",
        "CreateSection",
        "CreateLabel",
        "CreateParagraph",
        "CreateDivider",
        "CreateGroup",
        "CreateProgressBar",
        "CreateScrollHint",
        "CreateSegmentedPicker",
        "CreateShimmerLabel",
        "CreateInput",
        "CreateKeybind",
        "CreateColorPicker",
        "CreateGradientPicker",
        "CreateHoldButton",
        "CreateChangelog",
        "CreateSpacer",
        "CreateTabbox",
        "CreatePanel",
        "CreateChart",
        "CreateStackedChart",
        "CreateCountdown",
        "CreateFAQ",
        "CreateTable",
        "CreateStepper",
        "CreateConsole",
        "CreateCollapsible",
    }
do
    Collapsible[name] = function(self, properties)
        return self._group[name](self._group, properties)
    end
end

function Collapsible:_setShown(shown, animate)
    local w = self.window
    local proxy = { stroke = self.stroke, title = self.title, main = self.header, iconLabel = self.iconLabel }
    if shown then
        w:_revealCommon(proxy, animate)
        w:_reveal(self.chevron, { ImageTransparency = 0.4 }, animate)
    else
        w:_hideCommon(proxy, animate)
        w:_reveal(self.chevron, { ImageTransparency = 1 }, animate)
    end
    if self.contentCard then
        w:_reveal(self.contentCard, {
            BackgroundTransparency = if shown then cardTransparency(w.theme.ElementTransparency) else 1,
        }, animate)
        w:_reveal(self.contentStroke, {
            Transparency = if shown then w.theme.ElementStrokeTransparency else 1,
        }, animate)
    end
    self._group:_setShown(shown, animate)
end

function Collapsible:_refreshTheme()
    self._group:_refreshTheme()
end

moveable(Collapsible)

return Collapsible
]=====]

sources["components/colorpicker"] = [=====[
--!nonstrict

