-- Devlog 5 rebuild: a collapsed header row (name + a live colour swatch pill) that taps open
-- into a hex field, RGB number boxes, a big swatch bar and quick-pick presets on the left, and a
-- Saturation/Value square + horizontal Hue rail (hsvEditor.luau, shared with GradientPicker) on
-- the right - same open/close shape as GradientPicker so the two pickers behave identically.
-- Reflows to a single stacked column under narrowWidth.

local ColorPicker = {}
ColorPicker.__index = ColorPicker
ColorPicker.__type = "ColorPicker"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local constants = require(utility.constants)
-- the height of a one-line card (see constants.elementHeight)
local elementHeight = constants.elementHeight
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)
local hsvEditor = require(utility.hsvEditor)

local headerHeight = elementHeight
local squareSize = 150
local rowGap = 8
local narrowWidth = 380
local glowOnTransparency = 0.55

local fadeInfo = TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
-- closing fades faster than it opens, and faster than the card shrinks, so the content is
-- gone before (or right as) the height tween finishes instead of visibly cutting off mid-fade
local closeFadeInfo = TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
-- closing height: Quart out, quick and clean, no overshoot
local heightInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
-- opening height: Back out - grows slightly past the final height then eases back, matching
-- GradientPicker's own open bounce
local heightOpenInfo = TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
local chevronInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
-- header swatch "pop" on click
local popOutInfo = TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local popBackInfo = TweenInfo.new(0.28, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
-- glow pulse on open: flashes brighter than the steady-state glow, then relaxes back down to it
local glowPulseInfo = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local glowRelaxInfo = TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
-- delay between each staggered reveal group when opening
local staggerStep = 0.05
local swatchSize = UDim2.fromOffset(40, 22)

local function clampByte(n)
    return math.clamp(math.round(n), 0, 255)
end

local function clamp01(n)
    return math.clamp(n, 0, 1)
end

-- named colours accepted by the smart hex field
local namedColors = {
    black = Color3.fromRGB(0, 0, 0),
    white = Color3.fromRGB(255, 255, 255),
    red = Color3.fromRGB(255, 0, 0),
    green = Color3.fromRGB(0, 255, 0),
    blue = Color3.fromRGB(0, 0, 255),
    yellow = Color3.fromRGB(255, 255, 0),
    cyan = Color3.fromRGB(0, 255, 255),
    magenta = Color3.fromRGB(255, 0, 255),
    orange = Color3.fromRGB(255, 165, 0),
    purple = Color3.fromRGB(128, 0, 128),
    pink = Color3.fromRGB(255, 105, 180),
    brown = Color3.fromRGB(139, 69, 19),
    gray = Color3.fromRGB(128, 128, 128),
    grey = Color3.fromRGB(128, 128, 128),
}

local function numbersIn(s)
    local out = {}
    for n in s:gmatch("[%d%.]+") do
        table.insert(out, tonumber(n))
    end
    return out
end

-- Smart, forgiving colour parse: hex (#fff, ffffff, 0xffffff), rgb("255,0,0"), 0..1 float
-- triplets, or a named colour. Returns a Color3 or nil.
local function parseColor(input)
    if typeof(input) ~= "string" then
        return nil
    end
    local s = (input:lower():match("^%s*(.-)%s*$")) or ""
    if s == "" then
        return nil
    end

    if namedColors[s] then
        return namedColors[s]
    end

    local model = s:match("^(%a+)")
    local nums = numbersIn(s)

    if (model == "rgb" or model == "rgba") and #nums >= 3 then
        return Color3.fromRGB(clampByte(nums[1]), clampByte(nums[2]), clampByte(nums[3]))
    end

    local hex = s:match("^#?(%x%x%x%x%x%x)$") or s:match("^#?(%x%x%x)$") or s:match("^0x(%x%x%x%x%x%x)$")
    if hex then
        local ok, color = pcall(Color3.fromHex, hex)
        if ok then
            return color
        end
    end

    if #nums >= 3 and not model then
        if nums[1] <= 1 and nums[2] <= 1 and nums[3] <= 1 then
            return Color3.new(clamp01(nums[1]), clamp01(nums[2]), clamp01(nums[3]))
        end
        return Color3.fromRGB(clampByte(nums[1]), clampByte(nums[2]), clampByte(nums[3]))
    end

    return nil
end

local function coerceColor(value, fallback)
    if typeof(value) == "Color3" then
        return value
    end
    if typeof(value) == "string" then
        return parseColor(value) or fallback
    end
    return fallback
end

local defaultPresets = {
    Color3.fromRGB(255, 255, 255),
    Color3.fromRGB(255, 59, 48),
    Color3.fromRGB(255, 149, 0),
    Color3.fromRGB(255, 214, 10),
    Color3.fromRGB(52, 199, 89),
    Color3.fromRGB(10, 132, 255),
    Color3.fromRGB(175, 82, 222),
}

function ColorPicker.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Color Picker",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState,
        presets = properties.presets or properties.Presets or defaultPresets,

        callback = properties.callback or properties.Callback or function() end,

        _isOpen = false,
        showGlow = if properties.glow ~= nil
            then properties.glow
            elseif properties.Glow ~= nil then properties.Glow
            else true,
    }, ColorPicker)

    self.value = coerceColor(
        functions.readValue(properties, { "color", "Color", "value", "Value" }),
        Color3.fromRGB(255, 255, 255)
    )
    self.hue, self.sat, self.val = self.value:ToHSV()

    local a = properties.alpha or properties.Alpha
    self.alpha = if type(a) == "number" then clamp01(a) else 1

    self.flag = properties.flag
        or properties.Flag
        or (not self.forgetState and functions.deriveFlagFromName(self.name) or nil)
    self.window:_registerControl(self)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, headerHeight),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.main)
    self.previewGlow = self.window:CreateGlow(self.main, self.value, 26, 1) -- In = glowOnTransparency (if showGlow)

    self:_buildHeader()
    self:_buildBody()

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        self:_popSwatch()
        if self._isOpen then
            self:_close()
        else
            self:_open()
        end
    end)

    self.window:ConnectFor(self, self.main.MouseEnter, function()
        if self._isOpen or not self.window:_interactive() then
            return
        end
        local theme = self.window.theme
        variables.tweenService
            :Create(
                self.stroke,
                fadeInfo,
                { Transparency = theme.ElementStrokeHoverTransparency, Color = theme.ElementStrokeHover }
            )
            :Play()
        variables.tweenService:Create(self.title, fadeInfo, { TextColor3 = theme.ElementTextHoverColor }):Play()
        variables.tweenService:Create(self.hoverOverlay, fadeInfo, { BackgroundTransparency = 0.97 }):Play()
    end)

    self.window:ConnectFor(self, self.main.MouseLeave, function()
        local theme = self.window.theme
        variables.tweenService
            :Create(
                self.stroke,
                fadeInfo,
                { Transparency = theme.ElementStrokeTransparency, Color = theme.ElementStroke }
            )
            :Play()
        variables.tweenService:Create(self.title, fadeInfo, { TextColor3 = theme.ContentColor }):Play()
        variables.tweenService:Create(self.hoverOverlay, fadeInfo, { BackgroundTransparency = 1 }):Play()
    end)

    self.window:ConnectFor(self, self.main:GetPropertyChangedSignal("AbsoluteSize"), function()
        if self.window.animating or (self.window.hidden and self.window.hasShownOnce) then
            return
        end
        self:_applyLayout()
    end)
    self:_applyLayout()

    self.window:_wireTooltip(self)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    self:_applyBodyVisibility(false, false)
    self:_setControlsVisible(false)

    self:_render("instant")

    return self
end

function ColorPicker:_buildHeader()
    local container = self.window:Create("Frame", {
        Size = UDim2.new(1, -90, 0, 16),
        Position = UDim2.new(0, constants.elementInset, 0, headerHeight / 2),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 5,

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        Padding = UDim.new(0, constants.elementIconGap),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(constants.elementIconSize, constants.elementIconSize),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            ZIndex = 5,

            ImageTransparency = 1, -- In = 0

            Parent = container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 1,
        ZIndex = 5,

        TextTransparency = 1, -- In = 0

        Parent = container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- small always-on colour pill in the header, live even while collapsed - mirrors
    -- GradientPicker's header swatch so both pickers read the same way at a glance
    self.swatch = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -16, 0, headerHeight / 2),
        Size = swatchSize,
        BackgroundColor3 = self.value,
        BorderSizePixel = 0,
        ZIndex = 3,

        BackgroundTransparency = 1, -- In = 0

        Parent = self.main,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = self.swatch })

    -- chevron: 180deg = closed (matches dropdown.luau's own convention), tweens to 0 on open
    self.chevron = self.window:Create("ImageLabel", {
        Image = constants.icons.chevron,
        Size = UDim2.fromOffset(12, 12),
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -64, 0, headerHeight / 2),
        Rotation = 180,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        ZIndex = 3,

        ImageTransparency = 1, -- In = 0.4

        Parent = self.main,
    }, { ImageColor3 = "ContentColor" })

    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, headerHeight),
        BorderSizePixel = 0,
        Text = "",
        AutoButtonColor = false,
        ZIndex = 10,

        Parent = self.main,
    })
end

-- A small rounded field: an optional single-letter label (R/G/B) left, a TextBox filling the
-- rest. Used for the hex box (no label) and the three RGB channel boxes.
function ColorPicker:_buildField(label, placeholder)
    local box = self.window:Create("Frame", {
        Size = UDim2.fromOffset(0, 34),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 2,

        BackgroundTransparency = 1, -- Open = 0.85

        Parent = self.main,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = box })
    local stroke = self.window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),

        Transparency = 1, -- Open = 0.75

        Parent = box,
    })

    local padLeft = if label then 30 else 12
    local input = self.window:Create("TextBox", {
        PlaceholderText = placeholder or "",
        Size = UDim2.new(1, -(padLeft + 10), 1, 0),
        Position = UDim2.new(0, padLeft, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        ClearTextOnFocus = false,
        ZIndex = 3,

        TextTransparency = 1, -- Open = 0

        Parent = box,
    }, { TextColor3 = "ContentColor", FontFace = "Font", PlaceholderColor3 = "PlaceholderColor" })

    local text = nil
    if label then
        text = self.window:Create("TextLabel", {
            Text = label,
            Size = UDim2.fromOffset(16, 34),
            Position = UDim2.new(0, 10, 0.5, 0),
            AnchorPoint = Vector2.new(0, 0.5),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 13,
            ZIndex = 3,

            TextTransparency = 1, -- Open = 0.4

            Parent = box,
        }, { TextColor3 = "PlaceholderColor", FontFace = "Font" })
    end

    return box, input, stroke, text
end

function ColorPicker:_buildBody()
    -- hex field
    self.hexBox, self.hexInput, self.hexBoxStroke = self:_buildField(nil, "Hex")
    self.hexInput.Text = "#" .. self.value:ToHex():upper()
    self.hexInput.TextXAlignment = Enum.TextXAlignment.Center

    -- RGB row: three equal fields sharing one flex-filled row
    self.rgbRow = self.window:Create("Frame", {
        Size = UDim2.fromOffset(0, 34),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 2,

        Parent = self.main,
    })
    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        HorizontalFlex = Enum.UIFlexAlignment.Fill,
        Padding = UDim.new(0, 8),

        Parent = self.rgbRow,
    })

    self.rBox, self.rInput, self.rBoxStroke, self.rBoxText = self:_buildRgbField("R")
    self.gBox, self.gInput, self.gBoxStroke, self.gBoxText = self:_buildRgbField("G")
    self.bBox, self.bInput, self.bBoxStroke, self.bBoxText = self:_buildRgbField("B")

    -- big live swatch bar
    self.swatchBar = self.window:Create("Frame", {
        Size = UDim2.fromOffset(0, 34),
        BackgroundColor3 = self.value,
        BorderSizePixel = 0,
        ZIndex = 2,

        BackgroundTransparency = 1, -- Open = 0

        Parent = self.main,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = self.swatchBar })

    -- preset swatches row
    self.presetsRow = self.window:Create("Frame", {
        Size = UDim2.fromOffset(0, 26),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 2,

        Parent = self.main,
    })
    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Padding = UDim.new(0, 8),

        Parent = self.presetsRow,
    })

    self.presetButtons = {}
    for _, color in self.presets do
        local dot = self.window:Create("TextButton", {
            Size = UDim2.fromOffset(26, 26),
            BackgroundColor3 = color,
            BorderSizePixel = 0,
            Text = "",
            AutoButtonColor = false,
            ZIndex = 2,

            BackgroundTransparency = 1, -- Open = 0

            Parent = self.presetsRow,
        })
        self.window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = dot })
        local ring = self.window:Create("UIStroke", {
            Color = Color3.fromRGB(255, 255, 255),
            Thickness = 2,
            Transparency = 1, -- managed by _render (selection ring), forced shut while closed

            Parent = dot,
        })
        table.insert(self.presetButtons, { color = color, dot = dot, ring = ring })

        self.window:ConnectFor(self, dot.MouseButton1Click, function()
            hapticEngine.click()
            soundEngine.click()
            self:Set(color)
            self.window:_persist(self)
        end)
    end

    -- shared HSV editor, right column
    self.hsv = hsvEditor.build(self.window, self, self.main, {
        squareSize = squareSize,
        hueHeight = 14,
        gap = 14,
        hue = self.hue,
        sat = self.sat,
        val = self.val,
        onChange = function(h, s, v)
            self.hue, self.sat, self.val = h, s, v
            self.value = Color3.fromHSV(h, s, v)
            self:_render("drag")
            self:_fireCallback()
        end,
        onCommit = function()
            self.window:_persist(self)
        end,
    })

    self.window:ConnectFor(self, self.hexInput.FocusLost, function()
        local color = parseColor(self.hexInput.Text)
        if color then
            self:Set(color)
            self.window:_persist(self)
        else
            self.hexInput.Text = "#" .. self.value:ToHex():upper()
        end
    end)

    local function commitRgb()
        local r = tonumber(self.rInput.Text) or self.value.R * 255
        local g = tonumber(self.gInput.Text) or self.value.G * 255
        local b = tonumber(self.bInput.Text) or self.value.B * 255
        self:Set(Color3.fromRGB(clampByte(r), clampByte(g), clampByte(b)))
        self.window:_persist(self)
    end
    self.window:ConnectFor(self, self.rInput.FocusLost, commitRgb)
    self.window:ConnectFor(self, self.gInput.FocusLost, commitRgb)
    self.window:ConnectFor(self, self.bInput.FocusLost, commitRgb)
end

function ColorPicker:_buildRgbField(label)
    local box = self.window:Create("Frame", {
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 2,

        BackgroundTransparency = 1, -- Open = 0.85

        Parent = self.rgbRow,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = box })
    local stroke = self.window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),

        Transparency = 1, -- Open = 0.75

        Parent = box,
    })

    local text = self.window:Create("TextLabel", {
        Text = label,
        Size = UDim2.fromOffset(14, 34),
        Position = UDim2.new(0, 8, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 13,
        ZIndex = 3,

        TextTransparency = 1, -- Open = 0.4

        Parent = box,
    }, { TextColor3 = "PlaceholderColor", FontFace = "Font" })

    local input = self.window:Create("TextBox", {
        Size = UDim2.new(1, -28, 1, 0),
        Position = UDim2.new(0, 24, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        ClearTextOnFocus = false,
        ZIndex = 3,

        TextTransparency = 1, -- Open = 0

        Parent = box,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    return box, input, stroke, text
end

function ColorPicker:_render(mode)
    self.swatch.BackgroundColor3 = self.value
    self.swatchBar.BackgroundColor3 = self.value
    self.hsv:SetColor(self.hue, self.sat, self.val, mode ~= "instant")

    if not self.hexInput:IsFocused() then
        self.hexInput.Text = "#" .. self.value:ToHex():upper()
    end
    if not self.rInput:IsFocused() then
        self.rInput.Text = tostring(math.round(self.value.R * 255))
    end
    if not self.gInput:IsFocused() then
        self.gInput.Text = tostring(math.round(self.value.G * 255))
    end
    if not self.bInput:IsFocused() then
        self.bInput.Text = tostring(math.round(self.value.B * 255))
    end

    self.previewGlow.Color = self.value
    for _, entry in self.presetButtons do
        entry.ring.Transparency = if entry.color == self.value and self._isOpen then 0 else 1
    end
end

function ColorPicker:_fireCallback()
    self.window:_runGuarded(self, self.callback, self.value, self.alpha)
end

-- Quick tactile feedback on the header swatch the instant it's clicked, independent of (and
-- faster than) the open/close animation that follows - squashes narrower, then springs back
-- past its resting width before settling (Back easing) for a little bounce.
function ColorPicker:_popSwatch()
    local squashed = UDim2.fromOffset(swatchSize.X.Offset * 0.85, swatchSize.Y.Offset * 0.85)
    local outTween = variables.tweenService:Create(self.swatch, popOutInfo, { Size = squashed })
    outTween:Play()
    local connection
    connection = outTween.Completed:Connect(function()
        connection:Disconnect()
        variables.tweenService:Create(self.swatch, popBackInfo, { Size = swatchSize }):Play()
    end)
end

function ColorPicker:_open()
    if self._isOpen then
        return
    end
    self._isOpen = true
    self._openSeq = (self._openSeq or 0) + 1
    local seq = self._openSeq
    self:_setControlsVisible(true)

    if self._outsideClickConn then
        self.window:Disconnect(self._outsideClickConn)
    end
    self._outsideClickConn = self.window:Connect(variables.userInputService.InputBegan, function(input)
        if
            input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch
        then
            return
        end
        local pos = input.Position
        local mainPos = self.main.AbsolutePosition
        local mainSize = self.main.AbsoluteSize
        if
            pos.X < mainPos.X
            or pos.X > mainPos.X + mainSize.X
            or pos.Y < mainPos.Y
            or pos.Y > mainPos.Y + mainSize.Y
        then
            self:_close()
        end
    end)

    -- card grows with a slight bounce past its final height instead of a flat stop
    variables.tweenService:Create(self.main, heightOpenInfo, { Size = UDim2.new(1, -20, 0, self._openHeight) }):Play()
    variables.tweenService:Create(self.chevron, chevronInfo, { Rotation = 0 }):Play()

    -- glow pulse: flashes past its steady-state glow, then relaxes back down to it
    if self.showGlow then
        variables.tweenService
            :Create(self.previewGlow, glowPulseInfo, { Transparency = math.max(0, glowOnTransparency - 0.3) })
            :Play()
        task.delay(glowPulseInfo.Time, function()
            if self._isOpen and self._openSeq == seq then
                variables.tweenService
                    :Create(self.previewGlow, glowRelaxInfo, { Transparency = glowOnTransparency })
                    :Play()
            end
        end)
    end

    -- staggered reveal: hex first, then RGB, then swatch+presets, then the HSV editor
    self:_revealHex(true, fadeInfo)
    task.delay(staggerStep, function()
        if self._isOpen and self._openSeq == seq then
            self:_revealRgb(true, fadeInfo)
        end
    end)
    task.delay(staggerStep * 2, function()
        if self._isOpen and self._openSeq == seq then
            self:_revealSwatchAndPresets(true, fadeInfo)
        end
    end)
    task.delay(staggerStep * 3, function()
        if self._isOpen and self._openSeq == seq then
            self.hsv:SetVisible(true, true)
        end
    end)

    self:_render("animate")
end

function ColorPicker:_close()
    if not self._isOpen then
        return
    end
    self._isOpen = false
    self._openSeq = (self._openSeq or 0) + 1 -- invalidates any staggered/delayed open steps still pending

    if self._outsideClickConn then
        self.window:Disconnect(self._outsideClickConn)
        self._outsideClickConn = nil
    end
    if self.hexInput:IsFocused() then
        self.hexInput:ReleaseFocus()
    end

    -- everything fades out together (no stagger) on the quicker closeFadeInfo, so the content
    -- is gone before (or right as) the height tween below finishes instead of cutting off mid-fade
    self:_applyBodyVisibility(false, closeFadeInfo)
    self.hsv:SetVisible(false, true)
    self:_render("animate") -- also drops the preset ring now that _isOpen is false
    variables.tweenService:Create(self.main, heightInfo, { Size = UDim2.new(1, -20, 0, headerHeight) }):Play()
    variables.tweenService:Create(self.chevron, chevronInfo, { Rotation = 180 }):Play()

    task.delay(closeFadeInfo.Time, function()
        if not self._isOpen then
            self:_setControlsVisible(false)
        end
    end)
end

-- Wide: hex/RGB/swatch/presets left, square+hue right, side by side.
-- Narrow: same stack, full width, with the editor centred underneath.
function ColorPicker:_applyLayout()
    local width = self.main.AbsoluteSize.X
    local mode = if width > 0 and width < narrowWidth then "narrow" else "wide"
    if mode == self._layoutMode then
        return
    end
    self._layoutMode = mode

    local leftWidth = if mode == "wide" then UDim.new(1, -(20 + squareSize + 16 + 20)) else UDim.new(1, -40)
    local y = headerHeight
    self.hexBox.Position = UDim2.new(0, 20, 0, y)
    self.hexBox.Size = UDim2.new(leftWidth.Scale, leftWidth.Offset, 0, 34)
    y += 34 + rowGap

    self.rgbRow.Position = UDim2.new(0, 20, 0, y)
    self.rgbRow.Size = UDim2.new(leftWidth.Scale, leftWidth.Offset, 0, 34)
    y += 34 + rowGap

    self.swatchBar.Position = UDim2.new(0, 20, 0, y)
    self.swatchBar.Size = UDim2.new(leftWidth.Scale, leftWidth.Offset, 0, 34)
    y += 34 + rowGap + 2

    self.presetsRow.Position = UDim2.new(0, 20, 0, y)
    self.presetsRow.Size = UDim2.new(leftWidth.Scale, leftWidth.Offset, 0, 26)
    local leftBottom = y + 26

    if mode == "wide" then
        self.hsv.root.Position = UDim2.new(1, -20 - squareSize, 0, headerHeight)
        self._openHeight = math.max(leftBottom, headerHeight + squareSize + 14 + 14) + 20
    else
        local hsvY = leftBottom + 16
        self.hsv.root.Position = UDim2.new(0.5, -squareSize / 2, 0, hsvY)
        self._openHeight = hsvY + squareSize + 14 + 14 + 20
    end

    if self._isOpen then
        variables.tweenService:Create(self.main, heightInfo, { Size = UDim2.new(1, -20, 0, self._openHeight) }):Play()
    end
end

function ColorPicker:Set(color, skipCallback)
    self.value = coerceColor(color, self.value)
    self.hue, self.sat, self.val = self.value:ToHSV()
    self:_render(if skipCallback then "instant" else "animate")

    if not skipCallback then
        self:_fireCallback()
        self.window:_persist(self)
    end
end

function ColorPicker:SetAlpha(alpha, skipCallback)
    self.alpha = clamp01(if type(alpha) == "number" then alpha else self.alpha)

    if not skipCallback then
        self:_fireCallback()
        self.window:_persist(self)
    end
end

-- Toggle the ambient glow behind the card at runtime.
function ColorPicker:SetGlow(shown)
    self.showGlow = shown and true or false
    variables.tweenService
        :Create(self.previewGlow, fadeInfo, { Transparency = if self.showGlow then glowOnTransparency else 1 })
        :Play()
end

-- Persistence: RRGGBB plus an alpha byte (AA) so alpha round-trips even though this layout has
-- no alpha control of its own - a dev can still drive SetAlpha() from code.
function ColorPicker:_serialize()
    return self.value:ToHex() .. string.format("%02x", math.clamp(math.round((self.alpha or 1) * 255), 0, 255))
end

function ColorPicker:_deserialize(raw)
    local hex = tostring(raw)
    if #hex >= 8 then
        self:SetAlpha((tonumber(hex:sub(7, 8), 16) or 255) / 255, true)
        hex = hex:sub(1, 6)
    end
    self:Set(Color3.fromHex(hex))
end

local function applySet(set, animate)
    for instance, props in set do
        if animate then
            variables.tweenService:Create(instance, animate, props):Play()
        else
            for prop, value in props do
                instance[prop] = value
            end
        end
    end
end

function ColorPicker:_revealHex(open, animate)
    applySet({
        [self.hexBox] = { BackgroundTransparency = if open then 0.85 else 1 },
        [self.hexBoxStroke] = { Transparency = if open then 0.75 else 1 },
        [self.hexInput] = { TextTransparency = if open then 0 else 1 },
    }, animate)
end

function ColorPicker:_revealRgb(open, animate)
    local set = {}
    for _, field in
        {
            { self.rBox, self.rBoxStroke, self.rBoxText, self.rInput },
            { self.gBox, self.gBoxStroke, self.gBoxText, self.gInput },
            { self.bBox, self.bBoxStroke, self.bBoxText, self.bInput },
        }
    do
        local box, stroke, text, input = field[1], field[2], field[3], field[4]
        set[box] = { BackgroundTransparency = if open then 0.85 else 1 }
        set[stroke] = { Transparency = if open then 0.75 else 1 }
        set[text] = { TextTransparency = if open then 0.4 else 1 }
        set[input] = { TextTransparency = if open then 0 else 1 }
    end
    applySet(set, animate)
end

function ColorPicker:_revealSwatchAndPresets(open, animate)
    local set = { [self.swatchBar] = { BackgroundTransparency = if open then 0 else 1 } }
    for _, entry in self.presetButtons do
        set[entry.dot] = { BackgroundTransparency = if open then 0 else 1 }
        if not open then
            set[entry.ring] = { Transparency = 1 }
        end
    end
    applySet(set, animate)
end

-- Every OPEN-only body part (hex/RGB fields, swatch bar, presets), all pulled from the same
-- three group methods above so both the initial hidden state at build and a plain (non-
-- staggered) open/close use exactly the same values the staggered _open() sequence does. The
-- header swatch pill is NOT in here since it stays visible whether the card is open or closed.
-- hsvEditor manages its own instances.
function ColorPicker:_applyBodyVisibility(open, animate)
    self:_revealHex(open, animate)
    self:_revealRgb(open, animate)
    self:_revealSwatchAndPresets(open, animate)
end

-- The open-only controls sit below the header even while collapsed (the card doesn't clip), so
-- a transparent TextBox/button down there would still catch the cursor. Toggling them off drops
-- the whole cluster out of input while closed - the header swatch pill is separate, stays put.
function ColorPicker:_setControlsVisible(visible)
    for _, frame in { self.hexBox, self.rgbRow, self.swatchBar, self.presetsRow, self.hsv.root } do
        frame.Visible = visible
    end
end

function ColorPicker:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.swatch, { BackgroundTransparency = 0 }, animate)
        w:_reveal(self.chevron, { ImageTransparency = 0.4 }, animate)
        w:_reveal(self.previewGlow, { Transparency = if self.showGlow then glowOnTransparency else 1 }, animate)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.swatch, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.chevron, { ImageTransparency = 1 }, animate)
        w:_reveal(self.previewGlow, { Transparency = 1 }, animate)
        if self._isOpen then
            self:_close()
        end
    end
end

moveable(ColorPicker)
lockable(ColorPicker)

return ColorPicker
]=====]

sources["components/console"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A monospaced block for code or log output. It holds the height it's given and scrolls inside
-- itself, so a console that fills up doesn't push the rest of the page down the screen. Ported
-- from upstream Rayfield Gen2 1.2's own Console element.
--
-- Lines can be plain text or styled: a colour, bold/italic/underline/strike, a highlight, a
-- size. `Append("Loaded", { color = "success" })` styles the whole line, and a list of parts
-- styles them one by one. What the buffer holds is the plain text either way, so Get() and Copy()
-- hand back what the panel reads as, never the markup behind it - see utility/richtext.luau.
--
-- One label per line, not one label for the whole body: a single auto-sized label inside a
-- fixed-height scroller gets clamped to one viewport, and the canvas then has nothing to
-- scroll. A row each keeps every label short enough that its own height is never the thing
-- being clamped, and the list layout measures the canvas for us.

local Console = {}
Console.__index = Console
Console.__type = "Console"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local moveable = require(utility.moveable)
local locale = require(utility.locale)
local clipboard = require(utility.clipboard)
local richtext = require(utility.richtext)

local defaultHeight = 120
local minHeight = 48
local titleHeight = 24 -- the row the name sits on, when there is one
local padding = 17
local textPadding = 12 -- inside the panel; log output sits close to its edge
local textSize = 12
local lineHeight = 1.25 -- dense, the way a real log reads

-- How many lines the block keeps. Past this the oldest roll off the top, so a console left
-- running all session cant grow without end.
local defaultMaxLines = 200

-- Monospace, so columns line up. Not the brand font: this is output, not copy.
local monoFont = Font.fromEnum(Enum.Font.Code)

-- What a line's own style table can carry. Anything else in it is ignored rather than guessed at.
local styleKeys = {
    "color",
    "bold",
    "italic",
    "underline",
    "strike",
    "strikethrough",
    "highlight",
    "size",
    "transparency",
}

-- The tag Info/Success/Warn/Error put in front of their line. Padded to the same width so the
-- messages still line up in a column under each other, which is the whole point of a monospaced
-- block - and coloured, which is the point of this.
local levels = {
    info = { tag = "INFO ", color = "info" },
    success = { tag = "OK   ", color = "success" },
    warn = { tag = "WARN ", color = "warning" },
    error = { tag = "ERROR", color = "error" },
}

local defaultTimestampFormat = "%H:%M:%S"

local function isStyleTable(value): boolean
    if type(value) ~= "table" then
        return false
    end
    if value.text ~= nil or value.Text ~= nil then
        return true
    end
    for _, key in styleKeys do
        if value[key] ~= nil then
            return true
        end
    end
    return false
end

-- A segment's own style, lifted off the segment table so { text = "x", color = "red" } works
-- without the caller nesting a style table inside it.
local function styleOf(segment): { [string]: any }?
    local style: { [string]: any } = {}
    local any = false
    for _, key in styleKeys do
        if segment[key] ~= nil then
            style[key] = segment[key]
            any = true
        end
    end
    return if any then style else nil
end

-- A segment's own keys win over the line's, so Append(parts, { color = "muted" }) is a default
-- the parts can each step out of.
local function mergeStyles(base, extra)
    if base == nil then
        return extra
    end
    if extra == nil then
        return base
    end
    local merged = table.clone(base)
    for key, value in extra do
        merged[key] = value
    end
    return merged
end

-- Flatten whatever was passed in into { { text = ..., style = ... }, ... }.
local function normalize(content, style, out)
    out = out or {}
    if type(content) == "table" then
        if isStyleTable(content) then
            local text = content.text or content.Text or content[1]
            if text ~= nil then
                table.insert(out, { text = tostring(text), style = mergeStyles(style, styleOf(content)) })
            end
        else
            for _, part in ipairs(content) do
                normalize(part, style, out)
            end
        end
    elseif content ~= nil then
        table.insert(out, { text = tostring(content), style = style })
    end
    return out
end

function Console.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name,
        description = properties.description or properties.Description,

        height = math.max(tonumber(properties.height or properties.Height) or defaultHeight, minHeight),
        -- a log pins itself to the newest line; a code sample stays where you left it
        follow = properties.follow or properties.Follow or false,
        maxLines = math.max(tonumber(properties.maxLines or properties.MaxLines) or defaultMaxLines, 1),

        -- Raw Roblox RichText, written by the dev: a string append is passed through as markup
        -- rather than escaped. Off by default, because output is output - a log line with a "<"
        -- in it must not be able to turn the rest of the row into a tag.
        richText = properties.richText or properties.RichText or false,

        lines = {},
        -- Per line, parallel to lines: false for a plain one, otherwise the segments (or the raw
        -- markup) it was written with. Kept rather than the rendered string so a theme swap can
        -- re-render a line whose colour follows the theme.
        specs = {},
        -- Pooled and recycled in a ring. Appending at capacity rewrites one label and gives it
        -- the next LayoutOrder, so a line costs the same whether the buffer holds ten or a
        -- thousand - rewriting every row on every append is what makes a console crawl.
        lineLabels = {},
        head = 1, -- the pooled label holding the oldest line
        nextOrder = 1,
        textDirty = true,
    }, Console)

    -- true (the default format), false, or a format string for os.date
    local timestamps = properties.timestamps
    if timestamps == nil then
        timestamps = properties.Timestamps
    end
    if timestamps == true then
        timestamps = defaultTimestampFormat
    end
    self.timestamps = if type(timestamps) == "string" then timestamps else nil

    self:_build()
    self:_setLines(properties.text or properties.Text or "")

    -- A line coloured "accent"/"text"/"muted" follows the window's theme, and nothing else would
    -- tell it the theme changed: the labels carry their colours inside their own markup.
    self.window:OnThemeChanged(function()
        if self._styled and not self.removed then
            self:_flush()
        end
    end)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- The body as one string. Built on demand: joining every line on each append would put an O(n)
-- cost on the one path that has to stay cheap.
function Console:Get(): string
    if self.textDirty then
        self.text = table.concat(self.lines, "\n")
        self.textDirty = false
    end
    return self.text
end

-- What this console paints against, for the colour names that come in a dark and a light half.
function Console:_context(): { [string]: any }
    local theme = self.window.theme
    return { theme = theme, light = richtext.isLight(theme and theme.StatBackground) }
end

-- The timestamp a line is stamped with as it arrives, or nil when the console doesn't do those.
function Console:_stamp(): string?
    if not self.timestamps then
        return nil
    end
    local ok, text = pcall(os.date, self.timestamps)
    return if ok and type(text) == "string" then text else nil
end

-- Whatever was passed to Append/Set, as a list of { plain = "...", spec = false | {...} } - one
-- entry per line, since a single append can carry newlines and a style can span them.
function Console:_compose(content, style): { { plain: string, spec: any } }
    local stamp = self:_stamp()
    local entries = {}

    local function add(plain: string, spec)
        if stamp then
            -- the time reads as part of the line (it is copied with it), just quieter
            local segments
            if spec and spec.raw then
                segments = { { text = spec.raw, raw = true, style = spec.style } }
            elseif spec and spec.segs then
                segments = spec.segs
            else
                segments = { { text = plain } }
            end
            table.insert(segments, 1, { text = stamp .. " ", style = { color = "muted" } })
            plain = stamp .. " " .. plain
            spec = { segs = segments }
        end
        table.insert(entries, { plain = plain, spec = spec or false })
    end

    -- the dev's own markup, passed through: only for a bare string on a richText console
    if self.richText and type(content) == "string" then
        for part in string.gmatch(content .. "\n", "([^\n]*)\n") do
            add(richtext.strip(part), { raw = part, style = style })
        end
        return entries
    end

    local segments = normalize(content, style)
    if #segments == 0 then
        return entries
    end

    local plain, styled, current = {}, false, {}
    local function flushLine()
        add(table.concat(plain), if styled then { segs = current } else false)
        plain, styled, current = {}, false, {}
    end

    for _, segment in segments do
        local first = true
        for part in string.gmatch(segment.text .. "\n", "([^\n]*)\n") do
            if not first then
                flushLine()
            end
            first = false
            if part ~= "" then
                table.insert(plain, part)
                table.insert(current, { text = part, style = segment.style })
                styled = styled or segment.style ~= nil
            end
        end
    end
    flushLine()

    return entries
end

-- Replace the whole body.
function Console:_setLines(content, style)
    table.clear(self.lines)
    table.clear(self.specs)

    if content ~= nil and content ~= "" then
        for _, entry in self:_compose(content, style) do
            table.insert(self.lines, entry.plain)
            table.insert(self.specs, entry.spec)
            self._styled = self._styled or entry.spec ~= false
        end
    end

    self:_trim()
    self:_flush()
end

-- A line's text as the label wants it: escaped, or wrapped in the tags its style asks for.
function Console:_render(index: number): string
    local spec = self.specs[index]
    if not spec then
        return richtext.escape(self.lines[index])
    end

    local context = self:_context()
    if spec.raw then
        return richtext.wrap(spec.raw, spec.style, context)
    end

    local out = {}
    for _, segment in spec.segs do
        local text = if segment.raw then segment.text else richtext.escape(segment.text)
        table.insert(out, richtext.wrap(text, segment.style, context))
    end
    return table.concat(out)
end

-- Drop from the front until the buffer fits. table.move rather than repeated table.remove, so
-- a burst of output doesn't turn into a quadratic shuffle.
function Console:_trim()
    local excess = #self.lines - self.maxLines
    if excess <= 0 then
        return
    end
    table.move(self.lines, excess + 1, #self.lines, 1)
    table.move(self.specs, excess + 1, #self.specs, 1)
    for index = #self.lines, #self.lines - excess + 1, -1 do
        self.lines[index] = nil
        self.specs[index] = nil
    end
end

-- A row for a line. Created once and then recycled; the pool never exceeds maxLines.
function Console:_makeLabel()
    return self.window:Create("TextLabel", {
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        FontFace = monoFont,
        TextSize = textSize,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        TextWrapped = true,
        LineHeight = lineHeight,
        -- On, so a styled line can paint itself. What a player's own text contains is escaped
        -- before it gets here (richtext.escape), so an angle bracket in a log line is still an
        -- angle bracket, not the start of a tag.
        RichText = true,

        -- a line added after the reveal comes in at whatever the rest are already at
        TextTransparency = self._textTransparency or 1,

        Parent = self.scroll,
    }, { TextColor3 = "ContentColor" })
end

-- a blank line still has to take a row, and an empty label collapses to nothing
local function rowText(line: string): string
    return if line == "" then " " else line
end

-- What a row's label should say, given the line index.
function Console:_rowText(index: number): string
    if self.lines[index] == "" then
        return " "
    end
    return rowText(self:_render(index))
end

-- Rebuild every row from the buffer. Only the paths that replace the whole body use this;
-- Append has its own O(1) route below.
function Console:_flush()
    self.textDirty = true

    for index in self.lines do
        local label = self.lineLabels[index]
        if not label then
            label = self:_makeLabel()
            self.lineLabels[index] = label
        end
        label.LayoutOrder = index
        label.Text = self:_rowText(index)
        label.Visible = true
    end
    self.lastLabel = self.lineLabels[#self.lines]

    for index = #self.lines + 1, #self.lineLabels do
        self.lineLabels[index].Visible = false
    end

    self.head = 1
    self.nextOrder = #self.lines + 1
    self:_follow()
end

-- One line, one label write. At capacity the oldest row is recycled into the newest position
-- rather than every row shuffling up, so the cost doesn't grow with the buffer.
function Console:_pushLine(entry)
    self.textDirty = true
    self._styled = self._styled or entry.spec ~= false

    if #self.lines < self.maxLines then
        table.insert(self.lines, entry.plain)
        local index = #self.lines
        self.specs[index] = entry.spec
        local label = self.lineLabels[index]
        if not label then
            label = self:_makeLabel()
            self.lineLabels[index] = label
        end
        label.LayoutOrder = self.nextOrder
        label.Text = self:_rowText(index)
        label.Visible = true
        self.nextOrder += 1
        self.lastLabel = label
        return
    end

    -- full: drop the oldest line and hand its row to the newest one. table.move rather than
    -- table.remove so the shift is one bulk copy instead of a per-element slide.
    table.move(self.lines, 2, #self.lines, 1)
    table.move(self.specs, 2, #self.specs, 1)
    self.lines[#self.lines] = entry.plain
    self.specs[#self.lines] = entry.spec

    local label = self.lineLabels[self.head]
    label.LayoutOrder = self.nextOrder
    label.Text = self:_rowText(#self.lines)
    label.Visible = true

    self.nextOrder += 1
    self.head = (self.head % #self.lineLabels) + 1
    self.lastLabel = label
end

function Console:_build()
    local top = if self.name then titleHeight else 0

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, self.height + top + padding * 2),
        BorderSizePixel = 0,
        Name = self.name or "Console",
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        -- Animation
        BackgroundTransparency = 1, -- In = 0

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)

    if self.name then
        self.container = self.window:Create("Frame", {
            Size = UDim2.new(1, -padding * 2, 0, 16),
            Position = UDim2.new(0, padding, 0, padding),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,

            Parent = self.main,
        })

        self.title = self.window:Create("TextLabel", {
            Text = locale.t(self.name),

            Size = UDim2.fromScale(1, 1),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            TextSize = 16,
            TextXAlignment = Enum.TextXAlignment.Left,

            -- Animation
            TextTransparency = 1, -- In = 0

            Parent = self.container,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })
    end

    -- The inset panel the text scrolls inside. Darker than the element it sits on, the way a
    -- terminal reads against the window around it.
    self.panel = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 1),
        Position = UDim2.new(0.5, 0, 1, -padding),
        Size = UDim2.new(1, -padding * 2, 0, self.height),
        BorderSizePixel = 0,
        ClipsDescendants = true,

        BackgroundTransparency = 1, -- In = 0

        Parent = self.main,
    }, { BackgroundColor3 = "StatBackground" })

    self.window:Create("UICorner", {
        Parent = self.panel,
    }, { CornerRadius = "ElementCornerRadius" })

    self.panelStroke = self.window:Create("UIStroke", {
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,

        -- Animation
        Transparency = 1, -- In = 0.9

        Parent = self.panel,
    }, { Color = "SurfaceStroke" })

    self.scroll = self.window:Create("ScrollingFrame", {
        Size = UDim2.new(1, -textPadding * 2, 1, -textPadding * 2),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        ScrollBarThickness = 0,
        ScrollingDirection = Enum.ScrollingDirection.Y,

        Parent = self.panel,
    })

    -- the layout is what measures the canvas, so the rows themselves can stay simple
    self.scrollLayout = self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        VerticalAlignment = Enum.VerticalAlignment.Top,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.scroll,
    })

    self:_watchCanvas()
end

-- Pin to the bottom. Asking for a position past the end is fine: Roblox clamps it to the real
-- maximum, which saves working out the viewport height ourselves.
function Console:_pin()
    local scroll = self.scroll
    if not scroll or not scroll.Parent then
        return
    end
    scroll.CanvasPosition = Vector2.new(0, scroll.AbsoluteCanvasSize.Y)
end

function Console:_follow()
    if not self.follow then
        return
    end
    self:_pin()
    task.defer(function()
        self:_pin()
    end)
end

-- The canvas only settles a frame or two after the rows change, so pinning once on Append is a
-- race. The layout's content size is the thing that actually moves, so follow that instead.
function Console:_watchCanvas()
    self.window:ConnectFor(self, self.scrollLayout:GetPropertyChangedSignal("AbsoluteContentSize"), function()
        if self.follow then
            self:_pin()
        end
    end)
end

-- Replace the whole body. Takes the same content as Append.
function Console:Set(content, style)
    self:_setLines(content, style)
end

-- Add a line to the end, the way a console does. Once the buffer is full the oldest line rolls
-- off the top, so what you see is always the newest output.
--
-- `content` is a string, a { text = ..., color = ... } part, or a list of either - so a line can be
-- one colour, or several. `style` styles the whole line, and a part's own keys win over it:
--
--     console:Append("Farm started", { color = "success", bold = true })
--     console:Append({ "Bought ", { "Golden Egg", color = "#ffcc00", bold = true }, " for 500" })
function Console:Append(content, style)
    for _, entry in self:_compose(content, style) do
        self:_pushLine(entry)
    end
    self:_follow()
end

-- One line with a coloured level tag in front, for output that is a log rather than a transcript.
function Console:Log(level, content, style)
    local descriptor = levels[string.lower(tostring(level))] or levels.info
    self:Append({ { text = descriptor.tag .. " ", color = descriptor.color, bold = true }, content }, style)
end

function Console:Info(content, style)
    self:Log("info", content, style)
end

function Console:Success(content, style)
    self:Log("success", content, style)
end

function Console:Warn(content, style)
    self:Log("warn", content, style)
end

function Console:Error(content, style)
    self:Log("error", content, style)
end

-- Rewrite the newest line in place, for output that counts rather than accumulates ("Farming...
-- 45%"). Appends instead when there is nothing there yet, and appends the rest when what's handed
-- in carries newlines.
function Console:UpdateLast(content, style)
    local entries = self:_compose(content, style)
    if #entries == 0 then
        return
    end

    if #self.lines == 0 or not self.lastLabel then
        for _, entry in entries do
            self:_pushLine(entry)
        end
        self:_follow()
        return
    end

    local index = #self.lines
    self.lines[index] = entries[1].plain
    self.specs[index] = entries[1].spec
    self._styled = self._styled or entries[1].spec ~= false
    self.textDirty = true
    self.lastLabel.Text = self:_rowText(index)

    for position = 2, #entries do
        self:_pushLine(entries[position])
    end
    self:_follow()
end

function Console:Clear()
    table.clear(self.lines)
    table.clear(self.specs)
    self:_flush()
end

-- Put the body on the clipboard, where the executor gives us one. Returns whether it landed.
--
-- Through utility/clipboard rather than reaching for `setclipboard` directly: executors name the
-- writer four different ways (setclipboard / toclipboard / set_clipboard / Clipboard.set) and it
-- probes every one off getfenv(), so this both works on more of them and stops referencing a
-- global the linter has every right to call undefined.
function Console:Copy(): boolean
    return clipboard.copy(self:Get())
end

-- Change how tall the block stands. The panel takes the height; the element grows around it.
function Console:SetHeight(height)
    self.height = math.max(tonumber(height) or defaultHeight, minHeight)
    local top = if self.name then titleHeight else 0
    self.panel.Size = UDim2.new(1, -padding * 2, 0, self.height)
    self.main.Size = UDim2.new(1, -20, 0, self.height + top + padding * 2)
end

function Console:_setShown(shown, animate)
    local w = self.window

    -- no icon and (usually) no title, so the shared reveal doesn't fit; drive the parts directly
    w:_reveal(self.main, { BackgroundTransparency = if shown then w.theme.ElementTransparency or 0 else 1 }, animate)
    w:_reveal(self.stroke, { Transparency = if shown then w.theme.ElementStrokeTransparency else 1 }, animate)
    w:_reveal(self.panel, { BackgroundTransparency = if shown then 0 else 1 }, animate)
    w:_reveal(self.panelStroke, { Transparency = if shown then 0.9 else 1 }, animate)

    self._textTransparency = if shown then 0.15 else 1
    for _, label in self.lineLabels do
        w:_reveal(label, { TextTransparency = self._textTransparency }, animate)
    end

    if self.title then
        w:_reveal(self.title, { TextTransparency = if shown then 0 else 1 }, animate)
    end
    if self.descriptor then
        w:_reveal(self.descriptor.titleLabel, { TextTransparency = if shown then 0.7 else 1 }, animate)
    end
end

function Console:Remove()
    self.removed = true -- the theme hook outlives the element, and must not touch a dead one
    if self.descriptor then
        self.descriptor:Remove()
    end
    self.main:Destroy()
end

moveable(Console)

return Console
]=====]

sources["components/copybutton"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Copies a string to the clipboard in one click. Title/icon left like Button; the pinned-right
-- "well" is the copy control itself - it pops, squishes, and swaps its icon for a checkmark that
-- reverts after 2s. Falls back gracefully (no error, just no copy) when the executor exposes no
-- clipboard writer.

local CopyButton = {}
CopyButton.__index = CopyButton
CopyButton.__type = "CopyButton"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local constants = require(utility.constants)
-- the height of a one-line card (see constants.elementHeight)
local elementHeight = constants.elementHeight
local clipboard = require(utility.clipboard)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)
local log = require(utility.log)

local wellSize = 30 -- the Concept's key
local wellRight = 12
local revertDelay = 2 -- seconds the checkmark holds before reverting

function CopyButton.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Copy",
        icon = properties.icon or properties.Icon, -- shown inside the well
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        compact = tab.compact or false,

        text = tostring(properties.text or properties.Text or properties.value or properties.Value or ""),

        callback = properties.callback or properties.Callback or function() end,

        _copyToken = 0, -- bumped per press so a rapid re-click restarts the revert cleanly
    }, CopyButton)

    if self.compact then
        self:_buildCompact()
    else
        self:_buildFull()
    end

    self.window:_wireTooltip(self)

    if self.description and not self.compact then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- The well, the Gen 3 Concept's: a small white key with a copy glyph on it, which turns into a tick
-- on a successful copy. The dev's own icon sits in front of the title like every other element's.
-- The same in both layouts; the caller places it (pinned right / flex item).
local glyphColour = Color3.fromRGB(26, 26, 26)

function CopyButton:_buildWell(parent)
    local window = self.window

    self.well = window:Create("Frame", {
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(wellSize, wellSize),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = 0
        Parent = parent,
    })

    window:Create("UICorner", {
        CornerRadius = UDim.new(0, 9),
        Parent = self.well,
    })

    window:Create("UIGradient", {
        Rotation = 90,
        Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(196, 196, 196)),
        Parent = self.well,
    })

    -- kept for anything that reaches for it; the key itself has no outline
    self.wellStroke = window:Create("UIStroke", {
        Transparency = 1,
        Parent = self.well,
    }, { Color = "SurfaceStroke" })

    self.wellScale = window:Create("UIScale", {
        Scale = 1,
        Parent = self.well,
    })

    self.copyGlyph = window:Create("ImageLabel", {
        Image = constants.icons.copy,
        Size = UDim2.fromOffset(16, 16),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        ImageColor3 = glyphColour,

        ImageTransparency = 1, -- In = 0
        Parent = self.well,
    })

    self.checkIcon = window:Create("ImageLabel", {
        Image = constants.icons.tick,
        Size = UDim2.fromOffset(16, 16),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        ImageColor3 = glyphColour,

        ImageTransparency = 1, -- swapped in on a successful copy
        Parent = self.well,
    })

    return self.well
end

-- pop -> squish -> swap to the checkmark -> settle. the swap lands at the bottom of the
-- squish, where it's smallest and the crossfade reads as one motion instead of two. Kept snappy
-- end to end (checkmark lands well under a quarter second after the press) - only the 2s hold
-- before revert is meant to read as a deliberate pause.
local popInfo = TweenInfo.new(0.06, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local squishInfo = TweenInfo.new(0.07, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
local settleInfo = TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
local crossfadeInfo = TweenInfo.new(0.06, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local revertInfo = TweenInfo.new(0.12, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

function CopyButton:_playSuccess()
    local ts = variables.tweenService
    self._copyToken += 1
    local token = self._copyToken

    ts:Create(self.wellScale, popInfo, { Scale = 1.12 }):Play()
    task.delay(popInfo.Time, function()
        if self._copyToken ~= token then
            return
        end
        ts:Create(self.wellScale, squishInfo, { Scale = 0.82 }):Play()
        task.delay(squishInfo.Time, function()
            if self._copyToken ~= token then
                return
            end
            -- swap at the squish's low point
            ts:Create(self.copyGlyph, crossfadeInfo, { ImageTransparency = 1 }):Play()
            ts:Create(self.checkIcon, crossfadeInfo, { ImageTransparency = 0 }):Play()
            ts:Create(self.wellScale, settleInfo, { Scale = 1 }):Play()

            task.delay(revertDelay, function()
                if self._copyToken ~= token then
                    return -- a newer press already owns the well
                end
                ts:Create(self.copyGlyph, revertInfo, { ImageTransparency = 0 }):Play()
                ts:Create(self.checkIcon, revertInfo, { ImageTransparency = 1 }):Play()
            end)
        end)
    end)
end

-- a copy that found no clipboard function still gets a press acknowledgement, just no checkmark
function CopyButton:_playMiss()
    local ts = variables.tweenService
    self._copyToken += 1
    local token = self._copyToken

    ts:Create(self.wellScale, popInfo, { Scale = 1.08 }):Play()
    task.delay(popInfo.Time, function()
        if self._copyToken ~= token then
            return
        end
        ts:Create(self.wellScale, squishInfo, { Scale = 0.88 }):Play()
        task.delay(squishInfo.Time, function()
            if self._copyToken ~= token then
                return
            end
            ts:Create(self.wellScale, settleInfo, { Scale = 1 }):Play()
        end)
    end)
end

function CopyButton:_performCopy()
    hapticEngine.click()
    soundEngine.click()
    local ok = clipboard.copy(self.text)

    if ok then
        self:_playSuccess()
    else
        self:_playMiss()
        -- once per button, not once per click - an impatient user mashing it shouldn't spam the console
        if not self._warnedNoClipboard then
            self._warnedNoClipboard = true
            log.warn(
                `Rayfield: no clipboard function exposed by this executor, the CopyButton '{self.name}' couldn't copy.`
            )
        end
    end

    self.window:_runGuarded(self, self.callback, ok)
end

-- full-width: title/description left, well pinned right, width-bounce (matches button.luau)
function CopyButton:_buildFull()
    local window = self.window

    self.main = window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, elementHeight),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = window:StyleElementBody(self.main)
    self.hoverOverlay = window:CreateHoverOverlay(self.main)

    -- the dev's icon in front of the title, where every other element carries its own
    local titleLeft = constants.elementInset
    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(constants.elementIconSize, constants.elementIconSize),
            Position = UDim2.new(0, 16, 0.5, 0),
            AnchorPoint = Vector2.new(0, 0.5),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            ImageTransparency = 1, -- In = 0
            Parent = self.main,
        }, { ImageColor3 = "ContentColor" })
        titleLeft = constants.elementInset + constants.elementIconSize + constants.elementIconGap
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(250, 16),
        Position = UDim2.new(0, titleLeft, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        AutomaticSize = Enum.AutomaticSize.X,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,

        TextTransparency = 1, -- In = 0

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.interact = window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        TextTransparency = 1,

        Parent = self.main,
    })

    self:_buildWell(self.main)
    self.well.Position = UDim2.new(1, -wellRight, 0, elementHeight / 2)
    self.well.AnchorPoint = Vector2.new(1, 0.5)
    self.window:_fitRowTitle(self, wellRight + wellSize + 10)

    self.window:_wireElementHover(self)

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()
        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -26, 0, elementHeight) }
            )
            :Play()

        self:_performCopy()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -20, 0, elementHeight) }
            )
            :Play()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- compact (row): title left, well right (SpaceBetween)
function CopyButton:_buildCompact()
    local window = self.window

    self.main, self.stroke, self.interact = window:_buildCompactRow(self.tab, self.name, 10)
    self.hoverOverlay = self.interact

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 15),
        PaddingRight = UDim.new(0, 15),

        Parent = self.interact,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.SpaceBetween,
        Padding = UDim.new(0, 10),

        Parent = self.interact,
    })

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 0,

        TextTransparency = 1, -- In = 0

        Parent = self.interact,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    self:_buildWell(self.interact)
    self.well.LayoutOrder = 1

    self.window:_wireElementHover(self)

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()

        self:_performCopy()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- iconLabel (the dev's icon, in front of the title) is handled by _revealCommon/_hideCommon
function CopyButton:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.well, { BackgroundTransparency = 0 }, animate)
        w:_reveal(self.copyGlyph, { ImageTransparency = 0 }, animate)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.well, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.copyGlyph, { ImageTransparency = 1 }, animate)
        w:_reveal(self.checkIcon, { ImageTransparency = 1 }, animate)
    end
end

-- The key is white on every theme, so a theme change has nothing to repaint on it.
function CopyButton:_refreshTheme() end

-- Update the string this button copies without rebuilding it.
function CopyButton:Set(text)
    self.text = tostring(text)
end

-- Room the compact copy button needs: side padding + title text + gap to the well + the well.
function CopyButton:_minWidth()
    local w = 30 + 10 + wellSize -- 15+15 padding, 10 gap to well, well itself
    w += functions.textWidth(self.window.theme.Font, 16, self.name)
    return w
end

moveable(CopyButton)
lockable(CopyButton)

return CopyButton
]=====]

sources["components/countdown"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A countdown: "next raid in 04:31", "boss respawns in 1:02:10", "daily reward ready".
--
-- Hubs build this by hand out of a Label and a loop, and each one gets a different piece of it
-- wrong: seconds counted with task.wait drift (a wait of 1 is never exactly 1), a loop left
-- running after the window unloads, a timer that says "0:00" forever instead of saying it is done.
-- Here the time left is always worked out from a fixed end moment, not by subtracting ticks, so it
-- cannot drift; the loop stops with the window; and a finished countdown says so.
--
--   local raid = tab:CreateCountdown({
--       name = "Next raid", icon = "lucide:swords", duration = 300, loop = true,
--       onFinished = function() joinRaid() end,
--   })
--   raid:Set(secondsLeftFromTheGame) -- line it up with the game's own clock whenever you learn it

local Countdown = {}
Countdown.__index = Countdown
Countdown.__type = "Countdown"

local utility = script.Parent.Parent.utility
local constants = require(utility.constants)
-- the height of a one-line card (see constants.elementHeight)
local elementHeight = constants.elementHeight
local variables = require(utility.variables)
local functions = require(utility.functions)
local locale = require(utility.locale)
local image = require(utility.image)
local odometer = require(utility.odometer)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)

local sidePadding = 15
local rowHeight = elementHeight
local trackHeight = 4
local trackBottom = 12
local tickInterval = 0.25 -- how often the loop looks at the clock; the display only moves on whole seconds

-- The last stretch reads warm, so a glance says "about to happen" before the digits do.
local warmColor = Color3.fromRGB(255, 176, 64)

local stateInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
-- the bar moves in the same one-second steps the digits do, eased linearly so it reads as time
local stepInfo = TweenInfo.new(1, Enum.EasingStyle.Linear)

-- 125 -> "02:05", 3725 -> "1:02:05"
local function clockText(seconds: number): string
    seconds = math.max(math.ceil(seconds), 0)
    local hours = math.floor(seconds / 3600)
    local minutes = math.floor((seconds % 3600) / 60)
    local secs = seconds % 60
    if hours > 0 then
        return string.format("%d:%02d:%02d", hours, minutes, secs)
    end
    return string.format("%02d:%02d", minutes, secs)
end

function Countdown.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local duration = math.max(tonumber(properties.duration or properties.Duration) or 60, 1)

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Countdown",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = true, -- a clock is not a setting to restore into another session

        -- The full length, which is what the bar measures against.
        duration = duration,
        -- Start again from the top when it reaches zero - a raid every five minutes.
        loop = functions.readBool(properties, "loop", false),
        -- What it says once it is done (and not looping).
        finishedText = properties.finishedText or properties.FinishedText or "Ready",
        -- Seconds left at which it turns warm.
        warnAt = math.max(tonumber(properties.warnAt or properties.WarnAt) or 10, 0),
        format = properties.format or properties.Format,
        onFinished = properties.onFinished or properties.OnFinished,

        -- the moment it reaches zero, on the clock below; nil while paused
        _endsAt = nil,
        -- seconds left, frozen, while paused
        _pausedLeft = nil,
        _shownSecond = nil,
        _finished = false,
        -- a method, so a spec can drive time instead of waiting for it
        _clock = os.clock,
    }, Countdown)

    local startAt = tonumber(properties.seconds or properties.Seconds) or duration

    self:_build()

    if functions.readBool(properties, "autoStart", true) then
        self:Start(startAt)
    else
        self._pausedLeft = math.max(startAt, 0)
        self:_render(false)
    end

    self.window:_wireTooltip(self)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

function Countdown:_build()
    local window = self.window

    self.main = window:Create("Frame", {
        Name = self.name,
        Size = UDim2.new(1, -20, 0, rowHeight + trackBottom),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = window:StyleElementBody(self.main)

    local titleLeft = sidePadding
    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Size = UDim2.fromOffset(constants.elementIconSize, constants.elementIconSize),
            Position = UDim2.new(0, sidePadding, 0, rowHeight / 2),
            AnchorPoint = Vector2.new(0, 0.5),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.main,
        }, { ImageColor3 = "ContentColor" })
        image.assign(self.iconLabel, "Image", self.icon)
        titleLeft += constants.elementIconSize + constants.elementIconGap
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.new(1, -(titleLeft + sidePadding + 110), 0, 18),
        Position = UDim2.new(0, titleLeft, 0, rowHeight / 2),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,

        TextTransparency = 1, -- In = 0

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- The time itself. The label is the value of record; the odometer is what the player sees
    -- change, one digit rolling down at a time.
    self.timeLabel = window:Create("TextLabel", {
        Text = "",
        Size = UDim2.fromOffset(110, 18),
        Position = UDim2.new(1, -sidePadding, 0, rowHeight / 2),
        AnchorPoint = Vector2.new(1, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Right,
        TextTransparency = 1,

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.timeHost = window:Create("Frame", {
        Name = "Time",
        Size = UDim2.fromOffset(0, 18),
        Position = UDim2.new(1, -sidePadding, 0, rowHeight / 2),
        AnchorPoint = Vector2.new(1, 0.5),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.main,
    })
    self.timeOdo = odometer.new(window, self.timeHost, {
        textSize = 16,
        alignment = Enum.HorizontalAlignment.Right,
        transparency = 1,
        duration = 0.35,
    })

    -- How much of the whole is left, as a bar that empties towards the left.
    self.track = window:Create("Frame", {
        Name = "Track",
        Size = UDim2.new(1, -(sidePadding * 2), 0, trackHeight),
        Position = UDim2.new(0, sidePadding, 1, -trackBottom),
        AnchorPoint = Vector2.new(0, 1),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = 0.9

        Parent = self.main,
    }, { BackgroundColor3 = "ContentColor" })
    window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = self.track })

    self.fill = window:Create("Frame", {
        Name = "Fill",
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = 0

        Parent = self.track,
    })
    window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = self.fill })
end

-- Seconds left right now.
function Countdown:Get(): number
    if self._endsAt then
        return math.max(self._endsAt - self._clock(), 0)
    end
    return self._pausedLeft or 0
end

function Countdown:IsRunning(): boolean
    return self._endsAt ~= nil
end

-- Run from `seconds` (default: the full duration). Also what a finished countdown restarts with.
function Countdown:Start(seconds)
    local left = math.max(tonumber(seconds) or self.duration, 0)
    self._pausedLeft = nil
    self._endsAt = self._clock() + left
    self._finished = false
    self:_render(false)
    self:_ensureLoop()
end

-- Line the countdown up with a time the game reports, without changing whether it is running.
function Countdown:Set(seconds)
    local left = math.max(tonumber(seconds) or 0, 0)
    self._finished = false
    if self._endsAt then
        self._endsAt = self._clock() + left
    else
        self._pausedLeft = left
    end
    self:_render(true)
end

-- Add (or, negative, take away) time.
function Countdown:Add(seconds)
    self:Set(self:Get() + (tonumber(seconds) or 0))
end

function Countdown:Pause()
    if not self._endsAt then
        return
    end
    self._pausedLeft = self:Get()
    self._endsAt = nil
    self:_render(false)
end

function Countdown:Resume()
    if self._endsAt or self._pausedLeft == nil then
        return
    end
    self:Start(self._pausedLeft)
end

-- Back to the full duration, running.
function Countdown:Reset()
    self:Start(self.duration)
end

function Countdown:SetDuration(seconds)
    self.duration = math.max(tonumber(seconds) or self.duration, 1)
    self:_render(false)
end

-- One loop per countdown, however many times Start is called; it ends on its own when the window
-- unloads or the element is removed.
function Countdown:_ensureLoop()
    if self._looping then
        return
    end
    self._looping = true
    task.spawn(function()
        while self._looping and not self.window.unloaded and not self._removed do
            if self._endsAt then
                self:_tick()
            end
            task.wait(tickInterval)
        end
        self._looping = false
    end)
end

-- Look at the clock: finish if it is time, otherwise move the display when the second changes.
function Countdown:_tick()
    if self._endsAt and self:Get() <= 0 and not self._finished then
        self:_finish()
        return
    end
    local second = math.ceil(self:Get())
    if second ~= self._shownSecond then
        self:_render(true)
    end
end

function Countdown:_finish()
    self._finished = true
    if self.loop then
        -- straight back to the top: the next one is already counting
        self._endsAt = self._clock() + self.duration
        self._finished = false
        self:_render(false)
    else
        self._endsAt = nil
        self._pausedLeft = 0
        self:_render(true)
    end
    if self.onFinished then
        self.window:_runGuarded(self, self.onFinished)
    end
end

function Countdown:_text(left: number): string
    if self._finished and not self.loop then
        return locale.resolve(self.finishedText)
    end
    if type(self.format) == "function" then
        local ok, text = pcall(self.format, left)
        if ok and text ~= nil then
            return tostring(text)
        end
    end
    return clockText(left)
end

-- Paint the time, the bar and the warm state for the seconds left now.
function Countdown:_render(animate: boolean)
    local left = self:Get()
    local second = math.ceil(left)
    self._shownSecond = second

    local text = self:_text(left)
    self.timeLabel.Text = text
    if self.timeOdo then
        -- counting down, so the digits roll downwards
        if animate then
            self.timeOdo:to(text, false)
        else
            self.timeOdo:snap(text)
        end
    end

    local fraction = math.clamp(second / self.duration, 0, 1)
    local warm = left > 0 and left <= self.warnAt and self.warnAt > 0
    local color = if warm then warmColor else self.window.theme.AccentColor

    local size = UDim2.fromScale(fraction, 1)
    if animate and self._endsAt then
        variables.tweenService:Create(self.fill, stepInfo, { Size = size }):Play()
    else
        self.fill.Size = size
    end

    if self._warm ~= warm or self._paintedColor ~= color then
        self._warm = warm
        self._paintedColor = color
        variables.tweenService:Create(self.fill, stateInfo, { BackgroundColor3 = color }):Play()
    end
end

moveable(Countdown)
lockable(Countdown)

function Countdown:_setShown(shown, animate)
    local w = self.window
    self._shown = shown
    if shown then
        w:_revealCommon(self, animate)
        self.timeOdo:reveal(0.05, animate)
        w:_reveal(self.track, { BackgroundTransparency = 0.9 }, animate)
        w:_reveal(self.fill, { BackgroundTransparency = 0 }, animate)
    else
        w:_hideCommon(self, animate)
        self.timeOdo:reveal(1, animate)
        w:_reveal(self.track, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.fill, { BackgroundTransparency = 1 }, animate)
    end
end

function Countdown:_refreshTheme()
    self._paintedColor = nil
    self:_render(false)
end

function Countdown:_minWidth(): number
    return 200
end

function Countdown:Remove()
    self._removed = true
    self._looping = false
    if self.descriptor then
        self.descriptor:Remove()
    end
    self.main:Destroy()
end

return Countdown
]=====]

sources["components/datatable"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A table: rows of values under named columns - an inventory, a shop, a leaderboard, a drop log.
--
--   local inventory = tab:CreateTable({
--       name = "Inventory",
--       columns = {
--           { key = "name", title = "Item" },
--           { key = "rarity", title = "Rarity", width = 0.25 },
--           { key = "amount", title = "Qty", width = 0.15, align = "right" },
--       },
--       rows = { { name = "Cursed Requiem", rarity = "Legendary", amount = 3 } },
--       onRowClick = function(row) print(row.name) end,
--   })
--
-- Clicking a column's title sorts by it; clicking it again flips the order. Numbers sort as
-- numbers ("10" after "9", not before it) and text sorts without caring about case.
--
-- Rows are positioned by hand rather than by a UIListLayout: this project's executor has fought
-- every attempt to animate or reorder children a layout also owns, and a sort is exactly a reorder.

local Table = {}
Table.__index = Table
Table.__type = "Table"

local utility = script.Parent.Parent.utility
local variables = require(utility.variables)
local functions = require(utility.functions)
local locale = require(utility.locale)
local image = require(utility.image)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)
local constants = require(utility.constants)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)

local sidePadding = 15
local headerTop = 14
local titleHeight = 18
local titleGap = 10
local columnsHeight = 26
local rowHeight = 30
local cellPadding = 10
local bottomPadding = 12
local emptyRoom = 62
local defaultMaxHeight = constants.listMaxHeight or 210

local stateInfo = TweenInfo.new(0.16, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

-- every other row carries a faint band so a long row can be followed across; the hovered one more
local zebraTransparency = 0.965
local hoverTransparency = 0.92

local function alignment(value)
    value = string.lower(tostring(value or "left"))
    if value == "right" then
        return Enum.TextXAlignment.Right
    elseif value == "center" or value == "centre" then
        return Enum.TextXAlignment.Center
    end
    return Enum.TextXAlignment.Left
end

-- Numbers as numbers, everything else as lower-case text; a missing value sorts last either way.
local function compare(a, b, descending: boolean): boolean
    if a == nil or b == nil then
        if a == nil and b == nil then
            return false
        end
        return b == nil
    end
    local na, nb = tonumber(a), tonumber(b)
    local less
    if na and nb then
        if na == nb then
            return false
        end
        less = na < nb
    else
        local sa, sb = string.lower(tostring(a)), string.lower(tostring(b))
        if sa == sb then
            return false
        end
        less = sa < sb
    end
    return if descending then not less else less
end

function Table.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name,
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = true, -- the rows are the hub's data, not a setting

        columns = {},
        rows = {}, -- in display order
        -- A ceiling, like ItemGrid's: fewer rows take only their height, more scroll inside it.
        maxHeight = math.max(tonumber(properties.maxHeight or properties.MaxHeight) or defaultMaxHeight, rowHeight),
        sortable = functions.readBool(properties, "sortable", true),
        emptyText = properties.emptyText or properties.EmptyText or "Nothing here yet.",
        emptyIcon = properties.emptyIcon or properties.EmptyIcon or "lucide:table",
        onRowClick = properties.onRowClick or properties.OnRowClick,

        sortKey = nil,
        sortDescending = false,
        rowFrames = {},
    }, Table)

    for _, column in (properties.columns or properties.Columns or {}) do
        if type(column) == "string" then
            column = { key = column }
        end
        if type(column) == "table" and column.key ~= nil then
            table.insert(self.columns, {
                key = column.key,
                title = column.title or column.Title or tostring(column.key),
                -- a share of the row (0-1); columns without one split what is left evenly
                width = tonumber(column.width or column.Width),
                align = alignment(column.align or column.Align),
                format = column.format or column.Format,
                -- How the column sorts, when alphabetical is the wrong answer. `sortOrder` ranks
                -- values by a list ({ "Common", "Rare", "Epic", ... }), so a rarity column sorts by
                -- tier rather than by spelling - reported live, "Rarity" sorting Epic before Rare read
                -- as broken. `sortValue` maps a value (and its row) to whatever should be compared.
                sortOrder = column.sortOrder or column.SortOrder,
                sortValue = column.sortValue or column.SortValue,
            })
        end
    end

    self:_build()
    self:SetRows(properties.rows or properties.Rows or {})

    local sortBy = properties.sortBy or properties.SortBy
    if sortBy ~= nil then
        self:SortBy(sortBy, functions.readBool(properties, "descending", false))
    end

    self.window:_wireTooltip(self)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- Where each column starts and how wide it is, as scales of the row.
function Table:_layoutColumns()
    local claimed, open = 0, 0
    for _, column in self.columns do
        if column.width then
            claimed += column.width
        else
            open += 1
        end
    end
    local share = if open > 0 then math.max(1 - claimed, 0) / open else 0
    local x = 0
    for _, column in self.columns do
        column.x = x
        column.scale = column.width or share
        x += column.scale
    end
end

function Table:_top(): number
    return if self.name then headerTop + titleHeight + titleGap else headerTop
end

function Table:_build()
    local window = self.window
    self:_layoutColumns()

    self.main = window:Create("Frame", {
        Name = self.name or "Table",
        Size = UDim2.new(1, -20, 0, 80),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = window:StyleElementBody(self.main)

    if self.name then
        local titleLeft = sidePadding
        if self.icon then
            self.iconLabel = window:Create("ImageLabel", {
                Size = UDim2.fromOffset(constants.elementIconSize, constants.elementIconSize),
                Position = UDim2.new(0, sidePadding, 0, headerTop + 1),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,

                ImageTransparency = 1, -- In = 0

                Parent = self.main,
            }, { ImageColor3 = "ContentColor" })
            image.assign(self.iconLabel, "Image", self.icon)
            titleLeft += constants.elementIconSize + constants.elementIconGap
        end

        self.title = window:Create("TextLabel", {
            Text = locale.t(self.name),
            Size = UDim2.new(1, -(titleLeft + sidePadding + 60), 0, titleHeight),
            Position = UDim2.new(0, titleLeft, 0, headerTop),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 16,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,

            TextTransparency = 1, -- In = 0

            Parent = self.main,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })

        -- "12 rows": the one number a table this size gets asked for
        self.counter = window:Create("TextLabel", {
            Text = "",
            Size = UDim2.fromOffset(60, titleHeight),
            Position = UDim2.new(1, -sidePadding, 0, headerTop),
            AnchorPoint = Vector2.new(1, 0),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 13,
            TextXAlignment = Enum.TextXAlignment.Right,

            TextTransparency = 1, -- In = 0.5

            Parent = self.main,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })
    end

    -- the column titles, which are also the sort controls
    self.headerRow = window:Create("Frame", {
        Name = "Columns",
        Size = UDim2.new(1, -(sidePadding * 2), 0, columnsHeight),
        Position = UDim2.new(0, sidePadding, 0, self:_top()),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.main,
    })

    self.headerRule = window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 1),
        Position = UDim2.new(0, 0, 1, -1),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = 0.88

        Parent = self.headerRow,
    }, { BackgroundColor3 = "ContentColor" })

    self.headers = {}
    for _, column in self.columns do
        local header = {}
        header.button = window:Create("TextButton", {
            Name = tostring(column.key),
            Text = locale.t(column.title),
            Size = UDim2.new(column.scale, -cellPadding, 1, 0),
            Position = UDim2.new(column.x, cellPadding / 2, 0, 0),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            TextSize = 12,
            TextXAlignment = column.align,
            TextTruncate = Enum.TextTruncate.AtEnd,

            TextTransparency = 1, -- In = 0.45

            Parent = self.headerRow,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })

        -- Which way it is sorted, right beside the heading's own words. Placed at the far edge of
        -- the column it floated away from the title it belongs to - on a wide column, next to the
        -- NEIGHBOURING heading instead.
        local titleWidth = functions.textWidth(window.theme.Font, 12, locale.resolve(column.title))
        header.arrow = window:Create("ImageLabel", {
            Image = "rbxassetid://" .. tostring(constants.icons.chevron),
            Size = UDim2.fromOffset(10, 10),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = if column.align == Enum.TextXAlignment.Right
                then UDim2.new(1, -(titleWidth + 9), 0.5, 0)
                elseif column.align == Enum.TextXAlignment.Center then UDim2.new(0.5, titleWidth / 2 + 9, 0.5, 0)
                else UDim2.new(0, titleWidth + 9, 0.5, 0),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Visible = false,

            ImageTransparency = 1, -- In = 0.3

            Parent = header.button,
        }, { ImageColor3 = "ContentColor" })

        window:ConnectFor(self, header.button.MouseButton1Click, function()
            if self.locked or not self.sortable then
                return
            end
            hapticEngine.click()
            soundEngine.click()
            local descending = if self.sortKey == column.key then not self.sortDescending else false
            self:SortBy(column.key, descending)
        end)

        self.headers[column.key] = header
    end

    self.body = window:Create("ScrollingFrame", {
        Name = "Rows",
        Size = UDim2.new(1, -(sidePadding * 2), 0, rowHeight),
        Position = UDim2.new(0, sidePadding, 0, self:_top() + columnsHeight),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        CanvasSize = UDim2.new(),
        ScrollBarThickness = 3,
        ScrollBarImageTransparency = 0.6,
        ScrollingDirection = Enum.ScrollingDirection.Y,

        Parent = self.main,
    }, { ScrollBarImageColor3 = "ContentColor" })

    self.empty = window:_buildEmptyState(self.main, {
        icon = self.emptyIcon,
        text = self.emptyText,
        size = UDim2.new(1, -(sidePadding * 2), 0, emptyRoom),
        position = UDim2.new(0, sidePadding, 0, self:_top() + columnsHeight),
    })
end

function Table:_rowFrame(index: number)
    local row = self.rowFrames[index]
    if row then
        return row
    end

    local window = self.window
    row = { cells = {} }

    row.frame = window:Create("TextButton", {
        Name = "Row",
        Text = "",
        AutoButtonColor = false,
        Size = UDim2.new(1, 0, 0, rowHeight),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = zebra / 1

        Parent = self.body,
    }, { BackgroundColor3 = "ContentColor" })
    window:Create("UICorner", { CornerRadius = UDim.new(0, 6), Parent = row.frame })

    for _, column in self.columns do
        row.cells[column.key] = window:Create("TextLabel", {
            Text = "",
            Size = UDim2.new(column.scale, -cellPadding, 1, 0),
            Position = UDim2.new(column.x, cellPadding / 2, 0, 0),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 13,
            TextXAlignment = column.align,
            TextTruncate = Enum.TextTruncate.AtEnd,

            TextTransparency = 1, -- In = 0.1

            Parent = row.frame,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })
    end

    window:ConnectFor(self, row.frame.MouseEnter, function()
        row.hovered = true
        self:_paintRow(row, true)
    end)
    window:ConnectFor(self, row.frame.MouseLeave, function()
        row.hovered = false
        self:_paintRow(row, true)
    end)
    window:ConnectFor(self, row.frame.MouseButton1Click, function()
        if self.locked or not self.onRowClick or not row.data then
            return
        end
        hapticEngine.click()
        soundEngine.click()
        self.window:_runGuarded(self, self.onRowClick, row.data, row.index)
    end)

    self.rowFrames[index] = row
    return row
end

function Table:_cellText(column, data): string
    local value = data[column.key]
    if type(column.format) == "function" then
        local ok, text = pcall(column.format, value, data)
        if ok and text ~= nil then
            return tostring(text)
        end
    end
    if value == nil then
        return "-"
    end
    return tostring(value)
end

function Table:_paintRow(row, animate: boolean)
    if not self._shown then
        return
    end
    local zebra = row.index and row.index % 2 == 0
    local goal = {
        BackgroundTransparency = if row.hovered and self.onRowClick
            then hoverTransparency
            elseif zebra then zebraTransparency
            else 1,
    }
    if animate then
        variables.tweenService:Create(row.frame, stateInfo, goal):Play()
    else
        row.frame.BackgroundTransparency = goal.BackgroundTransparency
    end
end

-- Draw every row in its current order, reusing the frames already made.
function Table:_redraw()
    for index, data in self.rows do
        local row = self:_rowFrame(index)
        row.index = index
        row.data = data
        row.frame.Visible = true
        row.frame.Position = UDim2.fromOffset(0, (index - 1) * rowHeight)
        for _, column in self.columns do
            row.cells[column.key].Text = self:_cellText(column, data)
        end
        self:_paintRow(row, false)
    end
    for index = #self.rows + 1, #self.rowFrames do
        local row = self.rowFrames[index]
        row.frame.Visible = false
        row.data = nil
    end

    local count = #self.rows
    self.body.CanvasSize = UDim2.fromOffset(0, count * rowHeight)
    local bodyHeight = if count == 0 then emptyRoom else math.min(count * rowHeight, self.maxHeight)
    self.body.Size = UDim2.new(1, -(sidePadding * 2), 0, bodyHeight)
    self.body.Visible = count > 0
    self.empty.frame.Visible = count == 0
    self.main.Size = UDim2.new(1, -20, 0, self:_top() + columnsHeight + bodyHeight + bottomPadding)

    if self.counter then
        self.counter.Text = if count == 1 then "1 row" else `{count} rows`
    end

    for key, header in self.headers do
        header.arrow.Visible = self.sortKey == key
        header.arrow.Rotation = if self.sortDescending then 180 else 0
    end
end

moveable(Table)
lockable(Table)

-- Replace every row.
function Table:SetRows(rows)
    self.rows = {}
    for _, row in (if type(rows) == "table" then rows else {}) do
        if type(row) == "table" then
            self:_stamp(row)
            table.insert(self.rows, row)
        end
    end
    self:_applySort()
    self:_redraw()
end

-- Add one row, in its sorted place when sorted.
function Table:AddRow(row)
    if type(row) ~= "table" then
        return false
    end
    self:_stamp(row)
    table.insert(self.rows, row)
    self:_applySort()
    self:_redraw()
    return true
end

-- Remove rows the predicate accepts, or the row at a position. Returns how many went.
function Table:RemoveRow(which)
    local removed = 0
    if type(which) == "function" then
        for index = #self.rows, 1, -1 do
            if which(self.rows[index]) then
                table.remove(self.rows, index)
                removed += 1
            end
        end
    elseif type(which) == "number" and self.rows[which] then
        table.remove(self.rows, which)
        removed = 1
    end
    if removed > 0 then
        self:_redraw()
    end
    return removed
end

function Table:Clear()
    self.rows = {}
    self:_redraw()
end

-- The rows, in the order they are shown.
function Table:Get(): { any }
    return table.clone(self.rows)
end

function Table:SortBy(key, descending)
    local known = false
    for _, column in self.columns do
        if column.key == key then
            known = true
        end
    end
    if not known then
        return false
    end
    self.sortKey = key
    self.sortDescending = descending == true
    self:_applySort()
    self:_redraw()
    return true
end

-- Remember the order rows arrived in, so rows that compare equal keep it.
function Table:_stamp(row)
    self._arrivals = self._arrivals or setmetatable({}, { __mode = "k" })
    if self._arrivals[row] == nil then
        self._nextArrival = (self._nextArrival or 0) + 1
        self._arrivals[row] = self._nextArrival
    end
end

function Table:_applySort()
    if self.sortKey == nil then
        return
    end
    local key, descending = self.sortKey, self.sortDescending
    local column
    for _, candidate in self.columns do
        if candidate.key == key then
            column = candidate
        end
    end

    -- the value a row is compared by in this column
    local rank = {}
    if column and type(column.sortOrder) == "table" then
        for index, value in column.sortOrder do
            rank[value] = index
        end
    end
    local function sortValue(row)
        local value = row[key]
        if column and type(column.sortValue) == "function" then
            local ok, mapped = pcall(column.sortValue, value, row)
            if ok then
                return mapped
            end
        end
        if column and column.sortOrder then
            -- a value the list does not name sorts after every one it does, in both directions:
            -- nil is what compare already puts last whichever way the column is sorted
            return rank[value]
        end
        return value
    end

    local arrivals = self._arrivals or {}
    table.sort(self.rows, function(a, b)
        local va, vb = sortValue(a), sortValue(b)
        if compare(va, vb, descending) then
            return true
        end
        if compare(vb, va, descending) then
            return false
        end
        -- Equal in this column: keep the order they arrived in. table.sort is not stable, so two
        -- "Legendary" rows used to swap places on every click, which read as the sort misbehaving.
        return (arrivals[a] or 0) < (arrivals[b] or 0)
    end)
end

function Table:SetMaxHeight(height)
    self.maxHeight = math.max(tonumber(height) or defaultMaxHeight, rowHeight)
    self:_redraw()
end

function Table:_setShown(shown, animate)
    local w = self.window
    self._shown = shown
    if shown then
        w:_reveal(self.main, { BackgroundTransparency = w.theme.ElementTransparency or 0 }, animate)
        w:_reveal(self.stroke, { Transparency = w.theme.ElementStrokeTransparency }, animate)
        if self.title then
            w:_reveal(self.title, { TextTransparency = 0 }, animate)
            w:_reveal(self.counter, { TextTransparency = 0.5 }, animate)
        end
        if self.iconLabel then
            w:_reveal(self.iconLabel, { ImageTransparency = 0 }, animate)
        end
        w:_reveal(self.headerRule, { BackgroundTransparency = 0.88 }, animate)
        for _, header in self.headers do
            w:_reveal(header.button, { TextTransparency = 0.45 }, animate)
            w:_reveal(header.arrow, { ImageTransparency = 0.3 }, animate)
        end
        for _, row in self.rowFrames do
            for _, cell in row.cells do
                w:_reveal(cell, { TextTransparency = 0.1 }, animate)
            end
            self:_paintRow(row, animate)
        end
        w:_reveal(self.empty.label, { TextTransparency = 0.55 }, animate)
        w:_reveal(self.empty.icon, { ImageTransparency = 0.65 }, animate)
    else
        w:_reveal(self.main, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.stroke, { Transparency = 1 }, animate)
        if self.title then
            w:_reveal(self.title, { TextTransparency = 1 }, animate)
            w:_reveal(self.counter, { TextTransparency = 1 }, animate)
        end
        if self.iconLabel then
            w:_reveal(self.iconLabel, { ImageTransparency = 1 }, animate)
        end
        w:_reveal(self.headerRule, { BackgroundTransparency = 1 }, animate)
        for _, header in self.headers do
            w:_reveal(header.button, { TextTransparency = 1 }, animate)
            w:_reveal(header.arrow, { ImageTransparency = 1 }, animate)
        end
        for _, row in self.rowFrames do
            for _, cell in row.cells do
                w:_reveal(cell, { TextTransparency = 1 }, animate)
            end
            w:_reveal(row.frame, { BackgroundTransparency = 1 }, animate)
        end
        w:_reveal(self.empty.label, { TextTransparency = 1 }, animate)
        w:_reveal(self.empty.icon, { ImageTransparency = 1 }, animate)
    end
end

function Table:_refreshTheme() end

function Table:_minWidth(): number
    return 220
end

function Table:Remove()
    if self.descriptor then
        self.descriptor:Remove()
    end
    self.main:Destroy()
end

return Table
]=====]

