        ColorSequenceKeypoint.new(1, Color3.fromRGB(24, 35, 48)),
    }),
    ShadowColor = Color3.fromRGB(6, 10, 16),

    ElementStroke = Color3.fromRGB(38, 52, 68),
    ElementGradient = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(20, 29, 40)),
        ColorSequenceKeypoint.new(0.9999, Color3.fromRGB(24, 34, 46)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(24, 34, 46)),
    }),
    ElementStrokeGradient = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(50, 68, 88)),
        ColorSequenceKeypoint.new(0.9999, Color3.fromRGB(62, 84, 108)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(50, 68, 88)),
    }),
    ElementStrokeHover = Color3.fromRGB(58, 80, 104),

    TabBackground = ColorSequence.new(Color3.fromRGB(38, 54, 72), Color3.fromRGB(24, 35, 48)),
    TabStroke = ColorSequence.new(Color3.fromRGB(62, 88, 116), Color3.fromRGB(38, 54, 72)),

    SliderBackground = Color3.fromRGB(32, 45, 60),
    SliderBackgroundHover = Color3.fromRGB(42, 58, 76),
    SliderProgress = ColorSequence.new(Color3.fromRGB(64, 180, 232), Color3.fromRGB(32, 138, 196)),

    -- Sky-blue accent for the active toggle, slider glow and popup primary button.
    AccentColor = Color3.fromRGB(56, 176, 232),
    AccentStroke = Color3.fromRGB(120, 212, 250),

    ToggleKnobOff = Color3.fromRGB(210, 224, 236), -- cool off-knob on the dark track

    StatBackground = Color3.fromRGB(16, 24, 34),

    DropdownHighlight = Color3.fromRGB(56, 176, 232),

    NeutralButton = Color3.fromRGB(32, 45, 60),
    NeutralButtonHover = Color3.fromRGB(42, 58, 76),
    NeutralButtonStroke = Color3.fromRGB(96, 132, 168),
}
]=====]

sources["themes/rose"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Dark theme with a rose accent. Partial: overrides the warm-plum tones + pink accent, inherits
-- corners, fonts and toggle/field behaviour from default.
return {
    WindowColor = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(26, 18, 22)),
        ColorSequenceKeypoint.new(0.9999, Color3.fromRGB(36, 26, 31)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(44, 32, 38)),
    }),
    ShadowColor = Color3.fromRGB(18, 10, 14),

    ElementStroke = Color3.fromRGB(58, 44, 50),
    ElementGradient = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(34, 25, 29)),
        ColorSequenceKeypoint.new(0.9999, Color3.fromRGB(40, 30, 34)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 30, 34)),
    }),
    ElementStrokeGradient = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(76, 58, 66)),
        ColorSequenceKeypoint.new(0.9999, Color3.fromRGB(92, 70, 80)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(76, 58, 66)),
    }),
    ElementStrokeHover = Color3.fromRGB(88, 66, 74),

    TabBackground = ColorSequence.new(Color3.fromRGB(62, 46, 53), Color3.fromRGB(38, 29, 33)),
    TabStroke = ColorSequence.new(Color3.fromRGB(102, 78, 88), Color3.fromRGB(62, 46, 53)),

    SliderBackground = Color3.fromRGB(50, 38, 44),
    SliderBackgroundHover = Color3.fromRGB(64, 50, 56),
    SliderProgress = ColorSequence.new(Color3.fromRGB(244, 88, 140), Color3.fromRGB(220, 60, 116)),

    -- Rose accent for the active toggle, slider glow and popup primary button.
    AccentColor = Color3.fromRGB(240, 82, 138),
    AccentStroke = Color3.fromRGB(255, 134, 178),

    ToggleKnobOff = Color3.fromRGB(236, 220, 226), -- warm off-knob on the dark track

    StatBackground = Color3.fromRGB(28, 20, 24),

    DropdownHighlight = Color3.fromRGB(240, 82, 138),

    NeutralButton = Color3.fromRGB(50, 38, 44),
    NeutralButtonHover = Color3.fromRGB(64, 50, 56),
    NeutralButtonStroke = Color3.fromRGB(170, 122, 140),
}
]=====]

sources["types"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Public API types. camelCase is the documented surface; PascalCase keys still work.

export type Theme = string | { [string]: any }

-- Optional dev hook: given a source string (the English copy, which doubles as its key) and the
-- active locale id, return the translation, or nil/"" to fall through to the built-in tables.
export type Translator = (source: string, localeId: string) -> string?

-- Translation tables keyed by locale id, each mapping a source string to its translation, e.g.
-- { fr = { ["Close"] = "Fermer" }, ["pt-br"] = { ["Close"] = "Fechar" } }.
export type Translations = { [string]: { [string]: string } }

export type WindowConfiguration = {
    autoSave: boolean?,
    autoLoad: boolean?,
    fileName: string?,
    customFolder: string?,
    -- flags excluded from every save/load, config export/import included - Fluent's own
    -- SaveManager:SetIgnoreIndexes(), for things like a menu keybind or a one-off server action
    -- that shouldn't round-trip through a saved config at all. Per-element forgetState already
    -- covers the single-element case; this is the same idea as a standing list instead.
    ignoreFlags: { string }?,
    -- nests configs one folder deeper, named after game.PlaceId (or a Studio-safe stand-in) -
    -- so a multi-place experience, or a hub script reused across several games, never mixes one
    -- place's saved configs into another's. Opt-in: flipping this on for a window that already
    -- has saved configs at the old, unscoped path won't find them there anymore.
    scopeByPlace: boolean?,
}

-- Dev-configured splash (icon/title/optional cycling tip) played once, on the window's very
-- first Show(), before its own staged content reveal. Omit `loading` entirely on WindowProps to
-- skip the feature outright - passing it (even {}) turns it on and adds the player's Settings
-- toggle ("Loading Animation") to switch it back off per-session.
export type LoadingProps = {
    enabled: boolean?, -- dev's own default for the Settings toggle (default true)
    icon: (string | number)?, -- defaults to the window's own `icon`
    title: string?, -- defaults to the window's own `name`
    tips: { string }?, -- cycles like PlayGreeting's texts; omit/empty = no tip line at all
    tipHoldTime: number?, -- seconds each tip holds before crossfading to the next (default 0.9)
    duration: number?, -- minimum total time the splash stays up (default 1.1)
}

-- One step of a guided tour: target is whatever CreateToggle/CreateButton/etc itself returned
-- (anything with a .main), title/description are the bubble's copy for that step. Steps can
-- freely mix targets from different tabs - the tour auto-Selects whichever tab actually owns
-- the next step's target (see tour.luau's own findOwningTab), no per-step tab field needed.
export type TourStep = {
    target: any,
    title: string?,
    description: string?,
}

export type WindowProps = {
    name: string?,
    -- what the Search action looks through: "tab" (default) filters the page the player is on,
    -- following them to another tab with the query; "all" gathers every page into one list
    searchScope: string?,
    subtitle: string?,
    theme: Theme?,
    icon: (string | number)?,
    showName: string?,
    showIcon: (string | number)?,
    loading: LoadingProps?,
    -- guided onboarding tour, played once automatically on first show; omit entirely to skip
    -- the feature (no Settings "Replay Tour" button either) - see tour.luau
    tour: { TourStep }?,
    configuration: WindowConfiguration?,
    fallbackFont: (Font | Enum.Font)?, -- built-in stand-in shown in secure mode while the brand font downloads
    locale: string?, -- pin the UI language; defaults to the player's Roblox locale
    translations: Translations?, -- language tables keyed by locale id; the easy, table-first path
    translator: Translator?, -- resolve copy yourself; falls back to the built-in tables
    -- Live machine translation for every dev string (see autoTranslate.luau) - no table, no
    -- translator function, nothing to maintain: turn it on and every name/description a script
    -- writes gets translated automatically the first time a player sees it in another language,
    -- then cached forever after. translator/translations above still win when both are set -
    -- this only fills in what neither of those already answers.
    autoTranslate: boolean?,
    -- Squircle corners (see utility/squircle.luau) on the window body only, instead of a plain
    -- UICorner circular arc - a smoother, more "premium" curve, at the cost of a couple of known
    -- gaps: an explicit borderColor/rainbowBorder still outlines a plain rounded rect (not the
    -- squircle curve), and the minimize-to-pill collapse animation keeps the squircle's normal
    -- radius throughout rather than rounding into a true pill.
    squircleCorners: boolean?,
    -- The Settings tab's own "Session" card (player name/players online/uptime/FPS, live-updated)
    -- - default true. Set false when a hub's own Dashboard tab already shows the same numbers, so
    -- a player doesn't see the same session info twice.
    sessionDashboard: boolean?,
    -- Settings > General toggles a hub can hide when it wants the behaviour pinned instead of
    -- player-adjustable - hiding one doesn't change self.settings' own default, only whether a
    -- player can flip it from Settings. All default true (unchanged from every toggle always
    -- showing, today's behaviour).
    showWelcomeToastToggle: boolean?,
    showHapticsToggle: boolean?,
    showSoundEffectsToggle: boolean?,
    showLoadingAnimationToggle: boolean?,
    -- initial window size (Vector2, a UDim2's offset component, or a {width,height}/{X,Y} table)
    -- - still screen-fit the same way the built-in default is, see windowSizing.luau
    size: (Vector2 | UDim2 | { [string]: number } | { number })?,

    -- Direct per-window visual overrides, layered on top of whatever the theme already draws -
    -- for a dev who wants one specific window's look tweaked without writing a whole custom
    -- theme table. Omit any of these and that piece stays exactly as the theme already renders
    -- it. gradient gates whether gradientColorSequence/gradientRotation apply at all, the same
    -- two-step shape Fluent's own Gradient/GradientColorSequence/GradientRotation properties use.
    gradient: boolean?,
    gradientColorSequence: ColorSequence?,
    gradientRotation: number?,
    borderColor: Color3?,
    borderThickness: number?,
    shadowColor: Color3?,
    shadowThickness: number?,
    shadowTransparency: number?,
    cornerRadius: number?, -- pixels

    -- Cycles the window's own border stroke through the hue wheel continuously. Forces the
    -- border visible the same way borderColor does (no need to also set one) - implies a border,
    -- doesn't just recolour an already-explicit one. Scoped to the window's own border only, not
    -- Fluent's full per-surface RainbowBorderTargets table (popups/groupboxes/cards) - the
    -- window itself is the only target actually turned on across every real CreateWindow call
    -- this was modelled from.
    rainbowBorder: boolean?,
    rainbowBorderSpeed: number?, -- full hue cycles per second (default 0.14, matching Fluent's own)

    -- Which bottom corner Window:Notify's stack grows from (default "Right", matching every
    -- prior version of this). Toast's own Top/Bottom is a separate, per-call `position` already.
    notifySide: ("Left" | "Right")?,

    -- Multiplies the resize grip's touch target on a touch-primary device (Window:IsMobile()) -
    -- default 1.4. See Window:IsMobile's own comment; also usable from a dev's own script.
    mobileHitScale: number?,

    -- The brief Rayfield-branded logo splash shown before the window appears - default false.
    -- Set true to bring it back.
    showBanner: boolean?,

    -- Adds a "Danger Zone" section to Settings with a hold-to-confirm "Destroy UI" button that
    -- calls Window:Unload(). Default false - destructive, so it's opt-in unlike the toggle-hide
    -- properties above.
    showUnloadButton: boolean?,
}

export type TabProps = {
    name: string?,
    icon: (string | number)?,
    locked: boolean?,
}

export type TagProps = {
    text: string?,
    title: string?,
    icon: (string | number)?,
    color: Color3?,
    order: number?,
}

export type SectionProps = {
    name: string?,
    icon: (string | number)?,
}

export type LabelProps = {
    text: string?,
    icon: (string | number)?,
}

export type ParagraphProps = {
    title: string?,
    content: string?,
    icon: (string | number)?,
}

export type DividerProps = {
    text: string?,
    line: boolean?, -- default true; false = spacing-only, no visible rule
    spacing: string?, -- "tight" | "normal" (default) | "loose" - vertical padding around the line
    height: number?, -- gap height in px when line = false (default 24)
}

export type TabboxProps = {
    name: string?,
}

export type TabboxPage = Group -- a Tabbox page is a column Group; every CreateX works on it

export type Tabbox = Moveable & {
    -- returns the page, which hosts elements exactly like a Group does
    CreateTab: (self: Tabbox, props: { name: string? }) -> TabboxPage,
}

export type PanelProps = {
    name: string?, -- the card's instance name; the header shows the CURRENT page, not this
    onPageChanged: ((page: string) -> ())?, -- a page change the player (or SelectPage) made
    flag: string?, -- config key for the open page; derived from the name when omitted
    forgetState: boolean?, -- don't persist which page is open
}

export type PanelPage = Group -- a Panel page is a column Group; every CreateX works on it

export type Panel = Moveable & {
    -- the first page created is the one the panel opens on
    CreatePage: (self: Panel, props: { name: string?, icon: (string | number)? }) -> PanelPage,
    -- by index, by name, or by the page object; false for a page this panel does not have
    SelectPage: (self: Panel, page: number | string | PanelPage, skipCallback: boolean?) -> boolean,
    -- like SelectPage, but a page this panel does not have YET is remembered and opened when built
    Set: (self: Panel, page: number | string | PanelPage, skipCallback: boolean?) -> boolean,
    GetPage: (self: Panel) -> string?,
}

export type GroupProps = {
    direction: string?, -- "row" | "column" (default row); "horizontal"/"vertical" also work
    -- Only meaningful for a column nested in a row, where the default is an equal split:
    -- `width` pins this column and lets the rest of the row absorb what is left, `weight`
    -- splits proportionally instead.
    width: number?,
    weight: number?,
    -- Dependency group: hides/shows every child together based on another control's value -
    -- Fluent's own DependencyGroupbox. dependsOn is whatever CreateToggle/CreateDropdown/etc
    -- itself returned; condition defaults to a plain truthy check (built for a toggle) - pass
    -- one explicitly for a dropdown/slider-driven group, e.g. function(v) return v == "Advanced"
    -- end.
    dependsOn: any?,
    condition: ((value: any) -> boolean)?,
}

-- tooltip is shared by every card element (see Window:_wireTooltip): hold the mouse a moment
-- and it fades in above the cursor, wrapping for longer text.
export type ButtonProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    locked: boolean?,
    -- a cheap destructive-action confirm: the first click just arms the button (its title flips
    -- to confirmText for a few seconds), the callback only fires on the confirming second click
    doubleClick: boolean?,
    confirmText: string?, -- default "Click again to confirm"
    callback: (() -> ())?,
}

export type ToggleProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    value: boolean?,
    locked: boolean?,
    forgetState: boolean?,
    callback: ((value: boolean) -> ())?,
}

-- A compact alternative to Toggle: same flag/config/description contract, a check box instead
-- of a pill switch.
export type CheckboxProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    value: boolean?,
    forgetState: boolean?,
    callback: ((value: boolean) -> ())?,
}

export type CopyButtonProps = {
    name: string?,
    description: string?,
    icon: (string | number)?, -- before the title, like any row; the key on the right holds the copy glyph
    tooltip: string?,
    text: string?, -- the string copied to the clipboard
    callback: ((success: boolean) -> ())?, -- fires after every press with whether the copy landed
}

export type FlipButtonProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    secondaryName: string?, -- the back face; hovering flips the title to this and back
    -- "slide" (default): the back face drops in over a card turned the text colour;
    -- "squish" (also "v1"/"classic"): the title squishes shut and springs back with the other label
    style: string?,
    callback: (() -> ())?,
}

-- A Button whose press feedback is a ripple from the exact point pressed (mouse or touch),
-- clipped to the card's rounded corners, instead of Button's stroke-ghost + width-bounce.
export type RippleButtonProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    callback: (() -> ())?,
}

export type ProgressBarProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    value: number?,
    max: number?, -- default 100
    suffix: string?, -- set this to switch the readout to "{value} {suffix} out of {max}"
}

export type ScrollHintProps = {
    text: string?,
}

-- A colour is a Color3, a hex string ("#ffcc00"), a name that follows the theme (accent, text,
-- muted, title) or a fixed one (success, warning, error, info, red, green, yellow, orange, blue,
-- cyan, purple, pink, gray, white, black).
export type ConsoleStyle = {
    color: (Color3 | string)?,
    bold: boolean?,
    italic: boolean?,
    underline: boolean?,
    strike: boolean?,
    highlight: (Color3 | string)?, -- a marker pen behind the text
    size: number?,
    transparency: number?,
}

export type ConsoleSegment = string | number | {
    text: (string | number)?,
    Text: (string | number)?,
    color: (Color3 | string)?,
    bold: boolean?,
    italic: boolean?,
    underline: boolean?,
    strike: boolean?,
    highlight: (Color3 | string)?,
    size: number?,
    transparency: number?,
}

-- one part, or a list of them: Append({ "Bought ", { "Egg", color = "#ffcc00" } })
export type ConsoleContent = ConsoleSegment | { ConsoleSegment }

export type ConsoleProps = {
    name: string?,
    description: string?,
    text: string?,
    height: number?, -- default 120
    follow: boolean?, -- pin to the newest line as output arrives, like a real log
    maxLines: number?, -- default 200; oldest lines roll off past this
    -- true for HH:MM:SS, or an os.date format string, in front of every line
    timestamps: (boolean | string)?,
    -- pass a plain string append straight through as Roblox RichText instead of escaping it.
    -- Off by default: output with a "<" in it must not be able to turn into a tag.
    richText: boolean?,
}

export type SegmentedPickerOption = string | {
    text: string?,
    Text: string?,
    -- nested sub-options, expanded inline within this segment's own slot once it's selected
    options: { string | { text: string?, Text: string? } }?,
    Options: { string | { text: string?, Text: string? } }?,
}

export type SegmentedPickerProps = {
    options: { SegmentedPickerOption }?,
    value: string?, -- a leaf's text - a top-level option's own, or a nested child's
    description: string?,
    flag: string?,
    forgetState: boolean?,
    callback: ((value: string) -> ())?,
}

export type ShimmerLabelProps = {
    text: string?,
    speed: number?, -- seconds per sweep (default 1.4)
    spread: number?, -- 0..1, width of the bright band (default 0.2)
    angle: number?, -- gradient rotation in degrees (default 20)
    textSize: number?,
}

export type SliderProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    range: { number }?, -- { min, max }
    increment: number?,
    value: number?,
    suffix: string?,
    minimal: boolean?, -- track only, no name/value (for dense rows)
    forgetState: boolean?,
    callback: ((value: number) -> ())?,
}

export type DropdownSection = {
    name: string?,
    options: { string }?,
}

export type DropdownProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    options: { string }?,
    -- section headers (e.g. "MELEE"/"RANGED") - when given, takes over from `options` above,
    -- which is instead derived by flattening every section's own option list in order
    sections: { DropdownSection }?,
    value: (string | { string })?,
    multiSelect: boolean?,
    placeholder: string?,
    locked: boolean?,
    forgetState: boolean?,
    callback: ((value: any) -> ())?,
}

-- CreatePlayerDropdown takes everything a Dropdown does except `options`/`sections`, which it
-- fills from the server itself.
export type PlayerDropdownProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    value: (string | { string })?,
    multiSelect: boolean?,
    placeholder: string?,
    locked: boolean?,
    forgetState: boolean?,
    -- how each player is labelled: "name" (default, and what code should key on), "display",
    -- or "both" ("DisplayName (@Name)")
    format: ("name" | "display" | "both")?,
    includeSelf: boolean?, -- default true
    callback: ((value: any) -> ())?,
}

export type GridItem = {
    id: string?, -- defaults to `name` when omitted
    name: string?,
    icon: (string | number)?, -- small glyph beside the name
    image: (string | number)?, -- a real thumbnail; takes over from `icon` when both are given
    color: Color3?, -- the card's edge while unselected: a rarity/category tint
    tag: string?, -- what the chips and Filter({ tags = ... }) narrow on
}

-- One filter chip. A bare string is its own tag and label.
export type GridFilterChip = string | {
    tag: string?,
    name: string?, -- the chip's label; defaults to the tag
    color: Color3?,
}

export type ListOption = string | {
    id: string?, -- defaults to `name`
    name: string?,
    icon: (string | number)?,
    color: Color3?, -- overrides the accent for this row's fill when selected
}

export type ListPickerProps = {
    name: string?, -- also the header label, rendered uppercase
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?, -- persists the selected id, or the array of ticked ids when multiSelect
    options: { ListOption }?,
    multiSelect: boolean?, -- default false; true ticks any number of rows
    value: (string | { string })?, -- single-select defaults to the first option, multi to none
    rowHeight: number?, -- default 34, floor 24
    maxHeight: number?, -- the CEILING: shorter lists take only their rows, longer ones scroll; default 210, same as ItemGrid
    height: number?, -- original spelling of maxHeight, still accepted
    showHeader: boolean?, -- default true
    emptyText: string?,
    callback: ((value: any) -> ())?, -- the id, or the array of ticked ids when multiSelect
}

export type ItemGridProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?, -- persists the selected ids
    items: { string | GridItem }?,
    value: (string | { string })?,
    columns: number?, -- ceiling, default 4; a narrow window drops below it on its own
    maxHeight: number?, -- the CEILING on the card area: fewer cards take only their rows, more scroll; default 210
    fixedColumns: boolean?, -- default false: columns is a ceiling a narrow window drops below; true holds it exactly
    loading: boolean?, -- placeholder cards until items arrive; defaults on for a grid built empty, and times out
    emptyIcon: (string | number)?, -- the glyph over the empty text; default "lucide:search-x"
    height: number?, -- original spelling of maxHeight, still accepted
    cellHeight: number?, -- default 46
    multiSelect: boolean?, -- default true
    emptyText: string?,
    -- built into the element: `true` for the default placeholder, or pass the placeholder itself
    search: (boolean | string)?,
    filters: { GridFilterChip }?, -- the chip row; the dev owns the tag set
    imageLayout: ("left" | "top")?, -- thumbnail beside the name, or above it. Default "left"
    onFilterChanged: ((filter: { text: string, tags: { string } }) -> ())?,
    callback: ((selected: { string }) -> ())?,
}

export type GridFilter = string | ((item: GridItem) -> boolean) | {
    text: string?,
    tags: ({ string } | { [string]: boolean })?,
}

export type ReorderItem = {
    id: string?, -- defaults to `name` when omitted
    name: string?,
    icon: (string | number)?,
    color: Color3?, -- tints the index badge, for a per-item category/rarity
}

export type ReorderListProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?, -- persists the ORDER (an array of ids)
    items: { string | ReorderItem }?,
    rowHeight: number?, -- default 38, floor 26
    showIndex: boolean?, -- the 1/2/3 badge, default true
    removable: boolean?, -- per-row remove button, default false
    emptyText: string?,
    onRemove: ((id: string) -> ())?,
    callback: ((order: { string }) -> ())?,
}

export type InputProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    value: string?,
    placeholder: string?,
    numeric: boolean?,
    clearOnFocus: boolean?,
    forgetState: boolean?,
    callback: ((value: string) -> ())?,
}

export type KeybindProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    value: (EnumItem | string)?, -- an Enum.KeyCode / mouse button, or a KeyCode name
    forgetState: boolean?,
    isMenuToggle: boolean?, -- internal: the settings menu-toggle keybind, clash check runs in reverse
    hold: boolean?, -- fire callback(true) once held, callback(false) on release
    holdThreshold: number?, -- seconds to hold before it counts (default 0.2)
    callback: ((value: EnumItem | boolean) -> ())?, -- bound key on press, or true/false in hold mode
    onChanged: ((key: EnumItem) -> ())?, -- fires when the binding is changed
}

export type ColorPickerProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    color: Color3?, -- initial colour (accepts a hex string too)
    alpha: number?, -- initial alpha 0..1 (default 1, no dedicated control in this layout - set via code)
    presets: { Color3 }?, -- quick-pick swatches under the RGB row
    glow: boolean?, -- ambient glow behind the card (default true)
    forgetState: boolean?,
    callback: ((value: Color3, alpha: number) -> ())?,
}

export type GradientStop = {
    time: number,
    color: Color3,
}

export type GradientPickerProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    gradient: (ColorSequence | { Color3 } | { GradientStop })?, -- initial value
    glow: boolean?, -- ambient glow behind the card (default true)
    forgetState: boolean?,
    callback: ((value: ColorSequence) -> ())?,
}

export type HoldButtonProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    holdDuration: number?, -- seconds the fill takes to complete (default 1)
    danger: boolean?, -- tint the fill red instead of the accent colour
    locked: boolean?,
    callback: (() -> ())?,
}

export type ChangelogEntry = {
    tag: string?, -- "ADDED" | "FIXED" | "CHANGED" | "REMOVED", or any custom tag
    text: string?,
}

export type ChangelogProps = {
    name: string?, -- card title (default "Update Log")
    version: string?,
    date: string?,
    entries: { ChangelogEntry }?,
}

export type CollapsibleProps = {
    name: string?,
    icon: (string | number)?,
    expanded: boolean?, -- start open (default false)
    flag: string?, -- config key for open/closed; derived from the name when omitted
    forgetState: boolean?, -- don't persist open/closed
}

export type SpacerProps = {
    height: number?, -- pixel gap (default 12)
}

export type StatProps = {
    sparkline: boolean?, -- the trace of recent values behind the number (default true on a full card)
    sparklinePoints: number?, -- how many values that trace keeps (2-120, default 24)
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    prefix: string?,
    suffix: string?,
    value: number?,
    display: string?, -- "value" | "change"
    compact: boolean?,
    changeMode: string?, -- "percentage" | "absolute"
    changeBaseline: string?, -- "previous" | "initial"
    numberEasing: boolean?,
}

-- One line of a StatusCard: label (dim, translated like any other dev-authored copy) · value
-- (live data - never auto-translated, since it changes at runtime). key defaults to `label` if
-- omitted; give it explicitly when the label itself might repeat or change.
export type StatusCardRow = {
    key: string?,
    label: string,
    value: string,
    muted: boolean?, -- renders the value in a plain, unremarkable colour instead of the theme accent
}

export type StatusCardProps = {
    name: string?, -- header title, default "Status"
    icon: (string | number)?,
    width: number?, -- card width in pixels, default 260 - fixed-width by design, not full tab width
    collapsible: boolean?, -- shows the header chevron, default true
    expanded: boolean?, -- default true
    glow: boolean?, -- ambient glow behind the card, default true
    rows: { StatusCardRow }?,
}

export type NotifyProps = {
    title: string?,
    content: string?,
    icon: (string | number)?,
    duration: number?,
    accentColor: Color3?,
    -- skip the auto-dismiss dwell entirely; the caller owns this notification's lifetime and
    -- must call :Destroy() on the returned handle themselves. Pair with :SetProgress/
    -- :ChangeTitle/:ChangeDescription for a long job's in-place progress card.
    persist: boolean?,
}

export type ToastAction = {
    text: string,
    callback: () -> (),
}

export type ToastProps = {
    title: string?,
    subtitle: string?, -- optional second line
    subtitleAbove: boolean?, -- render the subtitle above the title (label-over-value)
    icon: (string | number)?, -- optional; asset id or ready image string (rbxthumb works)
    avatar: number?, -- optional user id; shows that user's headshot as a larger avatar
    minWidth: number?, -- floor the pill width; slack becomes right-hand room (content is left-aligned)
    duration: number?,
    position: "Top" | "Bottom"?,
    -- optional trailing pill button (e.g. "Undo") - runs callback (guarded), then dismisses
    action: ToastAction?,
}

export type PopupBox = {
    title: string?,
    description: string?,
    icon: (string | number)?,
}

export type PopupOption = {
    text: string?,
    style: string?, -- "neutral" (default) | "primary" | "danger"
    -- receives the popup's current input value (see PopupProps.input) - "" when there's no
    -- input field. Return false to reject and keep the popup open (flashes the field red)
    -- instead of closing - the mechanism Window:KeySystem itself is built on.
    callback: ((value: string) -> boolean?)?,
}

export type PopupInputProps = {
    placeholder: string?,
    value: string?,
}

export type PopupProps = {
    title: string?,
    subtitle: string?,
    icon: (string | number)?,
    content: string?, -- a body paragraph
    boxes: { PopupBox }?, -- a list of cards (the changelog layout)
    -- a full-width text field between the content and the buttons, turning a plain confirm
    -- dialog into a "type something and submit" prompt. A plain string is shorthand for
    -- { placeholder = string }.
    input: (string | PopupInputProps)?,
    options: { PopupOption }?, -- footer buttons; defaults to a single dismiss button
    dismissable: boolean?, -- click the dim or press Escape to close (default true)
}

export type KeySystemProps = {
    title: string?,
    subtitle: string?,
    icon: (string | number)?,
    note: string?, -- body text above the field (a hint, a link to get a key, etc)
    placeholder: string?,
    submitText: string?,
    exitText: string?,
    -- exactly one of these decides what counts as a valid key: validator wins if given, else
    -- key/keys. validator is pcall'd - a throw counts as rejected, not a crash.
    validator: ((key: string) -> boolean)?,
    key: string?,
    keys: { string }?,
    -- persist an *accepted* key to disk so a returning player skips the gate - re-checked
    -- against validator/key every launch, not trusted blindly, so a revoked/rotated key can't
    -- let someone in forever just because it worked once.
    saveKey: boolean?,
    onSuccess: (() -> ())?,
    onFailure: (() -> ())?,
}

-- Handles ------------------------------------------------------------------
-- Every element can be reordered within its tab.
export type Moveable = {
    MoveTo: (self: any, index: number) -> (),
    MoveToTop: (self: any) -> (),
    MoveToBottom: (self: any) -> (),
    MoveUp: (self: any) -> (),
    MoveDown: (self: any) -> (),
    -- Devlog 7: shows/hides the element at runtime, independent of tab switching or the window
    -- itself hiding - pulls it out of layout entirely rather than just fading it.
    SetVisible: (self: any, visible: boolean) -> (),
}

export type Button = Moveable & {
    locked: boolean,
    SetLocked: (self: Button, locked: boolean) -> (),
    -- Shared Lock/Unlock/IsLocked naming, aliased into SetLocked - see lockable.luau.
    Lock: (self: Button) -> (),
    Unlock: (self: Button) -> (),
    IsLocked: (self: Button) -> boolean,
}

export type RippleButton = Moveable & {}

export type ProgressBar = Moveable & {
    value: number,
    Set: (self: ProgressBar, value: number, skipAnimation: boolean?) -> (),
}

-- (ListPicker and ReorderList also take `loading: boolean?` - placeholder rows until items arrive,
-- on by default for a list built empty and timing out - and have :SetLoading(loading).)

export type StepperProps = {
    name: string?,
    icon: (string | number)?,
    description: string?,
    tooltip: string?,
    flag: string?,
    forgetState: boolean?,
    value: number?, -- default: min, or 0
    min: number?,
    max: number?,
    step: number?, -- default 1; every value is snapped to it, counted from min
    decimals: number?, -- default: however many the step has
    prefix: string?,
    suffix: string?,
    typing: boolean?, -- click the number to type one (default true)
    callback: ((value: number) -> ())?,
}

export type Stepper = Moveable & {
    Get: (self: Stepper) -> number,
    Set: (self: Stepper, value: number, skipCallback: boolean?) -> boolean,
    Nudge: (self: Stepper, direction: number) -> boolean,
    SetRange: (self: Stepper, min: number?, max: number?) -> (),
    Remove: (self: Stepper) -> (),
}

export type TableColumn = {
    key: string, -- which field of a row this column shows
    title: string?, -- the column heading (default: the key)
    width: number?, -- a share of the row, 0-1; columns without one split what is left evenly
    align: string?, -- "left" (default), "center" or "right"
    format: ((value: any, row: { [string]: any }) -> string)?, -- how a cell reads
    sortOrder: { any }?, -- rank values by this list instead of alphabetically (a rarity tier list)
    sortValue: ((value: any, row: { [string]: any }) -> any)?, -- what the column compares instead
}

export type TableProps = {
    name: string?,
    icon: (string | number)?,
    description: string?,
    tooltip: string?,
    columns: { TableColumn | string },
    rows: { { [string]: any } }?,
    sortable: boolean?, -- click a heading to sort by it (default true)
    sortBy: string?, -- sort by this column from the start
    descending: boolean?, -- with sortBy
    maxHeight: number?, -- the ceiling; more rows scroll inside it (default 210)
    emptyText: string?,
    emptyIcon: (string | number)?,
    onRowClick: ((row: { [string]: any }, index: number) -> ())?,
}

export type Table = Moveable & {
    Get: (self: Table) -> { { [string]: any } },
    SetRows: (self: Table, rows: { { [string]: any } }) -> (),
    AddRow: (self: Table, row: { [string]: any }) -> boolean,
    RemoveRow: (self: Table, which: number | ((row: { [string]: any }) -> boolean)) -> number,
    Clear: (self: Table) -> (),
    SortBy: (self: Table, key: string, descending: boolean?) -> boolean,
    SetMaxHeight: (self: Table, height: number) -> (),
    Remove: (self: Table) -> (),
}

export type FAQItem = {
    question: string,
    answer: string?,
}

export type FAQProps = {
    name: string?, -- what the search matches besides the questions themselves (default "FAQ")
    items: { FAQItem }?,
    exclusive: boolean?, -- opening one question closes the others (default true)
}

export type FAQ = Moveable & {
    Open: (self: FAQ, index: number) -> (),
    Close: (self: FAQ, index: number) -> (),
    Toggle: (self: FAQ, index: number) -> (),
    CloseAll: (self: FAQ) -> (),
    IsOpen: (self: FAQ, index: number) -> boolean,
    SetItems: (self: FAQ, items: { FAQItem }) -> (),
    Get: (self: FAQ) -> { FAQItem },
    Remove: (self: FAQ) -> (),
}

export type CountdownProps = {
    name: string?,
    icon: (string | number)?,
    description: string?,
    tooltip: string?,
    duration: number?, -- the full length in seconds, which the bar measures against (default 60)
    seconds: number?, -- seconds left to start from (default: the full duration)
    autoStart: boolean?, -- start counting straight away (default true)
    loop: boolean?, -- start again from the top on reaching zero (default false)
    finishedText: string?, -- what a finished countdown says (default "Ready")
    warnAt: number?, -- seconds left at which it turns warm (default 10; 0 never)
    format: ((secondsLeft: number) -> string)?, -- how the time reads, instead of mm:ss / h:mm:ss
    onFinished: (() -> ())?, -- runs every time it reaches zero
}

export type Countdown = Moveable & {
    Get: (self: Countdown) -> number,
    Set: (self: Countdown, secondsLeft: number) -> (),
    Add: (self: Countdown, seconds: number) -> (),
    Start: (self: Countdown, seconds: number?) -> (),
    Pause: (self: Countdown) -> (),
    Resume: (self: Countdown) -> (),
    Reset: (self: Countdown) -> (),
    SetDuration: (self: Countdown, seconds: number) -> (),
    IsRunning: (self: Countdown) -> boolean,
    Remove: (self: Countdown) -> (),
}

export type ChartPoint = number | { value: number, label: string? }

export type ChartProps = {
    name: string?,
    icon: (string | number)?,
    description: string?,
    tooltip: string?,
    mode: string?, -- "line" (default) or "bar"
    values: { ChartPoint }?, -- the series to start with, oldest first; a bar can carry a label
    labels: { string }?, -- names under the bars, by index
    maxPoints: number?, -- how many points are kept; the oldest falls off the left (2-240, default 48)
    height: number?, -- the plot height in px (default 94, floor 40)
    min: number?, -- pin the bottom of the scale; omit to follow the data (bars stand on zero)
    max: number?, -- pin the top of the scale; omit to follow the data
    format: ((value: number) -> string)?, -- how the header current value reads
    prefix: string?, -- before the number, e.g. "$" (when there is no format)
    suffix: string?, -- after the number, e.g. " ccu"
    decimals: number?, -- digits after the point (default 0; thousands get separators)
    smooth: boolean?, -- a curve through the points instead of straight lines (default false)
    dots: boolean?, -- a white dot on every point (default true, false when smooth)
    scale: boolean?, -- the top and bottom of the scale written on the plot (default false)
    color: Color3?, -- the line/bar colour; defaults to the theme accent
    baseline: boolean?, -- the hairline under the plot (default true)
    showValue: boolean?, -- the newest value in the header (default true)
}

export type StackedChartRow = { name: string, values: { number } }

export type StackedChartProps = {
    name: string?,
    icon: (string | number)?,
    description: string?,
    tooltip: string?,
    series: { string }?, -- the parts every row is split into, in order
    rows: { StackedChartRow }?,
    colors: { Color3 }?, -- one per series; defaults to shades of the theme accent
    prefix: string?,
    suffix: string?,
}

export type StackedChart = Moveable & {
    Set: (self: StackedChart, rows: { StackedChartRow }) -> (),
    Get: (self: StackedChart) -> { StackedChartRow },
    Replay: (self: StackedChart) -> (), -- grow the bars in again
    Remove: (self: StackedChart) -> (),
}

export type Chart = Moveable & {
    Get: (self: Chart) -> { number },
    Push: (self: Chart, value: number, label: string?) -> boolean,
    Set: (self: Chart, values: { ChartPoint }) -> (),
    Clear: (self: Chart) -> (),
    SetRange: (self: Chart, min: number?, max: number?) -> (),
    SetHeight: (self: Chart, height: number) -> (),
    SetMode: (self: Chart, mode: string) -> boolean,
    Remove: (self: Chart) -> (),
}

export type Console = Moveable & {
    Get: (self: Console) -> string, -- the plain text, never the markup behind it
    Set: (self: Console, content: ConsoleContent, style: ConsoleStyle?) -> (),
    Append: (self: Console, content: ConsoleContent, style: ConsoleStyle?) -> (),
    -- one line with a coloured INFO/OK/WARN/ERROR tag in front
    Log: (self: Console, level: string, content: ConsoleContent, style: ConsoleStyle?) -> (),
    Info: (self: Console, content: ConsoleContent, style: ConsoleStyle?) -> (),
    Success: (self: Console, content: ConsoleContent, style: ConsoleStyle?) -> (),
    Warn: (self: Console, content: ConsoleContent, style: ConsoleStyle?) -> (),
    Error: (self: Console, content: ConsoleContent, style: ConsoleStyle?) -> (),
    -- rewrite the newest line in place, for a counter rather than a transcript
    UpdateLast: (self: Console, content: ConsoleContent, style: ConsoleStyle?) -> (),
    Clear: (self: Console) -> (),
    Copy: (self: Console) -> boolean,
    SetHeight: (self: Console, height: number) -> (),
}

export type ScrollHint = Moveable & {
    Set: (self: ScrollHint, text: string) -> (),
}

export type SegmentedPicker = Moveable & {
    value: string,
    Set: (self: SegmentedPicker, value: string, skipCallback: boolean?) -> (),
}

export type ShimmerLabel = Moveable & {
    text: string,
    Set: (self: ShimmerLabel, text: string) -> (),
    SetSpeed: (self: ShimmerLabel, seconds: number) -> (),
    SetSpread: (self: ShimmerLabel, fraction: number) -> (),
    SetAngle: (self: ShimmerLabel, degrees: number) -> (),
    SetTextSize: (self: ShimmerLabel, size: number) -> (),
}

export type CopyButton = Moveable & {
    text: string,
    Set: (self: CopyButton, text: string) -> (),
}

export type FlipButton = Moveable & {
    Set: (self: FlipButton, front: string?, back: string?) -> (),
}

export type Toggle = Moveable & {
    value: boolean,
    locked: boolean,
    Set: (self: Toggle, value: boolean, skipCallback: boolean?) -> (),
    SetLocked: (self: Toggle, locked: boolean) -> (),
    -- Element Locking (ported from upstream Rayfield Gen2 1.2): shared Lock/Unlock/IsLocked
    -- naming, aliased into this component's own SetLocked - see lockable.luau's own comment.
    Lock: (self: Toggle) -> (),
    Unlock: (self: Toggle) -> (),
    IsLocked: (self: Toggle) -> boolean,
    SetStatus: (self: Toggle, text: string) -> (),
    -- Runs fn(toggle) on a repeating timer for as long as this toggle is on; fn can return a
    -- number to override the wait before the next call instead of `interval` (default 0.5s).
    -- Managed and error-isolated per tick - see toggle.luau's own comment on why this beats a
    -- hand-rolled while loop in the toggle's own callback.
    Loop: (self: Toggle, fn: (toggle: any) -> number?, interval: number?) -> (),
}

export type Checkbox = Moveable & {
    value: boolean,
    Set: (self: Checkbox, value: boolean, skipCallback: boolean?) -> (),
}

export type Slider = Moveable & {
    value: number,
    locked: boolean,
    Set: (self: Slider, value: number, skipCallback: boolean?) -> (),
    -- Element Locking (ported from upstream Rayfield Gen2 1.2): dims the element and covers it
    -- with an input-blocking scrim. `reason` replaces its description while locked.
    Lock: (self: Slider, reason: string?) -> (),
    Unlock: (self: Slider) -> (),
    IsLocked: (self: Slider) -> boolean,
}

export type Dropdown = Moveable & {
    value: { string }, -- always stored pruned to the current options, even single-select
    locked: boolean,
    Set: (self: Dropdown, value: string | { string }, skipCallback: boolean?) -> (),
    Reset: (self: Dropdown, skipCallback: boolean?) -> (), -- clears back to the placeholder
    SetLocked: (self: Dropdown, locked: boolean) -> (),
    Refresh: (self: Dropdown, options: { string }?) -> (), -- swap the option list, keeping the pick
    -- Shared Lock/Unlock/IsLocked naming, aliased into SetLocked - see lockable.luau.
    Lock: (self: Dropdown) -> (),
    Unlock: (self: Dropdown) -> (),
    IsLocked: (self: Dropdown) -> boolean,
}

export type ListPicker = Moveable & {
    value: any, -- the selected id, or the ticked ids in option order when multiSelect
    multiSelect: boolean,
    locked: boolean,
    Get: (self: ListPicker) -> any,
    Set: (self: ListPicker, value: (string | { string })?, skipCallback: boolean?) -> boolean,
    Toggle: (self: ListPicker, id: string, skipCallback: boolean?) -> boolean,
    SelectAll: (self: ListPicker, skipCallback: boolean?) -> (), -- multi-select only
    Clear: (self: ListPicker, skipCallback: boolean?) -> (),
    Refresh: (self: ListPicker, options: { ListOption }, skipCallback: boolean?) -> (),
    SetHeight: (self: ListPicker, height: number?) -> (),
    SetMaxHeight: (self: ListPicker, height: number?) -> (),
    Lock: (self: ListPicker, reason: string?) -> (),
    Unlock: (self: ListPicker) -> (),
    IsLocked: (self: ListPicker) -> boolean,
}

export type ItemGrid = Moveable & {
    value: { string }, -- the selected ids, in item order
    locked: boolean,
    Get: (self: ItemGrid) -> { string },
    Set: (self: ItemGrid, ids: string | { string }, skipCallback: boolean?) -> (),
    Toggle: (self: ItemGrid, id: string, skipCallback: boolean?) -> boolean,
    Select: (self: ItemGrid, id: string, skipCallback: boolean?) -> (),
    Deselect: (self: ItemGrid, id: string, skipCallback: boolean?) -> (),
    SelectAll: (self: ItemGrid, skipCallback: boolean?) -> (), -- only what the filter shows
    Clear: (self: ItemGrid, skipCallback: boolean?) -> (),
    Filter: (self: ItemGrid, query: GridFilter?) -> (), -- nil clears it, chips included
    ToggleTag: (self: ItemGrid, tag: string) -> (), -- the programmatic half of clicking a chip
    GetFilter: (self: ItemGrid) -> { text: string, tags: { string } },
    Refresh: (self: ItemGrid, items: { string | GridItem }, skipCallback: boolean?) -> (),
    SetHeight: (self: ItemGrid, height: number?) -> (),
    SetMaxHeight: (self: ItemGrid, height: number?) -> (),
    SetColumns: (self: ItemGrid, columns: number, fixed: boolean?) -> (),
    ScrollChips: (self: ItemGrid, delta: number) -> number,
    SetLoading: (self: ItemGrid, loading: boolean) -> (),
    Lock: (self: ItemGrid, reason: string?) -> (),
    Unlock: (self: ItemGrid) -> (),
    IsLocked: (self: ItemGrid) -> boolean,
}

export type ReorderList = Moveable & {
    value: { string }, -- the current order, as ids
    locked: boolean,
    Get: (self: ReorderList) -> { string },
    Set: (self: ReorderList, order: { string }, skipCallback: boolean?) -> (),
    Add: (self: ReorderList, item: string | ReorderItem, skipCallback: boolean?) -> boolean,
    -- RemoveItem, not Remove: Remove() destroys the element, as on every other component
    RemoveItem: (self: ReorderList, id: string, skipCallback: boolean?) -> boolean,
    Refresh: (self: ReorderList, items: { string | ReorderItem }, skipCallback: boolean?) -> (),
    Lock: (self: ReorderList, reason: string?) -> (),
    Unlock: (self: ReorderList) -> (),
    IsLocked: (self: ReorderList) -> boolean,
}

-- A Dropdown built by CreatePlayerDropdown: the same handle with the player wiring on top.
