sources["utility/capabilities"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- What this executor can actually do, in one place.
--
-- Every optional thing the library reaches for - files, HTTP, the clipboard, custom assets, a
-- hidden GUI container, haptics - is probed for and worked around where it's missing, so the
-- interface itself comes up on anything from the best executor to the thinnest. This module is how
-- a hub (or a player filing a bug) can see which of those are missing on the machine in front of
-- them, instead of guessing from a feature that silently does nothing.
--
-- Nothing here changes behaviour: it reports. The probe runs once and is cached, since none of
-- these appear or disappear mid-session.

local filesystem = require(script.Parent.filesystem)
local network = require(script.Parent.network)
local clipboard = require(script.Parent.clipboard)
local runtime = require(script.Parent.runtime)
local hapticEngine = require(script.Parent.HapticEngine)

local capabilities = {}

export type Report = {
    executor: string,
    files: boolean,
    missingFiles: { string },
    http: boolean,
    nativeRequest: boolean,
    clipboard: boolean,
    customAssets: boolean,
    guiContainer: string,
    haptics: boolean,
    secureMode: boolean,
    touch: boolean,
    warnings: { string },
    summary: string,
}

local cached: Report? = nil

local function env(): any
    local ok, fenv = pcall(getfenv)
    return if ok and type(fenv) == "table" then fenv else {}
end

local function has(name: string): boolean
    local ok, value = pcall(function()
        return env()[name]
    end)
    return ok and typeof(value) == "function"
end

-- The executor's own name, where it gives one. Three spellings are in circulation and none of them
-- is guaranteed, so an unknown name is a perfectly normal answer, not a failure.
local function executorName(): string
    for _, name in { "identifyexecutor", "getexecutorname" } do
        local ok, fn = pcall(function()
            return env()[name]
        end)
        if ok and typeof(fn) == "function" then
            local called, result = pcall(fn)
            if called and type(result) == "string" and result ~= "" then
                return result
            end
        end
    end
    return "unknown"
end

function capabilities.probe(force: boolean?): Report
    if cached and not force then
        return cached
    end

    local userInputService = runtime.userInputService
    local report: Report = {
        executor = executorName(),
        files = filesystem.available == true,
        missingFiles = table.clone(filesystem.missing or {}),
        http = network.getFetchFn() ~= nil,
        nativeRequest = network.getRequestFn() ~= nil,
        clipboard = clipboard.getCopyFn() ~= nil,
        customAssets = has("getcustomasset"),
        guiContainer = runtime.guiContainerSource,
        haptics = hapticEngine.isSupported(),
        secureMode = runtime.secureMode == true,
        touch = userInputService.TouchEnabled and not userInputService.MouseEnabled,
        warnings = {},
        summary = "",
    }

    -- Each warning names what a player will notice, not which global is absent: "configs won't
    -- save" is something a hub can put in a toast, "no writefile" is not.
    local warnings = report.warnings
    if not report.files then
        table.insert(warnings, "No file access: configs and Settings choices can't be saved.")
    elseif #report.missingFiles > 0 then
        table.insert(
            warnings,
            `Partial file access (missing: {table.concat(report.missingFiles, ", ")}): some saving may fail.`
        )
    end
    if not report.http then
        table.insert(warnings, "No HTTP: downloaded fonts, cached icons and translations are unavailable.")
    end
    if not report.clipboard then
        table.insert(warnings, "No clipboard: Copy buttons and Console:Copy() do nothing.")
    end
    if report.secureMode and not report.customAssets then
        table.insert(warnings, "Secure mode is on but this executor has no getcustomasset: icons won't appear.")
    end

    local lines = {
        `Rayfield compatibility - executor: {report.executor}`,
        `  files: {if report.files then "yes" else "no"}`
            .. (if #report.missingFiles > 0 then ` (missing: {table.concat(report.missingFiles, ", ")})` else ""),
        `  http: {if report.http then (if report.nativeRequest then "request" else "HttpGet only") else "no"}`,
        `  clipboard: {if report.clipboard then "yes" else "no"}`,
        `  custom assets: {if report.customAssets then "yes" else "no"}`,
        `  gui container: {report.guiContainer}`,
        `  haptics: {if report.haptics then "yes" else "no"}`,
        `  secure mode: {if report.secureMode then "on" else "off"}`,
        `  input: {if report.touch then "touch" else "mouse/keyboard"}`,
    }
    for _, warning in warnings do
        table.insert(lines, "  ! " .. warning)
    end
    report.summary = table.concat(lines, "\n")

    cached = report
    return report
end

return capabilities
]=====]

sources["utility/clipboard"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Clipboard access, abstracted the same way network.luau abstracts `request`: every executor
-- names its clipboard writer differently (or ships none at all), so probe the environment for
-- one and no-op cleanly when nothing's there instead of throwing at the caller.

local clipboard = {}
clipboard.__index = clipboard

export type CopyFn = (text: string) -> ()

-- accepts the environment table from getfenv()
function clipboard.getCopyFn(env: any?): CopyFn?
    env = env or getfenv()
    return env.setclipboard or env.toclipboard or env.set_clipboard or (env.Clipboard and env.Clipboard.set)
end

-- Best-effort copy. Returns true only when a clipboard function was found and it didn't error.
function clipboard.copy(text: string): boolean
    local fn = clipboard.getCopyFn()
    if not fn then
        return false
    end
    local ok = pcall(fn, text)
    return ok
end

return clipboard
]=====]

sources["utility/colors"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local colors = {}

-- black or white, whichever reads better on the bg
function colors.contrastColor(color: Color3): Color3
    local luminance = 0.299 * color.R + 0.587 * color.G + 0.114 * color.B
    return if luminance > 0.5 then Color3.fromRGB(0, 0, 0) else Color3.fromRGB(255, 255, 255)
end

-- Coerce a Color3 to a ColorSequence (pass a ColorSequence through). UIGradient.Color
-- only accepts a sequence, so theme transforms feed colours through this.
function colors.toColorSequence(color: Color3 | ColorSequence): ColorSequence
    return if typeof(color) == "ColorSequence" then color else ColorSequence.new(color)
end

-- Pick near-black or white text for whatever colour it sits on, by perceived luminance.
-- Used for text on a solid fill whose colour comes from the theme (e.g. popup buttons).
function colors.contrastText(color: Color3): Color3
    local luminance = 0.299 * color.R + 0.587 * color.G + 0.114 * color.B
    return if luminance > 0.6 then Color3.fromRGB(20, 20, 20) else Color3.fromRGB(255, 255, 255)
end

-- The reverse of toColorSequence: a single representative Color3 for something that might be a
-- full gradient (e.g. picking contrast text for a label sitting on a gradient-filled pill) -
-- the midpoint blend of the sequence's first and last keypoints.
function colors.flatten(color: Color3 | ColorSequence): Color3
    if typeof(color) ~= "ColorSequence" then
        return color
    end
    local keypoints = color.Keypoints
    return keypoints[1].Value:Lerp(keypoints[#keypoints].Value, 0.5)
end

return colors
]=====]

sources["utility/constants"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Shared visual constants. Theme-varying colours/fonts live in themes/; these dont.

local constants = {}

-- brand font asset (themes reference this too)
-- The brand face: Builder Sans, the family SyncOfficialSpec's Rayfield Gen 3 Concept is set in.
-- It ships with the Roblox client, so it renders at once in every mode - no download, and in
-- secure mode no asset id to give the library away.
constants.fontAsset = "rbxasset://fonts/families/BuilderSans.json"

-- the input/keybind fields hug their text, tweening width instead of AutomaticSize so it animates
constants.pillResizeInfo = TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)

-- The height of a one-line card - a toggle, a button, a dropdown's header, an input. 50px, the
-- card of SyncOfficialSpec's Rayfield Gen 3 Concept: the old 41/43 read cramped beside it, and 50 is
-- also the more comfortable target for a thumb. Every one-line element derives its height, and
-- the vertical centre of whatever sits on its right, from this one number.
constants.elementHeight = 50
-- The icon in front of an element's name. 18px, the Concept's: the 16px one read a size small on a
-- 50px card. Only an element's own title icon - a section header's, or an icon inside a grid or a
-- list row, keeps its own size.
constants.elementIconSize = 18
-- where a row's icon (or, without one, its title) starts, and the gap between the icon and the
-- title after it: the Gen 3 Concept's 16 and 10, which sit the icon clear of the card's edge and
-- give the title room to breathe instead of butting up against its glyph
constants.elementInset = 16
constants.elementIconGap = 10

-- Every built-in icon Rayfield ships, by name. Single source of truth: secure mode caches
-- exactly these (see utility/image) so the UI never has to fall back to a raw asset id at
-- runtime. Add a new built-in icon here and it's cached automatically.
--
-- The header's own buttons and the search field use lucide glyphs (x, minus, maximize-2,
-- settings, text-search), the family SyncOfficialSpec's Rayfield Gen 3 Concept draws its header
-- with. Baked in as asset ids rather than "lucide:" strings: those resolve through a pack
-- download, and the window's own close button must never wait on one.
constants.icons = {
    close = 110786993356448, -- lucide x
    minimise = 118026365011536, -- lucide minus
    maximise = 73085922906397, -- lucide maximize-2
    settings = 80758916183665, -- lucide settings
    search = 92345384671606, -- lucide text-search
    plus = 111774323017047, -- lucide plus (the FAQ's open mark)
    tick = 93898873302694, -- lucide check: the checkbox's mark and the copy button's done state
    copy = 78979572434545, -- lucide copy: the copy button's well
    chevron = 88479147175134,
    check = 125626312718314,
    dot = 91452555903853, -- unselected dropdown option (also the colorpicker "invisible" mark)
    colorpicker = 91452555903853, -- same hollow-box glyph as dot
    banner = 111263549366178,
    config = 125823673784681, -- saved-configurations picker
    rayfield = 80387863064905, -- default show icon on the sign-in toast
}

-- The default height ceiling for a scrolling list inside an element - ItemGrid's card area and
-- ListPicker's rows both stop growing here and scroll past it. One value so two pickers placed
-- side by side share a ceiling on the part that scrolls. The cards around them can still end at
-- different heights, since ItemGrid stacks a search box and quick actions above its area.
constants.listMaxHeight = 210

-- Accent used by the toggle switch + slider glow when active.
constants.accent = {
    on = Color3.fromRGB(23, 153, 110),
    onStroke = Color3.fromRGB(32, 201, 144),
}

-- Stat card accents per direction (fill drives the card + glow, stroke is the brighter edge).
constants.statAccents = {
    positive = {
        fill = ColorSequence.new(Color3.fromRGB(0, 170, 127), Color3.fromRGB(0, 134, 98)),
        stroke = ColorSequence.new(Color3.fromRGB(0, 213, 156), Color3.fromRGB(0, 189, 135)),
    },
    negative = {
        fill = ColorSequence.new(Color3.fromRGB(172, 47, 47), Color3.fromRGB(135, 37, 37)),
        stroke = ColorSequence.new(Color3.fromRGB(255, 75, 75), Color3.fromRGB(244, 67, 67)),
    },
    -- Neutral matches RF2's default green stat exactly
    neutral = {
        fill = ColorSequence.new(Color3.fromRGB(0, 170, 127), Color3.fromRGB(0, 134, 98)),
        stroke = ColorSequence.new(Color3.fromRGB(0, 213, 156), Color3.fromRGB(0, 189, 135)),
    },
}

-- Named stacking layers for window furniture (assumes Global ZIndexBehavior)
constants.zIndex = {
    bottomFade = 100,
    drag = 1000,
    -- the corner resize grip lives in the same bottom-right corner bottomFade's own gradient
    -- sweeps across - live-caught the fade painting straight over the grip's arc, tinting it
    -- with a grey diagonal wash, since bottomFade (100) outranked the grip's old ZIndex (20)
    resizeGrip = 1100,
    -- the loading splash (icon/title/tip, first-show only): above ordinary window content, same
    -- reasoning as greeting below - plays before any of it has faded in yet, but a defensive
    -- tier beats relying on paint order matching build order
    loading = 1150,
    -- the greeting intro overlay: above ordinary window content (topbar, tabs, elements all sit
    -- near the default 1) but below notification/toast/restore/tooltip, which should still be
    -- able to show over it in the rare case one fires while a greeting is playing
    greeting = 1200,
    -- bottom-right notification cards, above the bottom fade + drag so they aren't dimmed or
    -- pierced by them (they land over the window's lower-right corner)
    notification = 1500,
    -- top-centre and bottom-centre toasts float over the whole window
    toast = 2000,
    toastContent = 2001,
    restoreContent = 100001,
    restoreInteract = 100002,
    tooltip = 100003,
    -- guided tour: the dim overlay + highlight ring sit just above tooltip (a tour step
    -- shouldn't be hideable behind a stray hover tooltip), the description bubble one above
    -- that so it's never itself dimmed by the overlay it's paired with.
    tourDim = 100004,
    tourBubble = 100005,
}

-- DisplayOrder for the top-level ScreenGuis (the window vs the loading banner).
constants.displayOrder = {
    window = 99999,
    banner = 100000,
    -- modal popups sit above everything, dim included
    popup = 100001,
}

return constants
]=====]

sources["utility/enums"] = [=====[
-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local enums = {}

-- FromValue with a manual scan fallback for executors whose Enum sandbox lacks it
function enums.itemFromValue(enumType, value)
    local ok, item = pcall(function()
        return enumType:FromValue(value)
    end)
    if ok and item then
        return item
    end

    local itemsOk, items = pcall(function()
        return enumType:GetEnumItems()
    end)
    if not itemsOk then
        return nil
    end

    for _, enumItem in items do
        if enumItem.Value == value then
            return enumItem
        end
    end

    return nil
end

return enums
]=====]

sources["utility/filesystem"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Filesystem Abstraction
-- Uses native executor functions when available, simulates with instances

local services = require(script.Parent.services)
-- local variables = require(script.Parent.variables)

local filesystem = {}

local isStudio = services.getService("RunService"):IsStudio()

-- An executor's own globals live in the running script's environment, not in _G. Read through
-- getfenv() so a missing one reads as nil instead of throwing on an executor that sandboxes
-- unknown global reads, and pcall the read itself for the ones that sandbox getfenv too.
local env: any = (function()
    local ok, fenv = pcall(getfenv)
    return if ok and type(fenv) == "table" then fenv else {}
end)()

local fileNames = {
    "writefile",
    "readfile",
    "appendfile",
    "isfile",
    "delfile",
    "listfiles",
    "makefolder",
    "isfolder",
    "delfolder",
}

-- Everything the library needs from a filesystem, built out of whatever an environment actually
-- exposes, one name at a time. Checking `writefile` alone and assuming the rest follow is how a
-- hub on a thinner executor used to die on its first `listfiles`: the library called a nil value,
-- and the error surfaced from whatever triggered the save rather than from the missing function.
--
-- The stand-ins are chosen so the library's own paths keep working: the readers answer "nothing
-- there" (`isfile` -> false, `listfiles` -> {}), `appendfile` is rebuilt out of read + write, and
-- the writers throw a named error - which every save path already pcalls - so a save reports
-- failure instead of quietly doing nothing.
--
-- Exported so the specs can hand it a pretend executor (a thin one, a partial one) instead of
-- only ever seeing whichever machine the tests happen to run on.
function filesystem.forEnvironment(source: any)
    local from: any = if type(source) == "table" then source else {}

    local function native(name: string)
        local ok, fn = pcall(function()
            return from[name]
        end)
        return if ok and typeof(fn) == "function" then fn else nil
    end

    local function refuse(name: string)
        return function(): any
            error(`Rayfield: this executor exposes no {name}, so nothing can be saved to disk`, 0)
        end
    end

    local fns: { [string]: any } = {}
    local absent: { string } = {}
    for _, name in fileNames do
        if native(name) == nil then
            table.insert(absent, name)
        end
    end

    fns.writefile = native("writefile") or refuse("writefile")
    fns.readfile = native("readfile") or refuse("readfile")
    fns.isfile = native("isfile") or function(): boolean
        return false
    end
    fns.isfolder = native("isfolder") or function(): boolean
        return false
    end
    fns.listfiles = native("listfiles") or function(): { string }
        return {}
    end
    -- nothing to make; the write that follows is what will report the failure
    fns.makefolder = native("makefolder") or function() end
    fns.delfile = native("delfile") or function() end
    fns.delfolder = native("delfolder") or function() end

    fns.appendfile = native("appendfile")
        or function(path: string, content: string)
            local existing = ""
            if fns.isfile(path) then
                local ok, body = pcall(fns.readfile, path)
                existing = if ok and type(body) == "string" then body else ""
            end
            fns.writefile(path, existing .. content)
        end

    return {
        fns = fns,
        missing = absent,
        -- anything can be saved at all only when both halves of a write are there
        available = native("writefile") ~= nil and native("readfile") ~= nil,
    }
end

if isStudio then
    -- Studio simulation using Instance hierarchy under ReplicatedStorage.
    -- Files are StringValues, folders are Folders. Glass is glass.

    filesystem.available = true
    filesystem.missing = {}

    local root = Instance.new("Folder")
    root.Name = "Filesystem"
    root.Parent = services.getService("ReplicatedStorage")

    local function splitPath(path: string): { string }
        local parts = {}
        for part in string.gmatch(path, "[^/]+") do
            table.insert(parts, part)
        end
        return parts
    end

    local function resolveParent(parts: { string }, createMissing: boolean): Instance?
        local current: Instance = root
        for i = 1, #parts - 1 do
            local child = current:FindFirstChild(parts[i])
            if not child then
                if not createMissing then
                    return nil
                end
                local folder = Instance.new("Folder")
                folder.Name = parts[i]
                folder.Parent = current
                child = folder
            end
            current = child :: Instance
        end
        return current
    end

    local function fileFromInstance(instance: Instance?): StringValue?
        if instance and instance:IsA("StringValue") then
            return instance
        end
        return nil
    end

    function filesystem.writefile(path: string, content: string)
        local parts = splitPath(path)
        assert(#parts > 0, "Invalid path")

        local parent = resolveParent(parts, true)
        assert(parent, "Invalid path")
        local fileName = parts[#parts]

        local existing = parent:FindFirstChild(fileName)
        local existingFile = fileFromInstance(existing)
        if existingFile then
            existingFile.Value = content
        else
            if existing then
                existing:Destroy()
            end
            local file = Instance.new("StringValue")
            file.Name = fileName
            file.Value = content
            file.Parent = parent
        end
    end

    function filesystem.readfile(path: string): string
        local parts = splitPath(path)
        assert(#parts > 0, "Invalid path")

        local parent = resolveParent(parts, false)
        assert(parent, "File not found: " .. path)

        local file = parent:FindFirstChild(parts[#parts])
        local stringFile = fileFromInstance(file)
        assert(stringFile, "File not found: " .. path)

        return stringFile.Value
    end

    function filesystem.appendfile(path: string, content: string)
        local parts = splitPath(path)
        assert(#parts > 0, "Invalid path")

        local parent = resolveParent(parts, false)
        assert(parent, "File not found: " .. path)

        local file = parent:FindFirstChild(parts[#parts])
        local stringFile = fileFromInstance(file)
        assert(stringFile, "File not found: " .. path)

        stringFile.Value = stringFile.Value .. content
    end

    function filesystem.isfile(path: string): boolean
        local parts = splitPath(path)
        if #parts == 0 then
            return false
        end

        local parent = resolveParent(parts, false)
        if not parent then
            return false
        end

        return fileFromInstance(parent:FindFirstChild(parts[#parts])) ~= nil
    end

    function filesystem.listfiles(folder: string): { string }
        local parts = splitPath(folder)
        local current: Instance = root

        for _, part in parts do
            local child = current:FindFirstChild(part)
            if not child or not child:IsA("Folder") then
                error("Folder not found: " .. folder)
            end
            current = child
        end

        local results: { string } = {}
        for _, child in current:GetChildren() do
            table.insert(results, folder .. "/" .. child.Name)
        end
        return results
    end

    function filesystem.delfile(path: string)
        local parts = splitPath(path)
        assert(#parts > 0, "Invalid path")

        local parent = resolveParent(parts, false)
        assert(parent, "File not found: " .. path)

        local file = parent:FindFirstChild(parts[#parts])
        local stringFile = fileFromInstance(file)
        assert(stringFile, "File not found: " .. path)

        stringFile:Destroy()
    end

    function filesystem.makefolder(path: string)
        local parts = splitPath(path)
        if #parts == 0 then
            return
        end

        local current: Instance = root
        for _, part in parts do
            local child = current:FindFirstChild(part)
            if not child then
                local folder = Instance.new("Folder")
                folder.Name = part
                folder.Parent = current
                child = folder
            end
            current = child :: Instance
        end
    end

    function filesystem.isfolder(path: string): boolean
        local parts = splitPath(path)
        if #parts == 0 then
            return false
        end

        local current: Instance = root
        for _, part in parts do
            local child = current:FindFirstChild(part)
            if not child or not child:IsA("Folder") then
                return false
            end
            current = child
        end
        return true
    end

    function filesystem.delfolder(path: string)
        local parts = splitPath(path)
        assert(#parts > 0, "Invalid path")

        local parent = resolveParent(parts, false)
        assert(parent, "Folder not found: " .. path)

        local folder = parent:FindFirstChild(parts[#parts])
        assert(folder and folder:IsA("Folder"), "Folder not found: " .. path)

        folder:Destroy()
    end
else
    -- Anything else: an executor, thin or complete. Every entry point exists whatever it exposes,
    -- so nothing in the library can call a nil value.
    local resolved = filesystem.forEnvironment(env)
    for name, fn in resolved.fns do
        (filesystem :: any)[name] = fn
    end
    filesystem.missing = resolved.missing
    filesystem.available = resolved.available
end

-- Whether anything can actually be read from or written to disk.
--
-- Callers used to ask "is there an isfile?" and skip their disk work when there wasn't. Since
-- forEnvironment gives every entry point a stand-in, that question always answers yes now - so a
-- font loader on an executor with no file API would download every .ttf it could never cache.
-- Ask here instead. The isfile check stays too, for a caller (or a spec) that removes it outright.
function filesystem.usable(): boolean
    return filesystem.available == true and typeof(filesystem.isfile) == "function"
end

function filesystem.ensureFolder(path: string)
    if not filesystem.isfolder(path) then
        filesystem.makefolder(path)
    end
end

function filesystem.ensureDir(dir: string)
    local built = ""
    for part in string.gmatch(dir, "[^/]+") do
        built = if built == "" then part else built .. "/" .. part
        if not filesystem.isfolder(built) then
            filesystem.makefolder(built)
        end
    end
end

return filesystem
]=====]

sources["utility/filesystemManager"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local filesystem = require(script.Parent.filesystem)
local path = require(script.Parent.path)

-- defaults
local DEFAULT_ROOT_PATH = "Rayfield"

local fileSystemManager = {}
fileSystemManager.__index = fileSystemManager

export type FileSystemManager = {
    root: string,
    assets: string,
    getPath: (self: FileSystemManager, subpath: string?) -> string,
    getAssetsFolder: (self: FileSystemManager, subfolder: string?) -> string,
    getRootFolder: (self: FileSystemManager) -> string,
}

function fileSystemManager.new(name: string?): FileSystemManager
    -- ensure the folder exists
    local root = name or DEFAULT_ROOT_PATH
    local self = setmetatable({
        root = root,
        assets = root .. "/Assets",
    }, fileSystemManager) :: any
    pcall(filesystem.ensureFolder, self.root)
    pcall(filesystem.ensureFolder, self.assets)

    return self
end

function fileSystemManager:getPath(subpath: string?): string
    return path.join(self.root, subpath)
end

function fileSystemManager:getAssetsFolder(subfolder: string?): string
    if subfolder then
        local assetPath = path.join(self.assets, subfolder)
        pcall(filesystem.ensureFolder, assetPath)
        return assetPath
    end
    return self.assets
end

function fileSystemManager:getRootFolder(): string
    return self.root
end

return fileSystemManager
]=====]

sources["utility/flagNames"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local flagNames = {}

local offsetBasis = 2166136261
local prime = 16777619

-- FNV-1a over the raw bytes. Same name, same flag, every session, or saved configs stop reloading.
local function hashName(name: string): number
    local hash = offsetBasis
    for index = 1, #name do
        hash = bit32.bxor(hash, string.byte(name, index))
        -- split the multiply so it never runs out of double precision
        local low = hash % 65536
        local high = (hash - low) / 65536
        hash = (((high * prime) % 65536) * 65536 + low * prime) % 4294967296
    end
    return hash
end

-- Derives a suitable config flag key from element name.
function flagNames.deriveFlagFromName(name: string): string
    local flag = name:gsub("(%S+)", function(w: string): string
        return w:sub(1, 1):upper() .. w:sub(2, -1)
    end):gsub("[^%w]", "")

    -- %w is ASCII only, so a name like "音量" strips down to nothing and the element would
    -- silently skip persistence. Hash the name instead and it keeps a stable key.
    if flag == "" and name ~= "" then
        return string.format("Flag%08x", hashName(name))
    end

    return flag
end

return flagNames
]=====]

sources["utility/fontManager"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local services = require(script.Parent.services)
local httpService = services.getService("HttpService")
local runService = services.getService("RunService")
local fileSystem = require(script.Parent.filesystem)
local assetResolver = require(script.Parent.assetResolver)
local log = require(script.Parent.log)
local path = require(script.Parent.path)

local function jsonEncode(data: unknown): string?
    local success, result = pcall(function()
        return httpService:JSONEncode(data)
    end)
    if success and type(result) == "string" then
        return result
    else
        log.warn("Failed to encode JSON:", result)
        return nil
    end
end

local function jsonDecode(jsonString: string): unknown?
    local success, result = pcall(function()
        return httpService:JSONDecode(jsonString)
    end)
    if success then
        return result
    else
        log.warn("Failed to decode JSON:", result)
        return nil
    end
end

local fontManager = {}
fontManager.__type = "fontManager"

export type FontFace = {
    name: string,
    family: string,
    weight: number,
    style: string,
    assetId: string,
}

export type FontManifest = {
    name: string,
    faces: { FontFace },
}

export type CachedFont = {
    customId: number | string,
    manifest: FontManifest,
    loadedFromDisk: boolean,
    variants: { [string]: Font },
}

export type FontCache = { [number]: CachedFont }

export type FontResolverOptions = {
    fallbackFont: Font?,
    saveToDisk: boolean?,
    skipCache: boolean?,
}

type FontManagerState = {
    _debug: boolean,
    rootFolder: string,
    assetResolver: assetResolver.AssetResolver,
    defaultOptions: FontResolverOptions,
    fontCache: FontCache?,
}

export type FontManager = FontManagerState & {
    resolve: (self: FontManager, id: number | string) -> Font?,
    loadFont: (
        self: FontManager,
        id: (number | string)?,
        fontWeight: Enum.FontWeight?,
        fontStyle: Enum.FontStyle?,
        saveToDisk: boolean?,
        skipCache: boolean?
    ) -> Font?,
    getFontFromId: (self: FontManager, id: number | string) -> Font?,
}

export type fontManager = FontManager

-- the manifest comes off the network, so trust nothing about its shape. names feed straight
-- into disk paths, so sanitize them here too. returns nil for anything we cant use.
local function validateManifest(manifest: unknown): FontManifest?
    local candidate = manifest :: any
    if type(candidate) ~= "table" or type(candidate.name) ~= "string" or type(candidate.faces) ~= "table" then
        return nil
    end
    candidate.name = path.sanitizeFile(candidate.name)
    if #candidate.name == 0 or #candidate.faces == 0 then
        return nil
    end
    for _, face in candidate.faces do
        if type(face) ~= "table" or type(face.name) ~= "string" or type(face.assetId) ~= "string" then
            return nil
        end
        face.name = path.sanitizeFile(face.name)
        if #face.name == 0 then
            return nil
        end
    end
    return candidate :: FontManifest
end

-- a face only downloads when its file is missing, so an error page or a truncated body written to
-- disk would shadow the real font every session after. check the signature like we do for pngs
local fontSignatures = { "\0\1\0\0", "OTTO", "true", "ttcf", "wOFF", "wOF2" }

local function isFontBody(body: string): boolean
    for _, signature in fontSignatures do
        if string.sub(body, 1, #signature) == signature then
            return true
        end
    end
    return false
end

local env = getfenv()

local function variantKey(fontWeight: Enum.FontWeight, fontStyle: Enum.FontStyle): string
    return tostring(fontWeight) .. "|" .. tostring(fontStyle)
end

local function resolveId(id: unknown): number?
    if type(id) == "number" then
        return id
    end

    if type(id) == "string" then
        return tonumber(id)
    end

    return nil
end

function fontManager.__index(self: FontManagerState, key: unknown): unknown
    local classMember = (fontManager :: any)[key]
    if classMember ~= nil then
        return classMember
    end

    local resolvedId = resolveId(key)
    if not resolvedId then
        return nil
    end

    local fontCache = self.fontCache
    if fontCache then
        local cached = fontCache[resolvedId]
        if cached then
            local regularKey = variantKey(Enum.FontWeight.Regular, Enum.FontStyle.Normal)
            local regularFont = cached.variants and cached.variants[regularKey]
            if regularFont then
                return regularFont
            end

            for _, font in pairs(cached.variants or {}) do
                return font
            end
        end
    end

    return nil
end

function fontManager.new(
    rootFolder: string,
    useDebug: boolean?,
    useCache: boolean?,
    assetContentDownloadUrl: assetResolver.AssetDownloadUrl?,
    defaultOptions: FontResolverOptions?
): FontManager
    local defaultResolverOptions = defaultOptions
        or {
            saveToDisk = true,
            skipCache = not useCache or false,
            fallbackFont = Font.fromEnum(Enum.Font.SourceSans),
        }
    local self = setmetatable(
        {
            rootFolder = rootFolder,
            fontCache = if useCache then {} :: FontCache else nil,
            assetResolver = assetResolver.new(useCache, assetContentDownloadUrl),
            defaultOptions = defaultResolverOptions,
            _debug = useDebug or runService:IsStudio() or false,
        } :: FontManagerState,
        fontManager
    ) :: any
    -- executors without filesystem support must degrade to the fallback font, not kill the require
    pcall(fileSystem.ensureFolder, rootFolder)
    return self
end

function fontManager.loadFont(
    self: FontManager,
    id: (number | string)?,
    fontWeight: Enum.FontWeight?,
    fontStyle: Enum.FontStyle?,
    saveToDisk: boolean?,
    skipCache: boolean?
): Font?
    if saveToDisk == nil then
        saveToDisk = self.defaultOptions.saveToDisk
    end
    if skipCache == nil then
        skipCache = self.defaultOptions.skipCache
    end
    local requestedFontWeight = fontWeight or Enum.FontWeight.Regular
    local requestedFontStyle = fontStyle or Enum.FontStyle.Normal
    local cacheKey = variantKey(requestedFontWeight, requestedFontStyle)
    local rawId = self.assetResolver:resolve(id)
    local resolvedId = resolveId(rawId)
    if not resolvedId then
        log.warn("Invalid font id: " .. tostring(id))
        return self.defaultOptions.fallbackFont
    end
    -- if the font is already cached, return it
    local fontCache = self.fontCache
    if fontCache and not skipCache then
        local cachedFont = fontCache[resolvedId]
        if cachedFont then
            local cachedVariant = cachedFont.variants and cachedFont.variants[cacheKey]
            if cachedVariant then
                if self._debug then
                    log.print("Loaded font from cache for id: " .. tostring(resolvedId))
                end
                return cachedVariant
            end

            local ok, loadedFont = pcall(Font.new, cachedFont.customId :: any, requestedFontWeight, requestedFontStyle)
            if ok and loadedFont then
                cachedFont.variants = cachedFont.variants or {}
                cachedFont.variants[cacheKey] = loadedFont
                if self._debug then
                    log.print("Loaded font variant from cache for id: " .. tostring(resolvedId))
                end
                return loadedFont
            else
                if self._debug then
                    log.warn("Failed to load font from cache for id: " .. tostring(resolvedId))
                end
                fontCache[resolvedId] = nil
                return self.defaultOptions.fallbackFont
            end
        end
    end

    -- if saveToDisk is false, we cannot load the font from disk, so we return the default font
    if not saveToDisk then
        if self._debug then
            log.warn("Font loading without saving to disk can be detected by Anti-cheats.")
        end

        return self.defaultOptions.fallbackFont
    end

    -- if the font is not cached, we need to load it from the asset resolver
    local manifestPath = self.rootFolder .. "/" .. resolvedId .. ".json"
    -- fonts only load through the disk cache; without a file API there is just the fallback
    if not fileSystem.usable() then
        return self.defaultOptions.fallbackFont
    end
    local possibleFontManifest: string? = nil
    local downloadedManifest = false
    if runService:IsStudio() and self._debug then
        log.warn("Font manifest loading is not supported in Studio. Using default font manifest for testing.")
        possibleFontManifest =
            '{"name":"Inter","faces":[{"name":"Thin","weight":100,"style":"normal","assetId":"rbxassetid://12187277209"},{"name":"Extra Light","weight":200,"style":"normal","assetId":"rbxassetid://12187293441"},{"name":"Light","weight":300,"style":"normal","assetId":"rbxassetid://12187268450"},{"name":"Regular","weight":400,"style":"normal","assetId":"rbxassetid://12187266066"},{"name":"Medium","weight":500,"style":"normal","assetId":"rbxassetid://12187336822"},{"name":"Semi Bold","weight":600,"style":"normal","assetId":"rbxassetid://12187254443"},{"name":"Bold","weight":700,"style":"normal","assetId":"rbxassetid://12187275575"},{"name":"Extra Bold","weight":800,"style":"normal","assetId":"rbxassetid://12187267750"},{"name":"Black","weight":900,"style":"normal","assetId":"rbxassetid://12187359223"}]}'
    elseif fileSystem.isfile(manifestPath) then
        local ok, contents = pcall(fileSystem.readfile, manifestPath)
        possibleFontManifest = ok and contents or nil
    else
        -- written below only once it validates, so a bad body never poisons the cache
        possibleFontManifest = self.assetResolver:getAssetContentFromId(resolvedId, false)
        downloadedManifest = possibleFontManifest ~= nil
    end
    local fontManifest: FontManifest? = nil
    if possibleFontManifest then
        local ok, parsedManifest = pcall(jsonDecode, possibleFontManifest)
        if ok and parsedManifest then
            fontManifest = validateManifest(parsedManifest)
        else
            if self._debug then
                log.warn(
                    "Failed to parse font manifest for font id: "
                        .. tostring(resolvedId)
                        .. ". Error: "
                        .. tostring(parsedManifest)
                )
            end
        end
    else
        return self.defaultOptions.fallbackFont
    end
    if not fontManifest then
        if self._debug then
            log.warn("Font manifest is nil for font id: " .. tostring(resolvedId))
        end
        -- a cached manifest that fails validation would fail forever; drop it
        pcall(fileSystem.delfile, manifestPath)
        return self.defaultOptions.fallbackFont
    end
    if downloadedManifest and possibleFontManifest then
        pcall(fileSystem.writefile, manifestPath, possibleFontManifest)
    end
    local fontDirectory = self.rootFolder .. "/" .. fontManifest.name
    local madeAllFontsLocal = true
    -- create folder for the font
    if not pcall(fileSystem.ensureFolder, fontDirectory) then
        return self.defaultOptions.fallbackFont
    end

    -- iterate over each face, caching each to disk like we do images: a face only downloads once,
    -- later sessions reuse the local file and just re-resolve it
    for i, face in ipairs(fontManifest.faces) do
        local fontFacePath = fontDirectory .. "/" .. face.name:gsub(" ", "-") .. ".ttf"
        if not fileSystem.isfile(fontFacePath) then
            local fontFaceId = self.assetResolver:resolve(face.assetId)
            local fontFaceContent = if fontFaceId ~= nil
                then self.assetResolver:getAssetContentFromId(fontFaceId, false)
                else nil
            if not fontFaceContent or not isFontBody(fontFaceContent) then
                madeAllFontsLocal = false
                if self._debug then
                    log.warn(
                        "Font face content is missing or not a font for font id: "
                            .. tostring(resolvedId)
                            .. ", face: "
                            .. face.name
                    )
                end
                continue
            end
            pcall(fileSystem.writefile, fontFacePath, fontFaceContent)
        end
        local ok, uri = pcall(env.getcustomasset, fontFacePath)
        if ok and type(uri) == "string" then
            fontManifest.faces[i].assetId = uri
            if self._debug then
                log.print("Loaded font face for id: " .. tostring(resolvedId) .. ", face: " .. face.name)
            end
        else
            madeAllFontsLocal = false
            if self._debug then
                log.warn("Failed to load font face for id: " .. tostring(resolvedId) .. ", face: " .. face.name)
            end
        end
    end
    -- every face must be local before we hand the font over; falling back to the remote id
    -- here would fetch the asset this whole flow exists to keep off the wire
    if not madeAllFontsLocal then
        return self.defaultOptions.fallbackFont
    end

    local encodedManifest = jsonEncode(fontManifest)
    if not encodedManifest or not pcall(fileSystem.writefile, fontDirectory .. "/manifest.json", encodedManifest) then
        return self.defaultOptions.fallbackFont
    end
    local manifestOk, fontManifestId = pcall(env.getcustomasset, fontDirectory .. "/manifest.json")
    if not manifestOk or not fontManifestId then
        if self._debug then
            log.warn("Failed to load font manifest for id: " .. tostring(resolvedId))
        end
        return self.defaultOptions.fallbackFont
    end
    -- load the font using the manifest
    local ok, loadedFont = pcall(Font.new, fontManifestId :: any, requestedFontWeight, requestedFontStyle)
    if not ok or not loadedFont then
        if self._debug then
            log.warn("Failed to load font for id: " .. tostring(resolvedId))
        end
        return self.defaultOptions.fallbackFont
    end

    -- write the font manifest to the disk
    fontCache = self.fontCache
    if fontCache then
        fontCache[resolvedId] = {
            customId = fontManifestId,
            manifest = fontManifest,
            loadedFromDisk = true,
            variants = {
                [cacheKey] = loadedFont,
            },
        }
        if self._debug then
            log.print("Cached font for id: " .. tostring(resolvedId))
        end
    end
    return loadedFont
end

function fontManager.resolve(self: FontManager, id: number | string): Font?
    local resolvedId = resolveId(id)
    if not resolvedId then
        return nil
    end

    local fontCache = self.fontCache
    if fontCache then
        local cached = fontCache[resolvedId]
        if cached then
            if self._debug then
                log.print("Resolved font for id: " .. tostring(resolvedId))
            end
            for _, font in pairs(cached.variants or {}) do
                return font
            end
        end
    end

    return nil
end

function fontManager.getFontFromId(self: FontManager, id: number | string): Font?
    return self:resolve(id)
end

return fontManager
]=====]

