--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local functions = {}

local textMetrics = require(script.Parent.textMetrics)
local colors = require(script.Parent.colors)
local flags = require(script.Parent.flagNames)

-- Read a boolean property that accepts either casing, with a default for when neither is set.
--
-- Why this needs a helper: the obvious one-liner is wrong for exactly the value that matters.
-- `(properties.showIndex or properties.ShowIndex) ~= false` evaluates `false or nil` to nil, and
-- nil ~= false is true - so passing `showIndex = false` is silently ignored and the option can
-- only ever be turned ON. Live-caught on ReorderList, whose index badges kept rendering for a
-- caller that had explicitly switched them off.
function functions.readBool(properties: { [string]: any }, name: string, default: boolean): boolean
    local value = properties[name]
    if value == nil then
        value = properties[string.upper(string.sub(name, 1, 1)) .. string.sub(name, 2)]
    end
    if value == nil then
        return default
    end
    return value ~= false
end

-- Read a control's starting value from the first of `names` that is actually PRESENT, then
-- from `default`/`Default` as a last resort.
--
-- Two things this fixes at once. Presence, not truthiness: `properties.value or properties.Value`
-- evaluates `false or nil` to nil, so a declared `value = false` is indistinguishable from not
-- declaring one at all - the same trap readBool exists for. And the alias: `value` is this
-- fork's canonical name for a starting state, but upstream Rayfield called it `Default`, so that
-- is what hub scripts carried over from it (and anything generated against upstream's docs)
-- reach for. Accepting it costs nothing and silently ignoring it was a real reported confusion.
-- Each caller spells out its own `names` order because a few controls put a
-- domain-specific spelling first (colorpicker's `color`, gradientpicker's `gradient`).
function functions.readValue(properties: { [string]: any }, names: { string }): any
    for _, name in names do
        if properties[name] ~= nil then
            return properties[name]
        end
    end
    if properties.default ~= nil then
        return properties.default
    end
    return properties.Default
end

-- The fill a CONTAINER card carries - a surface other element cards sit on (Collapsible's open
-- content, a Panel). The elements inside are cards in the full element fill, so a container in
-- that same fill turns each of them into a grey rectangle on a grey rectangle, visible only by
-- its outline. Half the fill sits between the window behind and the elements on top, so they
-- still read as raised.
function functions.containerTransparency(elementTransparency: number?): number
    return 1 - (1 - (elementTransparency or 0)) * 0.5
end

functions.textWidth = textMetrics.textWidth
functions.textHeight = textMetrics.textHeight
functions.deriveFlagFromName = flags.deriveFlagFromName
functions.contrastColor = colors.contrastColor
functions.toColorSequence = colors.toColorSequence
functions.contrastText = colors.contrastText
functions.flattenColor = colors.flatten

return functions
]=====]

sources["utility/hsvEditor"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Shared Saturation/Value square + horizontal Hue rail, factored out of the old colorpicker.luau
-- so both ColorPicker (editing its own solid colour) and GradientPicker (editing whichever stop
-- is selected) drive the exact same widget instead of drifting two copies of the same drag math.
-- Owns its own instances and input wiring; the caller just supplies where to build it and what
-- to do with the (h, s, v) it produces.

local hsvEditor = {}

local variables = require(script.Parent.variables)

local dragInfo = TweenInfo.new(0.12, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local followInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local heldInfo = TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

-- left(red) -> right, wrapping back to red, for the horizontal hue rail
local hueSequence = ColorSequence.new({
    ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 0, 0)),
    ColorSequenceKeypoint.new(0.17, Color3.fromRGB(255, 255, 0)),
    ColorSequenceKeypoint.new(0.33, Color3.fromRGB(0, 255, 0)),
    ColorSequenceKeypoint.new(0.50, Color3.fromRGB(0, 255, 255)),
    ColorSequenceKeypoint.new(0.67, Color3.fromRGB(0, 0, 255)),
    ColorSequenceKeypoint.new(0.83, Color3.fromRGB(255, 0, 255)),
    ColorSequenceKeypoint.new(1.00, Color3.fromRGB(255, 0, 0)),
})

local function clamp01(n)
    return math.clamp(n, 0, 1)
end

-- opts: {
--   position, squareSize, hueHeight, gap = layout
--   hue, sat, val = initial channels
--   onChange = function(h, s, v, mode) end -- fires continuously (mode: "drag"/"instant")
--   onCommit = function() end -- fires once when a drag/click-set finishes, for persistence
-- }
function hsvEditor.build(window, owner, parent, opts)
    opts = opts or {}
    local squareSize = opts.squareSize or 150
    local hueHeight = opts.hueHeight or 14
    local gap = opts.gap or 14
    local onChange = opts.onChange or function() end
    local onCommit = opts.onCommit or function() end

    local hue, sat, val = opts.hue or 0, opts.sat or 1, opts.val or 1

    local root = window:Create("Frame", {
        Position = opts.position or UDim2.fromOffset(0, 0),
        Size = UDim2.fromOffset(squareSize, squareSize + gap + hueHeight),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = parent,
    })

    -- Saturation/Value square: hue-tinted base, a white->clear saturation gradient (left->right)
    -- layered on top, and a clear->black value gradient (top->bottom) over that.
    local square = window:Create("Frame", {
        Size = UDim2.fromOffset(squareSize, squareSize),
        BackgroundColor3 = Color3.fromHSV(hue, 1, 1),
        BorderSizePixel = 0,

        BackgroundTransparency = 1, -- Shown = 0

        Parent = root,
    })
    window:Create("UICorner", { CornerRadius = UDim.new(0, 10), Parent = square })
    local squareStroke = window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),

        Transparency = 1, -- Shown = 0.9

        Parent = square,
    })

    local satOverlay = window:Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,

        BackgroundTransparency = 1, -- Shown = 0

        Parent = square,
    })
    window:Create("UICorner", { CornerRadius = UDim.new(0, 10), Parent = satOverlay })
    window:Create("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Parent = satOverlay,
    })

    local valOverlay = window:Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.fromRGB(0, 0, 0),
        BorderSizePixel = 0,

        BackgroundTransparency = 1, -- Shown = 0

        Parent = square,
    })
    window:Create("UICorner", { CornerRadius = UDim.new(0, 10), Parent = valOverlay })
    window:Create("UIGradient", {
        Rotation = 90,
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(1, 0),
        }),
        Parent = valOverlay,
    })

    local cursor = window:Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Size = UDim2.fromOffset(16, 16),
        BackgroundColor3 = Color3.fromHSV(hue, sat, val),
        BorderSizePixel = 0,
        ZIndex = 3,

        BackgroundTransparency = 1, -- Shown = 0

        Parent = square,
    })
    window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = cursor })
    local cursorStroke = window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),
        Thickness = 2,

        Transparency = 1, -- Shown = 0

        Parent = cursor,
    })

    local squareInteract = window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        Text = "",
        AutoButtonColor = false,
        ZIndex = 4,

        Parent = square,
    })

    -- Horizontal hue rail, directly under the square.
    local hueBar = window:Create("Frame", {
        Position = UDim2.fromOffset(0, squareSize + gap),
        Size = UDim2.new(1, 0, 0, hueHeight),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,

        BackgroundTransparency = 1, -- Shown = 0

        Parent = root,
    })
    window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = hueBar })
    window:Create("UIGradient", { Color = hueSequence, Parent = hueBar })

    local hueHandle = window:Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(hue, 0, 0.5, 0),
        Size = UDim2.fromOffset(hueHeight + 6, hueHeight + 6),
        BackgroundColor3 = Color3.fromHSV(hue, 1, 1),
        BorderSizePixel = 0,
        ZIndex = 3,

        BackgroundTransparency = 1, -- Shown = 0

        Parent = hueBar,
    })
    window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = hueHandle })
    local hueHandleStroke = window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),
        Thickness = 2,

        Transparency = 1, -- Shown = 0

        Parent = hueHandle,
    })

    local hueInteract = window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 1, 16),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        Text = "",
        AutoButtonColor = false,
        ZIndex = 4,

        Parent = hueBar,
    })

    local controller = { root = root, square = square, hueBar = hueBar }

    local function paint(mode)
        local mapHue = Color3.fromHSV(hue, 1, 1)
        local satPos = UDim2.new(sat, 0, 1 - val, 0)
        local huePos = UDim2.new(hue, 0, 0.5, 0)
        local swatch = Color3.fromHSV(hue, sat, val)

        if mode == "instant" then
            square.BackgroundColor3 = mapHue
            cursor.Position, cursor.BackgroundColor3 = satPos, swatch
            hueHandle.Position, hueHandle.BackgroundColor3 = huePos, mapHue
        else
            local moveInfo = if mode == "drag" then dragInfo else followInfo
            variables.tweenService:Create(square, moveInfo, { BackgroundColor3 = mapHue }):Play()
            variables.tweenService:Create(cursor, moveInfo, { Position = satPos, BackgroundColor3 = swatch }):Play()
            variables.tweenService:Create(hueHandle, moveInfo, { Position = huePos, BackgroundColor3 = mapHue }):Play()
        end
    end

    function controller:SetColor(h, s, v, animate)
        hue, sat, val = h, s, v
        paint(if animate then "animate" else "instant")
    end

    -- Fade the whole editor in/out together, mirroring the shown/hidden convention every other
    -- element's _setShown uses (one table of instance -> target prop, so the owner's own
    -- _setShown can just delegate here instead of reaching into our private instances).
    function controller:SetVisible(shown, animate)
        local set = {
            [square] = { BackgroundTransparency = if shown then 0 else 1 },
            [squareStroke] = { Transparency = if shown then 0.9 else 1 },
            [satOverlay] = { BackgroundTransparency = if shown then 0 else 1 },
            [valOverlay] = { BackgroundTransparency = if shown then 0 else 1 },
            [cursor] = { BackgroundTransparency = if shown then 0 else 1 },
            [cursorStroke] = { Transparency = if shown then 0 else 1 },
            [hueBar] = { BackgroundTransparency = if shown then 0 else 1 },
            [hueHandle] = { BackgroundTransparency = if shown then 0 else 1 },
            [hueHandleStroke] = { Transparency = if shown then 0 else 1 },
        }
        for instance, props in set do
            if animate then
                variables.tweenService:Create(instance, followInfo, props):Play()
            else
                for prop, value in props do
                    instance[prop] = value
                end
            end
        end
    end

    function controller:Destroy()
        root:Destroy()
    end

    -- Mouse in AbsolutePosition space (see colorpicker.luau's original note: GetMouseLocation()
    -- sits one gui-inset below AbsolutePosition when the screen ignores the inset).
    local function mouseLocation()
        local mouse = variables.userInputService:GetMouseLocation()
        local screenGui = window.screenGui
        if screenGui and screenGui.IgnoreGuiInset then
            return mouse - variables.guiService:GetGuiInset()
        end
        return mouse
    end

    local drag, dragIsMouse, dragConnection = nil, false, nil

    local function setHeld(region)
        local cursorSize = if region == "square" then UDim2.fromOffset(20, 20) else UDim2.fromOffset(16, 16)
        local hueSize = if region == "hue"
            then UDim2.fromOffset(hueHeight + 10, hueHeight + 10)
            else UDim2.fromOffset(hueHeight + 6, hueHeight + 6)
        variables.tweenService:Create(cursor, heldInfo, { Size = cursorSize }):Play()
        variables.tweenService:Create(hueHandle, heldInfo, { Size = hueSize }):Play()
    end

    local function pump()
        local prevHue, prevSat, prevVal = hue, sat, val

        if drag == "square" then
            local size = square.AbsoluteSize
            if size.X <= 0 or size.Y <= 0 then
                return
            end
            local mouse = mouseLocation()
            sat = clamp01((mouse.X - square.AbsolutePosition.X) / size.X)
            val = 1 - clamp01((mouse.Y - square.AbsolutePosition.Y) / size.Y)
        elseif drag == "hue" then
            local width = hueBar.AbsoluteSize.X
            if width <= 0 then
                return
            end
            local mouse = mouseLocation()
            hue = clamp01((mouse.X - hueBar.AbsolutePosition.X) / width)
        else
            return
        end

        if hue == prevHue and sat == prevSat and val == prevVal then
            return
        end

        paint("drag")
        onChange(hue, sat, val, "drag")
    end

    local function endDrag()
        drag = nil
        setHeld(nil)
        if dragConnection then
            dragConnection:Disconnect()
            dragConnection = nil
        end
        onCommit()
    end

    local function beginDrag(region, isMouse)
        drag = region
        dragIsMouse = isMouse
        setHeld(region)
        pump()

        if dragConnection then
            dragConnection:Disconnect()
            dragConnection = nil
        end

        dragConnection = variables.runService.RenderStepped:Connect(function()
            local mouseReleased = dragIsMouse
                and not variables.userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
            if window.unloaded or not drag or mouseReleased then
                if mouseReleased then
                    endDrag()
                    return
                end
                if dragConnection then
                    dragConnection:Disconnect()
                    dragConnection = nil
                end
                return
            end
            pump()
        end)
    end

    window:ConnectFor(owner, squareInteract.InputBegan, function(input)
        if
            input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch
        then
            beginDrag("square", input.UserInputType == Enum.UserInputType.MouseButton1)
        end
    end)

    window:ConnectFor(owner, hueInteract.InputBegan, function(input)
        if
            input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch
        then
            beginDrag("hue", input.UserInputType == Enum.UserInputType.MouseButton1)
        end
    end)

    window:ConnectFor(owner, variables.userInputService.InputEnded, function(input)
        if
            (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch)
            and drag
        then
            endDrag()
        end
    end)

    paint("instant")

    return controller
end

return hsvEditor
]=====]

sources["utility/icons"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Community icon packs, originally sourced from github.com/Footagesus/Icons (the same data
-- WindUI uses) and mirrored into this project's own GitHub (opploop/97979797) so it isn't a
-- stranger's repo this loads and executes code from at runtime - pinned to one exact commit,
-- the same trust model the rest of this codebase already uses to load itself (see
-- dev-loadstring.luau's own comments on why a commit SHA, never a branch name). Fetched the
-- same way every other dev-loadstring asset in this codebase is: a plain HttpGet + loadstring,
-- no server script or RemoteFunction involved (unlike WindUI's own loader, which leans on a
-- server-side Script to hand icons to clients over a RemoteFunction - real for a dev who owns
-- the game and can add one via Studio, but nothing an executor-injected library like this one
-- can stand up in someone else's game). Each pack is ~18k icons combined; fetched lazily (only
-- the packs actually asked for) and cached per pack after the first successful fetch.
--
-- Two on-disk shapes exist upstream, both handled transparently by find():
--   flat:        { [iconName] = "rbxassetid://..." }                      (lucide, solar, sfsymbols, gravity)
--   spritesheet: { Icons = { [iconName] = { Image, ImageRectSize, ImageRectPosition } }, Spritesheets = {...} }  (geist, craft)

local icons = {}

-- Bump this (and re-verify every pack still resolves) to pick up a newer snapshot - never point
-- this at a branch name instead, or every future fetch trusts whatever's there at the time
-- without anyone having actually looked at it first.
local pinnedCommit = "47b8b275ec886ceb58b074bf491d28be48427779"
local baseUrl = "https://raw.githubusercontent.com/opploop/97979797/" .. pinnedCommit .. "/"

icons.packNames = {
    lucide = true,
    solar = true,
    sfsymbols = true,
    gravity = true,
    geist = true,
    craft = true,
}

export type IconEntry = {
    Image: string,
    ImageRectSize: Vector2?,
    ImageRectOffset: Vector2?,
}

local cache: { [string]: any } = {} -- pack -> the raw decoded table, or false if fetching it failed
local attempted: { [string]: boolean } = {}

-- Fetches and loadstring()s one pack's data file. Synchronous (HttpGet yields the calling
-- thread, same tradeoff every other dev-loadstring fetch in this codebase already makes) - only
-- ever pays that cost once per pack per session, on whichever call happens to ask for it first.
local function fetchPack(pack: string): any
    if cache[pack] ~= nil then
        return cache[pack] or nil
    end
    if attempted[pack] then
        return nil
    end
    attempted[pack] = true

    local ok, result = pcall(function()
        local code = game:HttpGet(baseUrl .. pack .. "/dist/Icons.lua", true)
        local fn = loadstring(code)
        assert(fn, "loadstring failed")
        return fn()
    end)

    if ok and typeof(result) == "table" then
        cache[pack] = result
        return result
    end

    cache[pack] = false -- remembered so a dead pack/repo doesn't retry a fetch every lookup
    return nil
end

-- Looks up one icon, normalized to the same shape regardless of which on-disk format its pack
-- uses. Returns nil if the pack name is unknown, its fetch failed, or the icon isn't in it -
-- callers should have a plain fallback ready (a built-in rbxassetid, or draw one from Frames)
-- rather than assume this always succeeds, since it depends on a third-party repo staying up.
function icons.find(name: string, pack: string?): IconEntry?
    -- a fresh local, not a reassigned parameter: Luau keeps the declared `string?` on the
    -- parameter however it is written to, so fetchPack still saw an optional
    local packName = pack or "lucide"
    if not icons.packNames[packName] then
        return nil
    end

    local data = fetchPack(packName)
    if not data then
        return nil
    end

    if data.Icons then
        local entry = data.Icons[name]
        if not entry or not entry.Image then
            return nil
        end
        -- entry.Image is an index into data.Spritesheets (e.g. 4), not a usable rbxassetid on
        -- its own - a spritesheet icon pack packs many icons' rects onto a handful of shared
        -- sheet images, and this is which one to slice this icon's rect out of. Every
        -- geist/craft lookup was returning that bare number as Image until now, which Roblox
        -- silently renders as nothing (no error, just an empty ImageLabel). tostring() matters:
        -- entry.Image decodes as a Lua number, but Spritesheets' own keys decode as strings (the
        -- JSON-shaped source has them quoted) - a number 4 and a string "4" are different table
        -- keys in Lua, so the unconverted lookup silently missed every single time.
        local sheet = data.Spritesheets and data.Spritesheets[tostring(entry.Image)]
        if not sheet then
            return nil
        end
        return {
            Image = sheet,
            ImageRectSize = entry.ImageRectSize,
            ImageRectOffset = entry.ImageRectPosition,
        }
    end

    local raw = data[name]
    if typeof(raw) ~= "string" then
        return nil
    end
    return { Image = raw }
end

-- Applies an icon by name straight onto an existing ImageLabel/ImageButton, including the rect
-- properties a spritesheet pack's icon needs (harmlessly zeroed for a flat-pack icon, which
-- doesn't use them). Returns false (and leaves the instance untouched) if the icon couldn't be
-- resolved, so a caller can fall back to whatever it already had.
function icons.apply(instance: Instance, name: string, pack: string?): boolean
    local entry = icons.find(name, pack)
    if not entry then
        return false
    end
    local target = instance :: any
    target.Image = entry.Image
    target.ImageRectSize = entry.ImageRectSize or Vector2.new(0, 0)
    target.ImageRectOffset = entry.ImageRectOffset or Vector2.new(0, 0)
    return true
end

return icons
]=====]

sources["utility/image"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local imageCache = require(script.Parent.imageCache)
local variables = require(script.Parent.variables)
local icons = require(script.Parent.icons)
local log = require(script.Parent.log)

type AvatarCallback = imageCache.AvatarCallback
type PreloadCallback = imageCache.PreloadCallback

local image = {}

image.rewrites = imageCache.rewrites
image.onBlock = nil :: ((unknown) -> ())?

-- images that resolve blank in secure mode (their icon isnt cached yet) register here, so the real
-- texture can be dropped in once the background download lands instead of leaving a blank. keyed by
-- instance so re-assigning the same icon cant stack up, and weakly so a destroyed one isnt pinned
type PendingProperties = { [string]: boolean }

image.pending = {} :: { [number]: { [Instance]: PendingProperties } }

-- once preload settles nothing else will ever land, so theres nothing left worth tracking
local settled = false

local imageProperties: { [string]: boolean } = {
    Image = true,
    HoverImage = true,
    PressedImage = true,
}

-- An icon string that looks like a pack lookup but doesn't resolve renders as nothing at all,
-- with no error anywhere - live-caught more than once as "the icon just isn't showing" with no
-- way to tell a typo from a dead pack. Warned once per distinct string so a whole tab list of
-- the same bad name doesn't flood the console.
local warnedIcons: { [string]: boolean } = {}
local function warnUnresolvedIcon(value: string, reason: string)
    if warnedIcons[value] then
        return
    end
    warnedIcons[value] = true
    log.warn(("Rayfield: icon '%s' didn't resolve - %s"):format(value, reason))
end

local function idOf(value: unknown): number?
    if type(value) == "number" then
        return value
    elseif type(value) == "string" then
        return tonumber(string.match(value, "^rbxassetid://(%d+)$"))
    end
    return nil
end

local function blocked(value: unknown): string
    if image.onBlock then
        image.onBlock(value)
    end
    return ""
end

function image.preload(onSettled: PreloadCallback?): (boolean, number)
    settled = false
    return imageCache.preload(function(failed)
        -- everything that cached has already rebound through onCached, and everything else never
        -- will, so drop whats left and stop tracking rather than growing all session
        settled = true
        table.clear(image.pending)
        if onSettled then
            onSettled(failed)
        end
    end)
end

function image.avatar(userId: number, onReady: AvatarCallback?): string
    if not variables.secureMode then
        return `rbxthumb://type=AvatarHeadShot&id={userId}&w=48&h=48`
    end

    return imageCache.avatar(userId, onReady)
end

function image.assign(instance: Instance, property: string, value: unknown)
    local target = instance :: any
    if not imageProperties[property] then
        target[property] = value
        return
    end
    target[property] = image.resolve(value)
    -- in secure mode an un-cached icon resolves blank; remember it so it appears once cached
    if variables.secureMode and not settled then
        local id = idOf(value)
        if id and not image.rewrites[id] then
            local waiting = image.pending[id]
            if not waiting then
                waiting = setmetatable({}, { __mode = "k" }) :: any
                image.pending[id] = waiting
            end
            local properties = waiting[instance]
            if not properties then
                properties = {}
                waiting[instance] = properties
            end
            properties[property] = true
        end
    end
end

-- imageCache calls this when a background icon download lands: drop the real texture into every
-- instance that resolved blank waiting for it
imageCache.onCached = function(id: number)
    local waiting = image.pending[id]
    if not waiting then
        return
    end
    local uri = image.rewrites[id]
    if uri then
        for instance, properties in waiting do
            if instance.Parent then
                local target = instance :: any
                for property in properties do
                    target[property] = uri
                end
            end
        end
    end
    image.pending[id] = nil
end

function image.resolve(value: unknown): string
    if value == nil or value == 0 or value == "" then
        return ""
    end

    if type(value) == "string" then
        if string.sub(value, 1, 11) == "rbxasset://" then
            return value
        end
        if string.sub(value, 1, 11) == "rbxthumb://" then
            return if variables.secureMode then blocked(value) else value
        end
        -- "pack:icon-name" (e.g. "lucide:lock") - a community icon pack lookup (see icons.luau).
        -- Only ever resolves a *flat*-format pack's icon this way (lucide/solar/sfsymbols/
        -- gravity - each already a plain rbxassetid, nothing else to set); a spritesheet pack's
        -- icon (geist/craft) also needs ImageRectSize/Offset set alongside Image, which this
        -- single-string return can't carry - use icons.apply() directly for those instead.
        -- Falls through to the plain-string case below on any miss (unknown pack/name, pack
        -- fetch failed, ...), which just resolves to the string as-is - a caller passing a real
        -- rbxassetid://... never round-trips through here to begin with.
        local packName, iconName = string.match(value, "^(%a+):([%w%-_]+)$")
        -- both, not just the first: string.match hands back two optionals and narrowing one
        -- says nothing about the other
        if packName and iconName then
            if not icons.packNames[packName] then
                warnUnresolvedIcon(value, ("unknown icon pack '%s'"):format(packName))
            else
                local found = icons.find(iconName, packName)
                if found and not found.ImageRectSize then
                    return found.Image
                end
                if found then
                    -- a spritesheet pack's icon can't come back as a single string - see above
                    warnUnresolvedIcon(
                        value,
                        ("'%s' is a spritesheet pack; use icons.apply() rather than an icon string"):format(packName)
                    )
                else
                    warnUnresolvedIcon(value, ("no icon named '%s' in '%s'"):format(iconName, packName))
                end
            end
        end
    end

    local id: number? = nil
    if type(value) == "number" then
        id = value
    elseif type(value) == "string" then
        id = tonumber(string.match(value, "^rbxassetid://(%d+)$"))
    end

    local rewrite = if id then image.rewrites[id] else nil
    if rewrite then
        return rewrite
    end

    if variables.secureMode then
        return blocked(value)
    end

    if type(value) == "number" then
        return "rbxassetid://" .. value
    end
    if type(value) == "string" then
        return value
    end

    return blocked(value)
end

return image
]=====]

sources["utility/imageCache"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local filesystem = require(script.Parent.filesystem)
local path = require(script.Parent.path)
local variables = require(script.Parent.variables)
local constants = require(script.Parent.constants)

export type RewriteMap = { [number]: string }
export type CacheSettledCallback = (failed: number) -> ()
export type PreloadCallback = CacheSettledCallback
export type AvatarCallback = (uri: string) -> ()
export type OnCachedCallback = (id: number) -> ()
export type ThumbnailEntry = {
    state: string?,
    imageUrl: string?,
}
export type ThumbnailResponse = {
    data: { ThumbnailEntry }?,
}
local imageCache = {}

local cacheRoot = variables.fileSystemManager:getRootFolder()
local cacheFolder = variables.fileSystemManager:getAssetsFolder()
local assetResolver = variables.assetResolver

-- raw host, not the /blob/ page: that 302s and executors that dont follow redirects
-- would cache the redirect body instead of the png
local assetBase = "https://raw.githubusercontent.com/SiriusSoftwareLtd/rayfield-gen2/main/assets/"
local headshotPx = 48
local thumbEndpoint =
    "https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds=%d&size=%dx%d&format=Png&isCircular=false"

local manifest: { [number]: string } = {}
for _, id in constants.icons do
    local iconId = id :: number
    manifest[iconId] = assetBase .. tostring(iconId) .. ".png"
end
local manifestSize = 0
for _ in manifest do
    manifestSize += 1
end

imageCache.rewrites = {} :: RewriteMap
imageCache.onCached = nil :: OnCachedCallback? -- image sets this to rebind blank instances when a background download lands

local pngMagic = "\137PNG\r\n\26\n"

local function cacheFile(filePath: string, url: string): string?
    -- no custom assets or no file API means nothing can be cached at all
    if type(getfenv().getcustomasset) ~= "function" or not filesystem.usable() then
        return nil
    end
    if not filesystem.isfile(filePath) then
        pcall(filesystem.ensureFolder, cacheRoot)
        pcall(filesystem.ensureFolder, cacheFolder)
        local body = assetResolver:getAssetContentFromUrl(url, filePath, false)
        -- never write a non-png body (error page, redirect html) to disk; a poisoned
        -- cache file would shadow the real asset on every later session
        if not body or string.sub(body, 1, 8) ~= pngMagic then
            return nil
        end
        if not pcall(filesystem.writefile, filePath, body) then
            return nil
        end
    end
    local ok, uri = pcall(getfenv().getcustomasset, filePath)
    return if ok and type(uri) == "string" then uri else nil
end

local function avatarPath(userId: number): string
    return path.join(cacheFolder, "avatar_" .. tostring(userId) .. ".png")
end

local function decodeThumbnailUrl(body: string): string?
    local decodeOk, parsed = pcall(function()
        return variables.httpService:JSONDecode(body)
    end)
    if not decodeOk or type(parsed) ~= "table" then
        return nil
    end

    local data = (parsed :: ThumbnailResponse).data
    if type(data) ~= "table" then
        return nil
    end

    local entry = data[1]
    if type(entry) ~= "table" then
        return nil
    end

    local thumbnail = entry :: ThumbnailEntry
    if thumbnail.state == "Completed" and type(thumbnail.imageUrl) == "string" then
        return thumbnail.imageUrl
    end

    return nil
end

local function fetchAvatar(userId: number): string?
    local cdnUrl: string? = nil
    for attempt = 1, 4 do
        -- retries must bypass the session cache or a cached "Pending" response wins forever
        local body = assetResolver:getAssetContentFromUrl(
            string.format(thumbEndpoint, userId, headshotPx, headshotPx),
            "avatar:" .. tostring(userId),
            attempt > 1
        )
        if body then
            local imageUrl = decodeThumbnailUrl(body)
            if imageUrl then
                cdnUrl = imageUrl
                break
            end
        end
        task.wait(0.3)
    end
    if not cdnUrl then
        return nil
    end

    return cacheFile(avatarPath(userId), cdnUrl)
end

-- onSettled(failed) fires once every background download has finished, with the count that never
-- cached (a genuine failure), so callers can surface it without spamming per-icon.
function imageCache.preload(onSettled: PreloadCallback?): (boolean, number)
    local env = getfenv()
    if type(env.getcustomasset) ~= "function" or not filesystem.usable() then
        if onSettled then
            -- defer so a caller that assigns state right after calling preload still sees this
            task.defer(onSettled, manifestSize)
        end
        return false, manifestSize
    end

    local rewrites = imageCache.rewrites
    table.clear(rewrites) -- drop stale entries before remapping (no-op on the fixed built-in manifest)

    local function settle()
        if not onSettled then
            return
        end
        local failed = 0
        for id in manifest do
            if not rewrites[id] then
                failed += 1
            end
        end
        onSettled(failed)
    end

    local pending, missing = 0, 0
    local spawning = true -- keep a synchronously-finishing download from settling mid-loop
    for id, url in manifest do
        local filePath = path.join(cacheFolder, tostring(id) .. ".png")
        local uri: string? = nil
        if filesystem.isfile(filePath) then
            local ok, res = pcall(env.getcustomasset, filePath)
            uri = if ok and type(res) == "string" then res else nil
        end
        if uri then
            -- already on disk from a past session: use it right away
            rewrites[id] = uri
        else
            -- not cached yet: fetch it in the background and swap it in once it lands
            missing += 1
            pending += 1
            task.spawn(function()
                local cached = cacheFile(filePath, url)
                if cached then
                    rewrites[id] = cached
                    if imageCache.onCached then
                        -- a throw in here would strand the counter and settle would never fire
                        pcall(imageCache.onCached, id)
                    end
                end
                pending -= 1
                if pending == 0 and not spawning then
                    settle()
                end
            end)
        end
    end

    spawning = false
    if pending == 0 then
        settle()
    end

    return missing == 0, missing
end

function imageCache.avatar(userId: unknown, onReady: AvatarCallback?): string
    if type(userId) ~= "number" then
        return ""
    end

    -- no file API means no local avatar cache; secure mode just goes without the headshot
    if not filesystem.usable() then
        return ""
    end

    local filePath = avatarPath(userId)
    if filesystem.isfile(filePath) then
        local ok, uri = pcall(getfenv().getcustomasset, filePath)
        if ok and type(uri) == "string" then
            return uri
        end
    end

    if onReady then
        task.spawn(function()
            local uri = fetchAvatar(userId)
            if uri then
                onReady(uri)
            end
        end)
    end

    return ""
end

return imageCache
]=====]

sources["utility/locale"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Rayfield's localization core. Two kinds of copy pass through here: the library's own chrome
-- (search placeholder, "Signed in as", the settings page, and so on) and whatever names a dev
-- gives its elements. Both resolve the same way - the dev translator first, then the built-in
-- table for the active locale, then the source string itself - so anything untranslated still
-- reads in plain English instead of a blank or a raw key.
--
-- Only strings wrapped in locale.t() are treated as copy. Element values, slider readouts,
-- keybind keys and hex codes are data, not language, so they're deliberately left alone.

local variables = require(script.Parent.variables)
local log = require(script.Parent.log)
local autoTranslateEngine = require(script.Parent.autoTranslate)

local locale = {}

-- Live machine translation (see autoTranslate.luau) - opt-in via CreateWindow's autoTranslate
-- property. Off by default: a dev who already hand-writes translations (locale.register) or
-- brings a translator hook shouldn't suddenly start making network calls they didn't ask for.
locale.autoTranslate = false

-- Windows subscribe here (see window.luau's own use of this) to hear about a translation that
-- landed *after* resolve() already had to answer with a fallback - the whole point of firing the
-- request async instead of blocking. A plain array rather than routing through locale.resolve
-- itself: locale.luau has no concept of "on-screen instances", only window.luau's
-- localeProperties does, so the actual re-apply stays there; this just rings the bell.
local listeners: { () -> () } = {}

function locale.addListener(callback: () -> ())
    table.insert(listeners, callback)
end

function locale.removeListener(callback: () -> ())
    local index = table.find(listeners, callback)
    if index then
        table.remove(listeners, index)
    end
end

local function notifyListeners()
    for _, callback in listeners do
        task.spawn(callback)
    end
end

export type LocaleToken = { [any]: string }
export type Translator = (source: string, localeId: string) -> string?
export type TranslationTables = { [string]: { [string]: string } }

-- English is canonical: every wrapped string in src is written in it, so the source text is
-- also its own lookup key. A new language is just a table keyed by those same source strings;
-- any key it omits falls back to English on its own. Regional tables ("pt-br") win over the
-- bare language ("pt") when both exist.
--
-- Portuguese and Spanish ship built in (see builtinLocales.luau) - every source string wrapped
-- in locale.t() across src/ as of this file, covering the library's own chrome (search, config
-- save/load/export/import, keybind clash messages, "Signed in as", and so on). A dev's own
-- locale.register() call still wins over these - built-ins are merged first, so anything a dev
-- registers for the same locale/key overwrites the shipped translation, not the other way round.
locale.strings = (function()
    -- table.clone alone is shallow - the per-locale string maps would stay shared references
    -- into the required (and require-cached) builtinLocales module, so a dev's own
    -- locale.register() mutating locale.strings.pt in place would permanently leak into that
    -- cached module table for the rest of the session. Clone one level deeper instead.
    local builtin = require(script.Parent.builtinLocales)
    local cloned = {}
    for id, entries in builtin do
        cloned[id] = table.clone(entries)
    end
    return cloned
end)() :: TranslationTables
-- ["fr"] = { ["Signed in as"] = "Connecte en tant que", ... },

-- active locale id and the optional dev hook (source, localeId) -> string?. both start neutral,
-- so with no setup at all everything renders in English.
locale.current = "en"
locale.translator = nil :: Translator?

-- a wrapped string carries this tag as a key so Window:Create can tell copy apart from a plain
-- value. property values are always Roblox datatypes or primitives, never plain tables, so the
-- table-with-tag shape is unambiguous.
local tokenTag = {}

local function languageOf(id: string): string
    return string.match(id, "^(%a+)") or id
end

-- Wrap a string so it localizes. Returns the value untouched when there's nothing to translate
-- (non-strings, empty) so callers can wrap unconditionally without special-casing nil names.
function locale.t(source: unknown): unknown
    if type(source) ~= "string" or source == "" then
        return source
    end
    return { [tokenTag] = source }
end

-- True for a value produced by locale.t that still carries a source string.
function locale.isToken(value: unknown): boolean
    return type(value) == "table" and type((value :: { [any]: unknown })[tokenTag]) == "string"
end

function locale.sourceOf(token: LocaleToken): string
    return token[tokenTag]
end

-- Resolve a source string to the active locale. Order: dev translator hook (explicit, always
-- wins, pcall'd so a bad hook can't take the UI down) - then anything actually configured, built
-- in or by the dev (the exact-locale table, then the language-only table) - THEN, only for a
-- string neither of those has an answer for, a live machine translation - then the source itself
-- as the last resort.
--
-- User-caught: this used to ask the live engine *before* the table, on the theory that live
-- translation needs zero maintenance so it should win whenever it's got an answer. That's backwards
-- for anything a dev actually configured on purpose (Window:RegisterTranslations, or a built-in
-- chrome string) - a hand-picked translation existing at all means someone already decided it's
-- the right one, and a machine translation landing in the *separate* autoTranslate cache later
-- must never quietly outrank it. The live engine's whole job is filling in whatever nobody
-- configured, not second-guessing what somebody did.
function locale.resolve(source: unknown): any
    if type(source) ~= "string" then
        return source
    end

    if locale.translator then
        local ok, translated = pcall(locale.translator, source, locale.current)
        if ok and type(translated) == "string" and translated ~= "" then
            return translated
        end
    end

    local exact = locale.strings[locale.current]
    if exact and exact[source] then
        return exact[source]
    end

    local language = locale.strings[languageOf(locale.current)]
    if language and language[source] then
        return language[source]
    end

    -- nothing configured for this exact string - only now does the live engine get a say
    if locale.autoTranslate and locale.current ~= "en" then
        local cached = autoTranslateEngine.peek(source, locale.current)
        if cached then
            return cached
        end
        -- not cached (yet) - fire the request in the background and fall through to the source
        -- text for *this* call; notifyListeners re-resolves everything once the real answer
        -- lands, same path a runtime SetLocale already uses.
        autoTranslateEngine.request(source, locale.current, notifyListeners)
    end

    return source
end

-- Merge dev-supplied translation tables into the built-in set. Keyed by locale id (lowercased),
-- each a map of source string -> translation. Merges rather than replaces, so repeated calls (or
-- several windows) accumulate instead of clobbering. These sit alongside the library's own tables;
-- a dev translator, if set, still wins over both.
--
-- Entries are checked here rather than trusted: a non-string translation would sail through
-- resolve() into a Text property and only blow up at render, nowhere near the register call.
function locale.register(tables: TranslationTables?)
    if type(tables) ~= "table" then
        return
    end
    for id, entries in tables do
        if type(id) == "string" and type(entries) == "table" then
            id = string.lower(id)
            local target = locale.strings[id]
            if not target then
                target = {}
                locale.strings[id] = target
            end
            for source, translated in entries do
                if type(source) == "string" and type(translated) == "string" then
                    target[source] = translated
                else
                    log.warn(`Rayfield: skipping a '{id}' translation, entries must be string to string.`)
                end
            end
        end
    end
end

-- Point the active locale at `localeId` (lowercased), falling back to English when it isn't a
-- usable string. Setting it alone touches nothing on screen; callers re-resolve their own labels.
function locale.setActive(localeId: string?): string
    locale.current = if type(localeId) == "string" and localeId ~= "" then string.lower(localeId) else "en"
    return locale.current
end

-- The player's language from Roblox's locale id (e.g. "fr-fr"), lowercased and kept whole so a
-- translator sees the exact region. resolve() narrows to the language part when it needs to.
function locale.detect(): string
    local id = variables.localizationService.RobloxLocaleId
    if type(id) == "string" and id ~= "" then
        return string.lower(id)
    end
    return "en"
end

return locale
]=====]

sources["utility/lockable"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Shared Lock/Unlock for tab elements. Call lockable(Class) once on the prototype. Ported from
-- upstream Rayfield Gen2 1.2's own Element Locking.
--
-- A locked element does three things: it dims so you can see it's out of reach, it stops taking
-- pointer input via an opaque scrim laid over it (see Window:_buildLockScrim), and its callback
-- is refused at the funnel every interactive element already routes through (Window:_runGuarded
-- checks `element.locked` before it runs anything). The scrim alone only ever stopped a real
-- click; the funnel check is what makes a lock hold against a programmatic `:Set()` or a fired
-- signal too, which is what a caller gating a premium feature actually needs.
--
-- A handful of components (Toggle, Button, Dropdown, HoldButton) already carry their own
-- bespoke SetLocked with a purpose-built dimming look - lockable(Class) is skipped for those
-- and Lock/Unlock/IsLocked are instead defined by hand right next to that existing method (see
-- each file's own SetLocked), aliasing straight into it rather than layering a second,
-- competing scrim on top.

local function lockable<T>(class: T): T
    local target = class :: any

    -- Lock it. `reason` is an optional line shown in place of the description while locked.
    function target:Lock(reason: string?)
        self.window:_setElementLocked(self, true, reason)
    end

    function target:Unlock()
        self.window:_setElementLocked(self, false)
    end

    function target:IsLocked(): boolean
        return self.locked == true
    end

    return class
end

return lockable
]=====]

sources["utility/log"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Rayfield's own console output. Silenced under secure mode so the library never announces
-- itself through warn/print, both of which anti-cheats hook. The game's and the dev's own
-- output are left alone; this only gags Rayfield.

local runtime = require(script.Parent.runtime)

local log = {}

type SuppressPredicate = () -> boolean

local function defaultSecureModeSource(): boolean
    return runtime.secureMode
end

local secureModeSource: SuppressPredicate = defaultSecureModeSource
local suppressPredicate: SuppressPredicate? = nil

-- variables.luau points this at its mutable secureMode once it loads; until then the
-- runtime snapshot answers. nil restores the default.
function log.setSecureModeSource(source: SuppressPredicate?)
    secureModeSource = if type(source) == "function" then source else defaultSecureModeSource
end

-- extra gag for embedders (the test runner uses this), layered over secure mode so
-- loading variables never clobbers it. nil clears it.
function log.setSuppressPredicate(predicate: SuppressPredicate?)
    suppressPredicate = if type(predicate) == "function" then predicate else nil
end

local function shouldSuppress(): boolean
    if suppressPredicate and suppressPredicate() then
        return true
    end
    return secureModeSource()
end

function log.warn(...)
    if shouldSuppress() then
        return
    end
    warn(...)
end

function log.print(...)
    if shouldSuppress() then
        return
    end
    print(...)
end

return log
]=====]

sources["utility/moveable"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Shared Move* + SetVisible methods for tab elements. Call moveable(Class) once on the
-- prototype, after the class has already defined its own _setShown (SetVisible wraps it).

local hideDelay = 0.2 -- gives the fade-out a moment before pulling the row out of layout

local function moveable<T>(class: T): T
    local target = class :: any

    function target:MoveTo(index: number)
        self.tab:_moveElement(self, index)
    end

    function target:MoveToTop()
        self.tab:_moveElement(self, 1)
    end

    function target:MoveToBottom()
        self.tab:_moveElement(self, #self.tab.elements)
    end

    function target:MoveUp()
        local idx = table.find(self.tab.elements, self)
        if idx then
            self.tab:_moveElement(self, idx - 1)
        end
    end

    function target:MoveDown()
        local idx = table.find(self.tab.elements, self)
        if idx then
            self.tab:_moveElement(self, idx + 1)
        end
    end

    -- Devlog 7: every element gets :SetVisible(boolean) for free here, rather than touching
    -- ~20 component files individually. Wraps the class's own _setShown (already defined by
    -- this point - every component calls moveable() as its last line) so a runtime hide takes
    -- effect the same way a tab switch or window hide already would (dropdown closes its panel,
    -- hold button cancels an in-progress hold, ...), on top of also pulling the row out of
    -- layout entirely (main.Visible = false) rather than just fading its content, and pinning
    -- it hidden against any later automatic reveal (a tab switch, a window show) until
    -- SetVisible(true) explicitly clears it again.
    local ownSetShown = target._setShown
    if ownSetShown then
        target._setShown = function(self, shown, animate)
            if shown and self._userHidden then
                return
            end
            return ownSetShown(self, shown, animate)
        end

        function target:SetVisible(visible)
            visible = visible and true or false
            local wasHidden = self._userHidden or false
            if wasHidden == not visible then
                return
            end

            if visible then
                self._userHidden = false
                if self.main then
                    self.main.Visible = true
                end
                if self.descriptor and self.descriptor.main then
                    self.descriptor.main.Visible = true
                end
                if self.window and not self.window.hidden then
                    self:_setShown(true, self.window:_interactive())
                end
            else
                self._userHidden = true
                self:_setShown(false, true)

                local token = (self._hideToken or 0) + 1
                self._hideToken = token
                task.delay(hideDelay, function()
                    if self._userHidden and self._hideToken == token then
                        if self.main then
                            self.main.Visible = false
                        end
                        if self.descriptor and self.descriptor.main then
                            self.descriptor.main.Visible = false
                        end
                    end
                end)
            end
        end
    end

    return class
end

return moveable
]=====]

sources["utility/network"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local network = {}
network.__index = network

export type RequestFn = (...any) -> any

-- A `request`-shaped GET built out of game:HttpGet. Every executor that can fetch anything at all
-- has HttpGet - it is the call their own loaders are written with - while `request` and its four
-- aliases are the ones a thinner executor tends to be missing. Without this, a hub on such an
-- executor loses every downloaded asset (icons in secure mode, the brand fonts, translations)
-- with nothing but a "no request function available" line to go on.
function network.httpGetFallback(options: any): any
    local url = if type(options) == "table" then options.Url or options.url else options
    local method = if type(options) == "table" then options.Method or options.method else "GET"
    if type(url) ~= "string" or string.upper(tostring(method or "GET")) ~= "GET" then
        return { Success = false, StatusCode = 0, Body = "", Headers = {} }
    end

    local ok, body = pcall(function()
        return game:HttpGet(url, true)
    end)
    if not ok or type(body) ~= "string" then
        return { Success = false, StatusCode = 0, Body = "", Headers = {} }
    end
    return { Success = true, StatusCode = 200, Body = body, Headers = {} }
end

-- accepts the environment table from getfenv()
function network.getRequestFn(env: any?): RequestFn?
    env = env or getfenv()
    local ok, fn = pcall(function()
        return env.request
            or env.http_request
            or (env.http and env.http.request)
            or (env.syn and env.syn.request)
            or (env.fluxus and env.fluxus.request)
    end)
    return if ok and typeof(fn) == "function" then fn else nil
end

-- What a downloader should actually call: the executor's own `request` when it has one, and the
-- HttpGet stand-in when it doesn't. Only ever nil when the client cannot make an HTTP call at all.
function network.getFetchFn(env: any?): RequestFn?
    local fn = network.getRequestFn(env)
    if fn then
        return fn
    end
    local ok, httpGet = pcall(function()
        return (game :: any).HttpGet
    end)
    return if ok and typeof(httpGet) == "function" then network.httpGetFallback else nil
end

return network
]=====]

sources["utility/odometer"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Odometer readout: a number as a row of per-digit reels. Each digit is a clipped
-- cell holding a strip of glyphs; changing it tweens the strip so the new digit
-- rolls up from the bottom and the old one leaves the top. Non-digit characters
-- (separators, %, prefix/suffix) are static cells.
--
-- Cells are variable width (each digit's natural advance) so it reads like normal
-- text, not a monospaced counter, and the width tweens with the roll. Reconciles
-- from the right so decimals/suffixes stay put as digits grow on the left. Cells are
-- pooled and reused (hidden, never destroyed) so window:Create owns their cleanup.

local variables = require(script.Parent.variables)
local TextService = variables.textService

local odometer = {}
odometer.__index = odometer

-- Two stacked copies of 0-9. A reel on digit d rests at strip Y = -d*H. Rolling up
-- moves to higher indices; rolling down first jumps to the second copy (same glyph)
-- so it can travel down without running past index 0.
local stripLength = 20

local function measure(font, size, text)
    local params = Instance.new("GetTextBoundsParams")
    params.Text = text
    params.Font = font
    params.Size = size
    params.Width = math.huge
    local ok, bounds = pcall(TextService.GetTextBoundsAsync, TextService, params)
    return if ok then bounds else Vector2.new(size * 0.6, size)
end

-- Digit advances are the same for every odometer of a given font+size, but
-- GetTextBoundsAsync yields, so measure the ten digits once per (font, size) and
-- cache. Later odometers reuse the result and never touch TextService again.
local metricsCache = {}
local function digitMetrics(font, size)
    -- Style is part of the key: italic and normal measure differently
    local key = tostring(font.Family)
        .. "|"
        .. tostring(font.Weight)
        .. "|"
        .. tostring(font.Style)
        .. "|"
        .. tostring(size)
    local cached = metricsCache[key]
    if cached then
        return cached
    end

    local advance, maxWidth = {}, 0
    for d = 0, 9 do
        local w = math.ceil(measure(font, size, tostring(d)).X)
        advance[d] = w
        if w > maxWidth then
            maxWidth = w
        end
    end
    cached = { advance = advance, maxWidth = maxWidth }
    metricsCache[key] = cached
    return cached
end

-- window   : owning Window (for :Create, theming + cleanup)
-- container: Frame the row lives in; the odometer lays its cells out inside it
-- opts     : { textSize, alignment (Enum.HorizontalAlignment), transparency, duration,
--              color (a fixed Color3 instead of the theme's ContentColor - for a readout on a card
--              painted its own colour), font ("Font" or "TitleFont", the theme font it uses) }
function odometer.new(window, container, opts)
    opts = opts or {}
    local self = setmetatable({
        window = window,
        container = container,
        textSize = opts.textSize or 16,
        transparency = opts.transparency or 1, -- current base text transparency
        duration = opts.duration or 0.55,
        color = opts.color,
        fontKey = if opts.font == "TitleFont" then "TitleFont" else "Font",
        slots = {}, -- [indexFromRight] = { reel = reelData?, static = label? }
        length = 0, -- how many slots are currently shown
    }, odometer)

    self.roll = TweenInfo.new(self.duration, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

    -- Cells sit above the container so the digits never get hidden by it under Global
    -- ZIndexBehavior, wherever the container itself is stacked (floored at the old default).
    self.zIndex = math.max(container.ZIndex + 1, 6)

    -- Height tracks the text size (not the taller text-bounds height) so the readout
    -- keeps a plain-label footprint; neighbour digits sit one cell away, outside the clip.
    self.height = math.ceil(self.textSize)

    -- Natural advance per digit (includes side bearings), plus the widest: the
    -- scrolling strip uses the widest so no glyph clips mid-roll, while each clip
    -- cell uses its own digit's advance.
    local metrics = digitMetrics(window.theme[self.fontKey] or window.theme.Font, self.textSize)
    self.advance = metrics.advance
    self.maxWidth = metrics.maxWidth

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = opts.alignment or Enum.HorizontalAlignment.Left,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 0),

        Parent = container,
    })

    return self
end

-- The theme bindings every digit and static label takes: the theme font picked, and the theme's
-- text colour unless a fixed one was given (set on the label itself instead).
function odometer:_textTheme()
    if self.color then
        return { FontFace = self.fontKey }
    end
    return { TextColor3 = "ContentColor", FontFace = self.fontKey }
end

-- Recolour a fixed-colour readout (one built with opts.color): every digit and static label.
function odometer:SetColor(color: Color3)
    self.color = color
    for _, slot in self.slots do
        if slot.reel then
            for _, label in slot.reel.strip:GetChildren() do
                if label:IsA("TextLabel") then
                    label.TextColor3 = color
                end
            end
        end
        if slot.static then
            slot.static.TextColor3 = color
        end
    end
end

-- Lazily build (or fetch) the reel for a slot: a clipped cell + a fixed-width
-- strip of 20 themed digit labels, centred so the visible glyph sits in the
-- middle of the (variable-width) cell.
function odometer:_reel(index)
    local slot = self.slots[index]
    if slot.reel then
        return slot.reel
    end

    local cell = self.window:Create("Frame", {
        Name = "Reel",
        Size = UDim2.fromOffset(self.maxWidth, self.height),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ClipsDescendants = true,
        ZIndex = self.zIndex,

        Parent = self.container,
    })

    local strip = self.window:Create("Frame", {
        Size = UDim2.fromOffset(self.maxWidth, self.height),
        AnchorPoint = Vector2.new(0.5, 0), -- centred horizontally in the cell
        Position = UDim2.new(0.5, 0, 0, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = self.zIndex,

        Parent = cell,
    })

    for i = 0, stripLength - 1 do
        self.window:Create("TextLabel", {
            Text = tostring(i % 10),
            Position = UDim2.fromOffset(0, i * self.height),
            Size = UDim2.fromOffset(self.maxWidth, self.height),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = self.textSize,
            TextXAlignment = Enum.TextXAlignment.Center,
            TextYAlignment = Enum.TextYAlignment.Center,
            TextTransparency = self.transparency,
            TextColor3 = self.color,
            ZIndex = self.zIndex,

            Parent = strip,
        }, self:_textTheme())
    end

    local reel = { cell = cell, strip = strip, digit = 0, target = 0, stripTween = nil, sizeTween = nil }
    slot.reel = reel
    return reel
end

-- Fetch/build the static (separator/letter) label for a slot. Statics hug their
-- own glyph width so separators/suffixes space naturally.
function odometer:_static(index)
    local slot = self.slots[index]
    if slot.static then
        return slot.static
    end

    local label = self.window:Create("TextLabel", {
        Name = "Static",
        Size = UDim2.fromOffset(0, self.height),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = self.textSize,
        TextXAlignment = Enum.TextXAlignment.Center,
        TextYAlignment = Enum.TextYAlignment.Center,
        TextTransparency = self.transparency,
        TextColor3 = self.color,
        ZIndex = self.zIndex,

        Parent = self.container,
    }, self:_textTheme())

    slot.static = label
    return label
end

local function stopReel(reel)
    if reel.stripTween then
        reel.stripTween:Cancel()
        reel.stripTween = nil
    end
    if reel.sizeTween then
        reel.sizeTween:Cancel()
        reel.sizeTween = nil
    end
end

function odometer:_reelSnap(reel, digit)
    stopReel(reel)
    reel.cell.Size = UDim2.fromOffset(self.advance[digit], self.height)
    reel.strip.Position = UDim2.new(0.5, 0, 0, -digit * self.height)
    reel.digit = digit
    reel.target = digit
end

function odometer:_reelRoll(reel, digit, up)
    -- Finalise any in-flight roll so we start from a clean resting digit.
    if reel.stripTween or reel.sizeTween then
        self:_reelSnap(reel, reel.target)
    end

    local a = reel.digit
    if a == digit then
        return
    end

    local startIndex, targetIndex
    if up then
        startIndex = a
        targetIndex = a + (digit - a) % 10 -- 1..9 above, glyph at target = digit
    else
        startIndex = a + 10 -- jump to 2nd copy (same glyph) to travel downward
        targetIndex = startIndex - (a - digit) % 10
    end

    reel.strip.Position = UDim2.new(0.5, 0, 0, -startIndex * self.height)
    reel.target = digit

    -- Roll the strip vertically and reflow the cell to the new digit's width together.
    local stripTween = variables.tweenService:Create(reel.strip, self.roll, {
        Position = UDim2.new(0.5, 0, 0, -targetIndex * self.height),
    })
    local sizeTween = variables.tweenService:Create(reel.cell, self.roll, {
        Size = UDim2.fromOffset(self.advance[digit], self.height),
    })
    reel.stripTween = stripTween
    reel.sizeTween = sizeTween
    stripTween.Completed:Connect(function(state)
        if state == Enum.PlaybackState.Completed and reel.stripTween == stripTween then
            self:_reelSnap(reel, digit)
        end
    end)
    stripTween:Play()
    sizeTween:Play()
    reel.digit = digit
end

-- Show a slot as a digit; hide its static twin. A cell coming back from hidden
-- (the number grew past this column earlier, e.g. 100 -> 99 -> 100) snaps rather
-- than rolling from whatever stale digit it last held.
function odometer:_putDigit(index, digit, up, animate)
    local reel = self:_reel(index)
    local wasHidden = not reel.cell.Visible
    reel.cell.Visible = true
    reel.cell.LayoutOrder = -index
    if self.slots[index].static then
        self.slots[index].static.Visible = false
    end
    if animate and not wasHidden then
        self:_reelRoll(reel, digit, up)
    else
        self:_reelSnap(reel, digit)
    end
end

-- Show a slot as a static char; hide its reel twin.
function odometer:_putStatic(index, char)
    local label = self:_static(index)
    label.Text = char
    label.Visible = true
    label.LayoutOrder = -index
    if self.slots[index].reel then
        self.slots[index].reel.cell.Visible = false
    end
end

function odometer:_hide(index)
    local slot = self.slots[index]
    if not slot then
        return
    end
    if slot.reel then
        slot.reel.cell.Visible = false
    end
    if slot.static then
        slot.static.Visible = false
    end
end

-- Core: render `text`, animating digit changes when `animate` and rolling in the
-- direction implied by `up` (value increased vs decreased).
function odometer:_render(text, animate, up)
    text = tostring(text)

    -- skip the reconcile when unchanged; snap() runs every drag frame
    if text == self._lastText then
        return
    end
    self._lastText = text

    -- Split into whole UTF-8 characters, not bytes: a suffix like "°" is two
    -- bytes and string.sub would tear it into invalid halves (rendered as tofu).
    local chars = {}
    for _, code in utf8.codes(text) do
        table.insert(chars, utf8.char(code))
    end

    local n = #chars
    for i = 0, math.max(n, self.length) - 1 do
        self.slots[i] = self.slots[i] or {}
        if i < n then
            local char = chars[n - i] -- reconcile from the right
            if char:match("%d") then
                self:_putDigit(i, tonumber(char), up, animate)
            else
                self:_putStatic(i, char)
            end
        else
            self:_hide(i)
        end
    end
    self.length = n
end

-- Roll to `text` (digits animate, direction from `up`).
function odometer:to(text, up)
    self:_render(text, true, up)
end

-- Set `text` instantly (no roll).
function odometer:snap(text)
    self:_render(text, false, true)
end

-- Fade every current label toward `target` transparency, and remember it so
-- lazily-created cells come in at the same level. Mirrors Window:_reveal.
function odometer:reveal(target, animate, info)
    self.transparency = target
    for _, slot in self.slots do
        if slot.static and slot.static.Visible then
            self.window:_reveal(slot.static, { TextTransparency = target }, animate, info)
        end
        if slot.reel then
            for _, lbl in slot.reel.strip:GetChildren() do
                if lbl:IsA("TextLabel") then
                    self.window:_reveal(lbl, { TextTransparency = target }, animate, info)
                end
            end
        end
    end
end

return odometer
]=====]

sources["utility/ordering"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Shared layout ordering. Tabs and groups both space children by tens so a descriptor can
-- slot in right after its element (order + 1) without colliding with the next one.

type OrderedElement = {
    main: GuiObject,
    descriptor: { main: GuiObject }?,
}

local function assignOrder(element: OrderedElement, order: number)
    element.main.LayoutOrder = order
    if element.descriptor then
        element.descriptor.main.LayoutOrder = order + 1
    end
end

return assignOrder
]=====]

sources["utility/path"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local path = {}

function path.join(basePath: string, childPath: string?): string
    if not childPath or childPath == "" then
        return basePath
    end

    return basePath .. "/" .. childPath
end

-- Removing a character can expose a fresh "..", so every sanitizer drops the illegal
-- characters first and only then walks the dots out, repeating until nothing changes.
-- ".:./.:./x" is the case that motivates it: the dots are inert until the colons go.
local function stripTraversal(text: string): string
    local previous
    repeat
        previous = text
        text = text:gsub("%.%.", "")
    until text == previous
    return text
end

-- strips drive letters and leading slashes too, so a folder name can never escape the
-- executors workspace on its own
function path.sanitizeFolder(value: unknown): string
    local text = tostring(value):gsub("\\", "/"):gsub('[:<>"|?*%c]', "")
    text = stripTraversal(text):gsub("/+", "/")
    return (text:gsub("^/+", ""))
end

-- also drops the characters Windows refuses in filenames, so a window named
-- "MyHub: S3" still writes instead of failing on every save
function path.sanitizeFile(value: unknown): string
    local text = tostring(value):gsub("[/\\]", ""):gsub('[:<>"|?*%c]', "")
    return stripTraversal(text)
end

function path.basename(value: unknown): string
    return tostring(value):match("[^/\\]+$") or tostring(value)
end

function path.stripExtension(value: unknown, extension: string?): string
    if extension and extension ~= "" then
        local text = tostring(value)
        if text:sub(-#extension) == extension then
            return text:sub(1, -#extension - 1)
        end
        return text
    end

    local base = tostring(value):match("^(.+)%.%w+$")
    return base or tostring(value)
end

return path
]=====]

