sources["utility/persistenceConfig"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local variables = require(script.Parent.variables)
local filesystem = require(script.Parent.filesystem)
local log = require(script.Parent.log)
local path = require(script.Parent.path)
local paths = require(script.Parent.persistencePaths)
local atomic = require(script.Parent.persistenceWrite)

local persistenceConfig = {}

type PersistedControl = {
    value: unknown,
    flag: string?,
    _canBeNil: boolean?,
    _serialize: ((PersistedControl) -> unknown)?,
    _deserialize: ((PersistedControl, unknown) -> ())?,
    Set: (PersistedControl, unknown) -> (),
}

type ConfigWindow = {
    controls: { [string]: PersistedControl },
    configuration: {
        fileName: string?,
        customFolder: string?,
        ignoreFlags: { string }?,
    },
    name: string,
    _loading: boolean?,
    _loadedConfig: { [string]: unknown }?,
    _loadedConfigPath: string?,
    _controlOrder: { PersistedControl }?,
}

function persistenceConfig.getPath(window: ConfigWindow, name: unknown?): (string, string)
    -- Cast, not a shared type: persistencePaths declares its own ConfigWindow with just the
    -- fields IT needs, and two identical-looking table types from different modules are not
    -- interchangeable to Luau. This one is a superset (it also carries controls/_loading), so
    -- handing it over is safe - aliasing the two instead makes every controls/_loading access
    -- in this file a type error.
    return paths.getConfigPath(window :: any, name)
end

-- window.configuration.ignoreFlags as an O(1) lookup set, rebuilt fresh each call rather than
-- cached - it's a short dev-set list read a handful of times per save/load, not a hot path
-- worth the bookkeeping to keep a cache in sync with a table a dev could still be mutating.
-- Every registered control, in the order it was CREATED. A restore walks this rather than
-- window.controls, which is a hash keyed by flag and so hands its entries back in no particular
-- order - different from one session to the next.
--
-- The order matters whenever one control's callback shapes another. Live-reported: a hub whose
-- map picker's callback rebuilds the mob grid lost the saved mob selection on some reloads and not
-- others. When the grid happened to restore FIRST it had no mobs yet (they only exist once a map is
-- ticked), so its saved ticks were dropped as unknown; the picker restoring after then rebuilt the
-- grid empty. Restoring in creation order runs the picker first, the way the dev built them, so the
-- grid has its mobs by the time its own saved ticks arrive.
local function orderedControls(window: ConfigWindow): { { flag: string, control: PersistedControl } }
    local ordered = {}
    local seen: { [PersistedControl]: boolean } = {}
    local order: { PersistedControl } = window._controlOrder or {}
    for _, control in order do
        local flag = control.flag
        -- a control removed since (or re-registered under another flag) is skipped here
        if flag and window.controls[flag] == control and not seen[control] then
            seen[control] = true
            table.insert(ordered, { flag = flag, control = control })
        end
    end
    -- anything registered some other way still restores, after the ordered ones, sorted by flag
    -- so even that part is the same every session
    local rest = {}
    for flag, control in window.controls do
        if not seen[control] then
            table.insert(rest, { flag = flag, control = control })
        end
    end
    table.sort(rest, function(a, b)
        return a.flag < b.flag
    end)
    for _, entry in rest do
        table.insert(ordered, entry)
    end
    return ordered
end

local function ignoreSet(window: ConfigWindow): { [string]: boolean }
    local list = window.configuration and window.configuration.ignoreFlags
    local set: { [string]: boolean } = {}
    if type(list) == "table" then
        for _, flag in list do
            if type(flag) == "string" then
                set[flag] = true
            end
        end
    end
    return set
end

-- Every flag's current (or, if the control defines one, custom-serialized) value, minus
-- anything on window.configuration.ignoreFlags. Shared by the file-based save below and the
-- clipboard export path - both just want "what every control is set to right now" (ignore list
-- excepted), the file path just also layers on carrying forward not-yet-built controls.
local function collectFlags(window: ConfigWindow): { [string]: unknown }
    local ignored = ignoreSet(window)
    local flags: { [string]: unknown } = {}
    for flag, control in window.controls do
        if ignored[flag] then
            continue
        end
        local ok, value = pcall(function()
            local serialize = control._serialize
            if serialize then
                return serialize(control)
            end
            return control.value
        end)
        if ok then
            flags[flag] = value
        else
            log.warn("Rayfield: Failed to serialize flag '" .. tostring(flag) .. "' - " .. tostring(value))
        end
    end
    return flags
end

function persistenceConfig.save(window: ConfigWindow, name: unknown?): boolean
    local dir, fullPath = persistenceConfig.getPath(window, name)

    local flags = collectFlags(window)

    -- carry forward saved values whose elements aren't built yet; without this an early
    -- autosave would permanently drop a late element's saved value. only into the file they
    -- came from though, or Load("A") then Save("B") would smuggle A's flags into B.
    local loadedConfig = window._loadedConfig
    if loadedConfig and window._loadedConfigPath == fullPath then
        for flag, value in loadedConfig do
            if window.controls[flag] == nil then
                flags[flag] = value
            end
        end
    end

    local encodeSuccess, encoded = pcall(variables.httpService.JSONEncode, variables.httpService, flags)
    if not encodeSuccess then
        log.warn("Rayfield: Failed to encode configuration - " .. tostring(encoded))
        return false
    end

    local ok, err = pcall(function()
        atomic.write(dir, fullPath, encoded)
    end)

    if not ok then
        log.warn("Rayfield: Failed to save configuration - " .. tostring(err))
        return false
    end

    return true
end

-- Decode a saved config. Also hands back the raw text, so a file that read fine but isn't a
-- config can be backed up.
local function decodeFile(fullPath: string): ({ [string]: unknown }?, string?)
    if not filesystem.isfile(fullPath) then
        return nil, nil
    end

    local readOk, contents = pcall(filesystem.readfile, fullPath)
    if not readOk or type(contents) ~= "string" then
        log.warn("Rayfield: Failed to read configuration file")
        return nil, nil
    end

    local decodeOk, parsed = pcall(variables.httpService.JSONDecode, variables.httpService, contents)

    -- a scalar root is valid JSON but not a config, so it resets like any other bad file
    if not decodeOk or type(parsed) ~= "table" then
        return nil, contents
    end

    return parsed :: { [string]: unknown }, contents
end

-- Every corrupt file gets its own backup. Reusing one name would let a second corruption
-- destroy the salvageable data the first backup exists to keep.
local function backupPathFor(fullPath: string): string
    -- same path logic as getConfigPath, so the backup lands next to the file it mirrors
    local stem = path.stripExtension(fullPath, ".rfld")
    local candidate = stem .. " (Incorrect Format).rfld"
    local index = 2
    while index <= 100 and filesystem.isfile(candidate) do
        candidate = stem .. " (Incorrect Format " .. index .. ").rfld"
        index += 1
    end
    return candidate
end

function persistenceConfig.load(window: ConfigWindow, name: unknown?): boolean
    local dir, fullPath = persistenceConfig.getPath(window, name)

    -- no file API on this executor: nothing to load, degrade quietly
    if not filesystem.usable() then
        return false
    end

    local parsedFlags, raw = decodeFile(fullPath)

    -- a save that died mid-overwrite leaves its whole copy parked beside the wreck, so take
    -- that instead. only when the real file is really there, or a deleted config could come back.
    if not parsedFlags and filesystem.isfile(fullPath) then
        local parked, parkedRaw = decodeFile(atomic.tempPathFor(fullPath))
        if parked and parkedRaw then
            parsedFlags = parked
            -- put it back where it belongs so the next load reads it straight
            pcall(atomic.write, dir, fullPath, parkedRaw)
        end
    end

    if not parsedFlags then
        if raw then
            log.warn("Rayfield: Configuration file has an invalid format, backing up and resetting")
            local backupPath = backupPathFor(fullPath)
            pcall(function()
                filesystem.ensureDir(dir)
                filesystem.writefile(backupPath, raw)
                filesystem.delfile(fullPath)
            end)
        end
        return false
    end

    local flags = parsedFlags :: { [string]: unknown }
    local ignored = ignoreSet(window)
    local wasLoading = window._loading
    window._loading = true
    -- the reset must survive a throwing restore, or autosave stays suppressed all session
    local applyOk, applyErr = pcall(function()
        for _, entry in orderedControls(window) do
            if not ignored[entry.flag] then
                persistenceConfig.applyTo(entry.control, flags[entry.flag])
            end
        end
    end)
    -- back to what it was, not just down: a nested load from a control callback must leave
    -- the outer load's guard standing
    window._loading = wasLoading
    if not applyOk then
        log.warn("Rayfield: Failed to apply configuration - " .. tostring(applyErr))
    end

    -- kept so elements built after this load can still restore themselves (see
    -- Window:_restoreLate). without it a late element shows its default and the next
    -- autosave writes that default over the saved value.
    window._loadedConfig = flags
    window._loadedConfigPath = fullPath

    return true
end

-- restore one control from a decoded config. callers own the window._loading guard.
function persistenceConfig.applyTo(control: PersistedControl, value: unknown)
    if value == nil and not control._canBeNil then
        return
    end
    local ok, err = pcall(function()
        local deserialize = control._deserialize
        if deserialize then
            deserialize(control, value)
        else
            control:Set(value)
        end
    end)
    if not ok then
        log.warn("Rayfield: Failed to restore flag '" .. tostring(control.flag) .. "' - " .. tostring(err))
    end
end

-- Clipboard export/import - a text-based sibling to the file-based save/load above, for sharing
-- a config outside the executor's own file system (Discord, a text box, etc). Encodes to the
-- exact same flags-JSON shape .save() writes to disk, so a string round-trips through either
-- path interchangeably.
function persistenceConfig.encode(window: ConfigWindow): (boolean, string?)
    local ok, encoded = pcall(variables.httpService.JSONEncode, variables.httpService, collectFlags(window))
    if not ok then
        log.warn("Rayfield: Failed to encode configuration - " .. tostring(encoded))
        return false, nil
    end
    return true, encoded
end

-- Most executors that support setclipboard (writing out) don't support any reliable way to
-- *read* the clipboard back in - unlike setclipboard, a getclipboard-shaped function was never
-- something most executors converged on exposing. Importing from pasted text instead sidesteps
-- that entirely: a native Roblox TextBox already accepts a normal OS paste (Ctrl+V) with no
-- executor API involved, so the player pastes into an ordinary input field and this just parses
-- whatever text ended up there - the same reason config import UIs across this kind of library
-- tend to be "paste into a box" rather than "click an import button that reads the clipboard".
function persistenceConfig.decode(raw: string): { [string]: unknown }?
    if type(raw) ~= "string" or raw == "" then
        return nil
    end
    local ok, parsed = pcall(variables.httpService.JSONDecode, variables.httpService, raw)
    if not ok or type(parsed) ~= "table" then
        return nil
    end
    return parsed :: { [string]: unknown }
end

-- Apply a decoded flags table to every currently-built control, same restore path .load() uses
-- (applyTo below, guarded by window._loading the same way) - just skipping the file read/write
-- either side of it.
function persistenceConfig.applyFlags(window: ConfigWindow, flags: { [string]: unknown }): boolean
    local ignored = ignoreSet(window)
    local wasLoading = window._loading
    window._loading = true
    local applyOk, applyErr = pcall(function()
        for _, entry in orderedControls(window) do
            if not ignored[entry.flag] then
                persistenceConfig.applyTo(entry.control, flags[entry.flag])
            end
        end
    end)
    window._loading = wasLoading
    if not applyOk then
        log.warn("Rayfield: Failed to apply configuration - " .. tostring(applyErr))
    end
    return applyOk
end

function persistenceConfig.list(window: ConfigWindow): { string }
    local dir = persistenceConfig.getPath(window)

    local names: { string } = {}
    local ok, files = pcall(filesystem.listfiles, dir)
    if not ok or type(files) ~= "table" then
        return names
    end

    for _, filePath in files do
        local file = path.basename(filePath)
        -- listfiles returns folders and anything else in the dir; only our own configs are
        -- real names, so require the extension rather than listing whatever is lying around
        if file:sub(-5) == ".rfld" then
            local base = path.stripExtension(file, ".rfld")
            if base and base ~= "" and not base:find(" %(Incorrect Format[^%)]*%)$") then
                table.insert(names, base)
            end
        end
    end

    table.sort(names)
    return names
end

function persistenceConfig.delete(window: ConfigWindow, name: unknown): boolean
    if type(name) ~= "string" or name == "" then
        return false
    end

    local _, fullPath = persistenceConfig.getPath(window, name)
    if not filesystem.usable() or not filesystem.isfile(fullPath) then
        return false
    end

    -- take the parked copy with it, or a later load could resurrect what was just deleted
    pcall(filesystem.delfile, atomic.tempPathFor(fullPath))

    return (pcall(filesystem.delfile, fullPath))
end

return persistenceConfig
]=====]

sources["utility/persistencePaths"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local variables = require(script.Parent.variables)
local path = require(script.Parent.path)

local paths = {}

type ConfigWindow = {
    configuration: {
        fileName: string?,
        customFolder: string?,
        scopeByPlace: boolean?,
    },
    name: string,
}

-- PlaceId, or a Studio-safe stand-in (PlaceId reads 0 there) built from GameId instead - so
-- scopeByPlace still gives distinct, stable folders per Studio place rather than every one of
-- them colliding on the same "0".
local function placeFolderName(): string
    if game.PlaceId ~= 0 then
        return tostring(game.PlaceId)
    end
    return "Studio_" .. tostring(game.GameId)
end

function paths.getConfigPath(window: ConfigWindow, name: unknown?): (string, string)
    local dir = variables.fileSystemManager:getPath("Configurations")
    if window.configuration.customFolder then
        dir = path.join(dir, path.sanitizeFolder(window.configuration.customFolder))
    end
    -- scopeByPlace: nests one folder deeper per game/place, so a multi-place experience (or a
    -- hub-style script reused across several games) never mixes one place's saved configs into
    -- another's just because they happened to share a fileName/customFolder. Opt-in (see its own
    -- WindowProps comment) rather than the default, since flipping it on for an existing window
    -- would silently orphan whatever was already saved at the old, unscoped path.
    if window.configuration.scopeByPlace then
        dir = path.join(dir, path.sanitizeFolder(placeFolderName()))
    end
    local base = name or window.configuration.fileName or window.name
    local safe = path.sanitizeFile(base)
    if safe == "" then
        safe = path.sanitizeFile(window.name)
    end
    if safe == "" then
        safe = "Configuration"
    end
    return dir, path.join(dir, safe .. ".rfld")
end

function paths.getSettingsPath(): (string, string)
    local dir = variables.fileSystemManager:getPath("Settings")
    return dir, path.join(dir, "rayfield.rfld")
end

return paths
]=====]

sources["utility/persistenceSettings"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local variables = require(script.Parent.variables)
local filesystem = require(script.Parent.filesystem)
local paths = require(script.Parent.persistencePaths)
local atomic = require(script.Parent.persistenceWrite)
local enums = require(script.Parent.enums)

local persistenceSettings = {}

type SettingsWindow = {
    settings: {
        toggleKeybind: EnumItem,
        mouseOverride: boolean,
        keepOnScreen: boolean,
        welcomeToast: boolean,
        haptics: boolean,
        soundEffects: boolean,
        uiScale: number,
        tourSeen: boolean,
        resizeGripEnabled: boolean,
        loadingAnimationEnabled: boolean,
        customWindowSize: { X: number, Y: number }?,
        windowPositions: { [string]: { X: number, Y: number } }?,
        -- where the collapsed pill was left, per window name, and where a HUD chip was dragged,
        -- per "window name/chip key" - same shape as windowPositions, same file
        collapsedPositions: { [string]: { X: number, Y: number } }?,
        hudPositions: { [string]: { X: number, Y: number } }?,
        theme: string?,
    },
}

type DecodedSettings = {
    toggleKeybind: { [number]: unknown }?,
    mouseOverride: unknown?,
    keepOnScreen: unknown?,
    welcomeToast: unknown?,
    haptics: unknown?,
    soundEffects: unknown?,
    uiScale: unknown?,
    tourSeen: unknown?,
    resizeGripEnabled: unknown?,
    loadingAnimationEnabled: unknown?,
    customWindowSize: { X: unknown?, Y: unknown? }?,
    windowPositions: { [unknown]: unknown }?,
    collapsedPositions: { [unknown]: unknown }?,
    hudPositions: { [unknown]: unknown }?,
    theme: unknown?,
}

-- A decoded { [name] = { X = n, Y = n } } map, with anything that isn't that dropped. Shared by
-- the three position maps (window, collapsed pill, HUD chip): a settings file is a plain text file
-- on the executor's disk, so every value in it is whatever was last written there, not a promise.
local function readPositionMap(raw: unknown?): { [string]: { X: number, Y: number } }?
    if type(raw) ~= "table" then
        return nil
    end
    local positions: { [string]: { X: number, Y: number } } = {}
    for name, position in raw :: { [unknown]: unknown } do
        if type(name) == "string" and type(position) == "table" then
            local x, y = (position :: any).X, (position :: any).Y
            if type(x) == "number" and type(y) == "number" then
                positions[name] = { X = x, Y = y }
            end
        end
    end
    return positions
end

function persistenceSettings.getSettingsPath(): (string, string)
    return paths.getSettingsPath()
end

function persistenceSettings.saveSettings(window: SettingsWindow): boolean
    local dir, fullPath = persistenceSettings.getSettingsPath()

    local data: { [string]: unknown } = {
        toggleKeybind = {
            tostring(window.settings.toggleKeybind.EnumType),
            window.settings.toggleKeybind.Value,
        } :: { unknown },
        mouseOverride = window.settings.mouseOverride,
        keepOnScreen = window.settings.keepOnScreen,
        welcomeToast = window.settings.welcomeToast,
        haptics = window.settings.haptics,
        soundEffects = window.settings.soundEffects,
        uiScale = window.settings.uiScale,
        tourSeen = window.settings.tourSeen,
        resizeGripEnabled = window.settings.resizeGripEnabled,
        loadingAnimationEnabled = window.settings.loadingAnimationEnabled,
        -- nil (never manually resized, or reset via the grip's double-click) just omits the key -
        -- JSONEncode drops a nil value, and the decode side already treats a missing key as "no
        -- saved size", so there's nothing extra to do to represent "not set" on either end.
        -- the built-in theme the player picked in Settings, by name
        theme = window.settings.theme,
        customWindowSize = window.settings.customWindowSize,
        -- keyed by window name: this file is shared by every hub on the executor, and one hub's
        -- window must not open where another's was left
        windowPositions = window.settings.windowPositions,
        collapsedPositions = window.settings.collapsedPositions,
        hudPositions = window.settings.hudPositions,
    }

    local ok, encoded = pcall(variables.httpService.JSONEncode, variables.httpService, data)
    if not ok then
        return false
    end

    local writeOk = pcall(atomic.write, dir, fullPath, encoded)

    if not writeOk then
        return false
    end

    return true
end

-- Decode the settings file. Also hands back the raw text, so a parked copy can be put back.
local function decodeFile(fullPath: string): (DecodedSettings?, string?)
    local fileExists = false
    pcall(function()
        fileExists = filesystem.isfile(fullPath)
    end)
    if not fileExists then
        return nil, nil
    end

    local readOk, contents = pcall(filesystem.readfile, fullPath)
    if not readOk or type(contents) ~= "string" then
        return nil, nil
    end

    local decodeOk, parsed = pcall(variables.httpService.JSONDecode, variables.httpService, contents)
    -- JSONDecode happily returns scalars; a corrupt file must not brick CreateWindow
    if not decodeOk or type(parsed) ~= "table" then
        return nil, contents
    end

    return parsed :: DecodedSettings, contents
end

function persistenceSettings.loadSettings(window: SettingsWindow): boolean
    local dir, fullPath = persistenceSettings.getSettingsPath()

    local settings = decodeFile(fullPath)

    -- a save that died mid-overwrite leaves its whole copy parked beside the wreck, so take that
    if not settings then
        local parked, parkedRaw = decodeFile(atomic.tempPathFor(fullPath))
        if parked and parkedRaw then
            settings = parked
            -- put it back where it belongs so the next load reads it straight
            pcall(atomic.write, dir, fullPath, parkedRaw)
        end
    end

    if not settings then
        return false
    end

    if settings.toggleKeybind then
        pcall(function()
            local enumName = tostring(settings.toggleKeybind[1]):gsub("^Enum%.", "")
            local enumType = (Enum :: any)[enumName]
            if enumType then
                local enumItem = enums.itemFromValue(enumType, settings.toggleKeybind[2])
                if enumItem then
                    window.settings.toggleKeybind = enumItem
                end
            end
        end)
    end

    if type(settings.mouseOverride) == "boolean" then
        window.settings.mouseOverride = settings.mouseOverride
    end

    if type(settings.keepOnScreen) == "boolean" then
        window.settings.keepOnScreen = settings.keepOnScreen
    end

    if type(settings.welcomeToast) == "boolean" then
        window.settings.welcomeToast = settings.welcomeToast
    end

    if type(settings.haptics) == "boolean" then
        window.settings.haptics = settings.haptics
    end

    if type(settings.soundEffects) == "boolean" then
        window.settings.soundEffects = settings.soundEffects
    end

    if type(settings.uiScale) == "number" then
        window.settings.uiScale = math.clamp(settings.uiScale, 85, 115)
    end

    if type(settings.tourSeen) == "boolean" then
        window.settings.tourSeen = settings.tourSeen
    end

    if type(settings.resizeGripEnabled) == "boolean" then
        window.settings.resizeGripEnabled = settings.resizeGripEnabled
    end

    if type(settings.loadingAnimationEnabled) == "boolean" then
        window.settings.loadingAnimationEnabled = settings.loadingAnimationEnabled
    end

    if type(settings.theme) == "string" and settings.theme ~= "" then
        window.settings.theme = settings.theme
    end

    window.settings.windowPositions = readPositionMap(settings.windowPositions) or window.settings.windowPositions
    window.settings.collapsedPositions = readPositionMap(settings.collapsedPositions)
        or window.settings.collapsedPositions
    window.settings.hudPositions = readPositionMap(settings.hudPositions) or window.settings.hudPositions

    if type(settings.customWindowSize) == "table" then
        local x, y = settings.customWindowSize.X, settings.customWindowSize.Y
        if type(x) == "number" and type(y) == "number" then
            window.settings.customWindowSize = { X = x, Y = y }
        end
    end

    return true
end

return persistenceSettings
]=====]

sources["utility/persistenceWrite"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Crash-safe writes for the persistence layer.

local filesystem = require(script.Parent.filesystem)

local persistenceWrite = {}

local parkedExtension = ".saving"

-- Where a save parks its new copy while it works.
function persistenceWrite.tempPathFor(fullPath: string): string
    return fullPath .. parkedExtension
end

-- Executors give us no rename, so this is the next best thing: park a whole copy beside the
-- real file, read it back, then overwrite. Die mid-overwrite and the parked copy is still
-- intact for the next load to pick up. Throws on failure, callers pcall.
function persistenceWrite.write(dir: string, fullPath: string, contents: string)
    local tempPath = persistenceWrite.tempPathFor(fullPath)

    filesystem.ensureDir(dir)
    filesystem.writefile(tempPath, contents)

    -- a short read back means the disk is full or gone. stop here rather than shred the real file
    if filesystem.readfile(tempPath) ~= contents then
        error("parked copy did not write cleanly")
    end

    filesystem.writefile(fullPath, contents)
    pcall(filesystem.delfile, tempPath)
end

return persistenceWrite
]=====]

sources["utility/richtext"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Roblox RichText, written for you. A style table ({ color = "success", bold = true }) becomes the
-- tags a TextLabel understands, and the text inside it is escaped first, so a log line that happens
-- to contain "a < b" still reads as "a < b" rather than swallowing the rest of the row as a tag.
--
-- Colours can be a Color3, a hex string ("#ffcc00"), a name that follows the window's theme
-- (accent, text, muted, title), or one of the fixed names below. The fixed ones come in pairs: a
-- log panel is nearly black under most themes and white under Frost, and one green cannot be
-- legible on both. Which one is used is decided by the surface the text is drawn on, not the theme's
-- name, so a hand-written theme gets the right half too.

local richtext = {}

local escapes = { ["&"] = "&amp;", ["<"] = "&lt;", [">"] = "&gt;" }
local unescapes = { amp = "&", lt = "<", gt = ">", quot = '"', apos = "'" }

-- { on a dark surface, on a light one }
local palette: { [string]: { Color3 } } = {
    success = { Color3.fromRGB(96, 208, 138), Color3.fromRGB(22, 122, 68) },
    green = { Color3.fromRGB(96, 208, 138), Color3.fromRGB(22, 122, 68) },
    warning = { Color3.fromRGB(240, 186, 70), Color3.fromRGB(158, 102, 0) },
    yellow = { Color3.fromRGB(240, 214, 90), Color3.fromRGB(140, 112, 0) },
    orange = { Color3.fromRGB(245, 150, 70), Color3.fromRGB(180, 84, 16) },
    error = { Color3.fromRGB(240, 96, 96), Color3.fromRGB(186, 38, 38) },
    red = { Color3.fromRGB(240, 96, 96), Color3.fromRGB(186, 38, 38) },
    info = { Color3.fromRGB(104, 172, 255), Color3.fromRGB(28, 96, 198) },
    blue = { Color3.fromRGB(104, 172, 255), Color3.fromRGB(28, 96, 198) },
    cyan = { Color3.fromRGB(94, 212, 220), Color3.fromRGB(0, 126, 142) },
    purple = { Color3.fromRGB(182, 134, 255), Color3.fromRGB(104, 56, 198) },
    pink = { Color3.fromRGB(245, 126, 192), Color3.fromRGB(184, 44, 128) },
    gray = { Color3.fromRGB(154, 154, 154), Color3.fromRGB(110, 110, 110) },
    grey = { Color3.fromRGB(154, 154, 154), Color3.fromRGB(110, 110, 110) },
    white = { Color3.fromRGB(255, 255, 255), Color3.fromRGB(28, 28, 28) },
    black = { Color3.fromRGB(28, 28, 28), Color3.fromRGB(255, 255, 255) },
}

-- names that follow whatever theme is running, rather than a fixed colour
local themeKeys: { [string]: string } = {
    accent = "AccentColor",
    text = "ContentColor",
    muted = "PlaceholderColor",
    title = "TitlingColor",
}

-- Escape what a player's own text might contain. Only the three characters that can start a tag or
-- an entity: quotes are only special inside a tag we write ourselves.
function richtext.escape(text: string): string
    if not string.find(text, "[&<>]") then
        return text -- the common case, and gsub on every log line is not free
    end
    return (string.gsub(text, "[&<>]", escapes))
end

-- Markup back to what it reads as on screen, for Get()/Copy(): tags out, entities back.
function richtext.strip(markup: string): string
    local text = string.gsub(markup, "<[^<>]*>", "")
    text = string.gsub(text, "&(%a+);", function(name)
        return unescapes[name]
    end)
    text = string.gsub(text, "&#(%d+);", function(code)
        local number = tonumber(code)
        return if number then utf8.char(number) else nil
    end)
    return text
end

-- Luminance, the same rough weighting utility/colors.luau uses to pick black or white text.
function richtext.isLight(color: Color3?): boolean
    if typeof(color) ~= "Color3" then
        return false
    end
    return (color.R * 0.299 + color.G * 0.587 + color.B * 0.114) > 0.55
end

local function fromHex(text: string): Color3?
    local hex = string.match(text, "^#?(%x+)$")
    if not hex then
        return nil
    end
    if #hex == 3 then -- "#fc0", the way CSS allows it
        hex = string.gsub(hex, "(%x)", "%1%1")
    end
    if #hex ~= 6 then
        return nil
    end
    local r = tonumber(string.sub(hex, 1, 2), 16)
    local g = tonumber(string.sub(hex, 3, 4), 16)
    local b = tonumber(string.sub(hex, 5, 6), 16)
    if not r or not g or not b then
        return nil
    end
    return Color3.fromRGB(r, g, b)
end

-- `context` is { theme = <the window's theme table>, light = <is the surface light> }.
function richtext.color(value: any, context: { theme: { [string]: any }?, light: boolean? }?): Color3?
    if typeof(value) == "Color3" then
        return value
    end
    if type(value) ~= "string" or value == "" then
        return nil
    end

    local name = string.lower(value)
    local theme = context and context.theme
    local key = themeKeys[name]
    if key and theme and typeof(theme[key]) == "Color3" then
        return theme[key]
    end

    local pair = palette[name]
    if pair then
        return if context and context.light then pair[2] else pair[1]
    end

    return fromHex(value)
end

local function toHex(color: Color3): string
    return string.format(
        "%02X%02X%02X",
        math.clamp(math.round(color.R * 255), 0, 255),
        math.clamp(math.round(color.G * 255), 0, 255),
        math.clamp(math.round(color.B * 255), 0, 255)
    )
end

-- Wrap already-escaped text in the tags a style table asks for. Unknown colour names simply don't
-- paint anything: a typo'd colour should leave the line readable, not tear a hole in the row.
function richtext.wrap(text: string, style: { [string]: any }?, context: { [string]: any }?): string
    if type(style) ~= "table" then
        return text
    end

    local inner = text
    if style.strike or style.strikethrough then
        inner = "<s>" .. inner .. "</s>"
    end
    if style.underline then
        inner = "<u>" .. inner .. "</u>"
    end
    if style.italic then
        inner = "<i>" .. inner .. "</i>"
    end
    if style.bold then
        inner = "<b>" .. inner .. "</b>"
    end

    local attributes = ""
    local color = richtext.color(style.color, context)
    if color then
        attributes ..= ` color="#{toHex(color)}"`
    end
    if type(style.size) == "number" then
        attributes ..= ` size="{math.max(math.floor(style.size), 1)}"`
    end
    if type(style.transparency) == "number" then
        attributes ..= ` transparency="{math.clamp(style.transparency, 0, 1)}"`
    end
    if attributes ~= "" then
        inner = `<font{attributes}>{inner}</font>`
    end

    -- a highlight behind the text, the way a search hit reads in an editor
    local highlight = richtext.color(style.highlight, context)
    if highlight then
        inner = `<mark color="#{toHex(highlight)}" transparency="0.6">{inner}</mark>`
    end

    return inner
end

return richtext
]=====]

sources["utility/runtime"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local services = require(script.Parent.services)

export type RuntimeState = {
    secureMode: boolean,
    coreGui: CoreGui,
    workspace: Workspace,
    runService: RunService,
    userInputService: UserInputService,
    guiService: GuiService,
    localPlayer: Player?,
    tweenService: TweenService,
    httpService: HttpService,
    textService: TextService,
    replicatedStorage: ReplicatedStorage,
    localizationService: LocalizationService,
    guiContainer: Instance,
    guiContainerSource: string, -- "PlayerGui" | "gethui" | "CoreGui", for the compatibility report
}

local runtime = {} :: RuntimeState

runtime.secureMode = (function()
    -- getgenv lives in the executor's script environment, not _G, same as gethui below
    if typeof(getgenv) ~= "function" then
        return false
    end
    local ok, val = pcall(function()
        return getgenv().RAYFIELD_SECURE
    end)
    return ok and val == true
end)()

runtime.coreGui = services.getService("CoreGui") :: CoreGui
runtime.workspace = services.getService("Workspace") :: Workspace -- read for CurrentCamera
runtime.runService = services.getService("RunService") :: RunService
runtime.userInputService = services.getService("UserInputService") :: UserInputService
runtime.guiService = services.getService("GuiService") :: GuiService
runtime.localPlayer = (services.getService("Players") :: Players).LocalPlayer
runtime.tweenService = services.getService("TweenService") :: TweenService
runtime.httpService = services.getService("HttpService") :: HttpService
runtime.textService = services.getService("TextService") :: TextService
runtime.replicatedStorage = services.getService("ReplicatedStorage") :: ReplicatedStorage
runtime.localizationService = services.getService("LocalizationService") :: LocalizationService
-- Where every ScreenGui this library builds is parented. Tried in order and *verified*, not
-- assumed: a gethui stub that hands back nil parents everything nowhere, and an executor whose
-- thread can't write to CoreGui throws on the assignment - either way the whole interface would
-- simply never appear, with nothing on screen to say why. Parenting a throwaway ScreenGui and
-- checking it stuck costs one instance at startup and turns both cases into a fallback.
local function canParentTo(container: Instance?): boolean
    if container == nil then
        return false
    end
    local ok, landed = pcall(function()
        local probe = Instance.new("ScreenGui")
        probe.Enabled = false
        probe.Parent = container
        local stuck = probe.Parent == container
        probe:Destroy()
        return stuck
    end)
    return ok and landed == true
end

-- PlayerGui, however this client will give it up: FindFirstChildOfClass is the right call and a
-- plain index is what answers where that method is not there (a test harness, an old shim).
local function playerGuiOf(player: Player?): Instance?
    if player == nil then
        return nil
    end
    local ok, gui = pcall(function()
        return (player :: any):FindFirstChildOfClass("PlayerGui")
    end)
    if ok and gui then
        return gui
    end
    local direct, value = pcall(function()
        return (player :: any).PlayerGui
    end)
    return if direct and value then value else nil
end

runtime.guiContainerSource = "CoreGui"
runtime.guiContainer = (function(): Instance
    local playerGui = playerGuiOf(runtime.localPlayer)

    if runtime.runService:IsStudio() and playerGui then
        runtime.guiContainerSource = "PlayerGui"
        return playerGui
    end

    if typeof(gethui) == "function" then
        local ok, container = pcall(gethui)
        if ok and typeof(container) == "Instance" and canParentTo(container) then
            runtime.guiContainerSource = "gethui"
            return container
        end
    end

    if canParentTo(runtime.coreGui) then
        runtime.guiContainerSource = "CoreGui"
        return runtime.coreGui
    end

    -- Last resort, and the one that always works from a plain LocalScript: the player's own
    -- PlayerGui. The window is visible either way, which is the whole point.
    if playerGui then
        runtime.guiContainerSource = "PlayerGui"
        return playerGui
    end

    runtime.guiContainerSource = "CoreGui"
    return runtime.coreGui
end)()

return runtime
]=====]

